/* 令和7年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r07.committeeSessions.push(...[{"id":"r07-20250825-5","meetingId":"r07-cm08","date":"2025年8月25日","dateIso":"2025-08-25","committee":"総務委員会","time":"午後 １時００分～午後 ３時３２分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を43件整理しています。","topics":[{"id":"topic-01","title":"令和７年度都区財政調整交付金当初算定結果","agenda":"令和７年度都区財政調整交付金当初算定結果","exchanges":[{"speaker":"西本委員","kind":"質問","question":"これもう少し説明してほしいということと、３００億円積み増しになった予算になっているのですが、どのような影響があるのか。実際それが区に来たときにどのような差があるのか、予定どおりという形で、その見立てはどうなっているのかなということをまず説明を求めました。","respondent":"加島財政課長","answer":"配分割合の変更は５５.１％から５６％になりましたので、結果といたしまして、今歳入は２０億円増となる見込みです。ちなみに、今日２０億円増という動きは、令和６年度当初予算も同様の動きをしておりましたので、今後最終補正で対応してまいりたいと考えております。","id":"exchange-001"},{"speaker":"西本委員","kind":"質問","question":"というものを教えてほしいのです。補助金があったとしてもできないのだなどというようなことが起きているのではないかなと想像するのですが、その辺はいかがか尋ねました。","respondent":"加島財政課長","answer":"それに対して、特定財源のほうが７億円ほど入ってまいります。国のほうがそこに財源を手当てしていくことによって、全ての子どもの食の確保というものが図られる、そのように考えているものです。","id":"exchange-002"},{"speaker":"西本委員","kind":"質問・要望","question":"その辺の考え方というか、要望の仕方などというものは、動向的にはどうなのでしょうか。その後２３区の中でやっていこうとすると、どのような考え方で、この財調も含めての交渉に当たっているのかを教えてほしいです。","respondent":"加島財政課長","answer":"特別区２３区間で等しく事務を行うことができるように、水平調整という役割を担っているものが都区財政調整になります。その中でこれだけ都区や特別区全体での実施事業の数や、実施している区の数などということ、予算編成に至っても同様です。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"先ほど交付金の割合ですか、これが今まで５５.１％から５６％に増えた、これはまた元へ戻ってしまうということですか。この割合、今増えたのですが、その辺についてご見解を説明を求めました。","respondent":"加島財政課長","answer":"１点目が今後のフレームの動きというところなのですけれども、率直なところ、この間の数字の動きからして否定はできないと考えております。これは設置区は、令和８年度に開設予定の１２区分までを見込んだ財源規模をカバーできるものとなっておりますので…","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問・要望","question":"恐らくその先、もっと超えるのではないかと思うのですが、そちらのほうもやはりしっかり、財政課としての立場として、私はしっかり見てほしいのです。やはりそれを多くの区民の方に区民サービスとして回せるような努力をしていただきたいと私は思うのですが、ご見解を説明を求めました。","respondent":"加島財政課長","answer":"庁舎整備基金と、それから起債によって、財源を調達する方針を令和７年度予算の中で提出させていただいたところになります。そういったものできちんと品川区のほうが財政の不健全化に陥らないよう運営はしてまいりたいと考えております。","id":"exchange-005"},{"speaker":"須貝委員","kind":"質問・要望","question":"質問が悪かったと思うのですが、ちょっと意見だけ言わせていただきます。何ですか、できるだけ費用のかからないような、そのような仕組みに目を光らせてやってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問","question":"品川区はそこをどう考えているのかということと、４年間にわたって品川区に入ってくるというか、そのような形になってくると思うのです。ですから、どこの部分になってくるのかということがあるのか伺いたいと思うのですけれども、お願いします。","respondent":"加島財政課長","answer":"再開発を行った際の財調での引き当て分というところですけれども、このフレームの中で直接的に表されているものはございません。全て基準財政需要額の概算値の中で算定を行っているところです。","id":"exchange-007"},{"speaker":"石田（ち）委員","kind":"意見","question":"私は再開発が進むことで周辺の地価が上がることで、そうするとやはり住み続けられる品川ということではなくなっていく、今住んでいる方にとっては。一旦立ち止まる、そういった視点が必要なのではないかなと思いますので…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"山本委員","kind":"質問・要望","question":"品川区として要望した項目として、何か特徴的なものなど、こういったものを要望しているのですなどというものがあれば教えてほしいと求めました。それで、全体何項目ぐらい出されて、その中でどのように要望が通ったのかという状況が分かれば教えてほしいと求めました。","respondent":"加島財政課長","answer":"それから２３区の水平調整がどのように都区財政調整の中で図られているかというところですけれども、補正係数というものがあります。それぞれの区の状況に応じた係数で財政需要額というものを出しておりますので、そこで水平調整が図られているような状況です。","id":"exchange-009"},{"speaker":"山本委員","kind":"提案","question":"過去の委員会で品川区として提案していた数などが質疑になっていたので、知りたかったのですけれども、また別途確認させていただきたいと思いました。２３区が足並みそろえて都には要望していくということなのですけれども…","respondent":"加島財政課長","answer":"この表でいきますと、そこで児童相談所を設置した区が、それに係る経費を需要額として算定しております。つまり、設置していない区についてはそこの算定はゼロになりますので、それで図られているような形になります。","id":"exchange-010"},{"speaker":"山本委員","kind":"質問・要望","question":"区民に身近な基礎自治体、今後も配分がさらに充実を、区側の配分が充実したものとなるよう取り組んでいただきたいと考えています。その費用もかさんでまいりますので、その予算の効率的な使い方については、一層ご検討いただきたいと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"}]},{"id":"topic-02","title":"しながわ中央公園ナイター照明ＬＥＤ化その他電気設備工事請負契約","agenda":"しながわ中央公園ナイター照明ＬＥＤ化その他電気設備工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"１億五、２社共同企業体という形を取っているのですが、それだけの規模なのですか。説明を求めました。","respondent":"佐藤経理課長","answer":"ＪＶにつきましては、区内の中小企業の育成や受注機会の確保、そういったところを目的といたしまして、従前から行っているところです。本件につきましても、もちろん１社でも受けるところはあろうかと思いますけれども、今申し上げたとおりですので…","id":"exchange-012"},{"speaker":"須貝委員","kind":"意見","question":"経理課として、入札に入ってもらうとか、やはりそのような考え方というものは私は持つべきではないかなと思います。これは意見だけですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"西本委員","kind":"質問","question":"今回は、ランニングコストなどというものは変わってくると思うのですが、これの計算というものはどのような形でされていますか。かなり省エネ化されるのか、どうなのか尋ねました。","respondent":"佐藤経理課長","answer":"所管から聞いているというところでお答えいたしますけれども、ＬＥＤ化照明にするによって、従前から電気料は低減されると。今回この工事におきましては、率にして４３％ほど低減するというように聞いております。","id":"exchange-014"},{"speaker":"西本委員","kind":"質問","question":"今これだけ見ても４０％以上が削減できるということなので、かなり期待はしているのですけれども、どのような見立てをしているのでしょうか。全体のお話を聞ければと思います。","respondent":"佐藤経理課長","answer":"公園灯全体におきましては、ほぼ９５％程度進んでおりまして、あと５％程度というように聞いております。同様のナイター照明のＬＥＤ化については、あとしながわ南ふ頭公園が残るのみとなるというように聞いております。","id":"exchange-015"}]},{"id":"topic-03","title":"デジタルプラットフォームの実施","agenda":"デジタルプラットフォームの実施","exchanges":[{"speaker":"澤田委員","kind":"質問","question":"高齢者の方でもＬＩＮＥだと割とやっている方も多いので、そこから入れるということはとても意見を集めるのに有効なのかなと思います。あれにもっと、今以上力を入れていったりということが必要だと思うのですけれども、それについてはどうお考えか尋ねました。","respondent":"與那嶺戦略広報課長","answer":"デジタルデバイド対策といいますか、ふだんから、いわゆるインターネットなどの機能を活用されない方に対しての対応です。今回これはちょっとこのしながわ防災区民憲章の個別の対応にはなるのですけれども、並行してできるようにという形で工夫をしています。","id":"exchange-016"},{"speaker":"澤田委員","kind":"質問","question":"やはり今後のことを考えると、今移行期で、しっかりとデジタルに慣れていただくということにもより一層力を入れていただけたらと思います。もし取っていこうというのであれば、今品川区だったらｉＰａｄを皆１人１台持っているので、その辺りについてはどうか尋ねました。","respondent":"與那嶺戦略広報課長","answer":"まさにおっしゃるとおりで、今小・中学生の、そういったスマートフォンなどの利用の比率というものは相当高いというようには認識しています。まずはこういったことを知ってもらうというところから始めて、多くの方に参加していただくというところの取組ではないかと考えています。","id":"exchange-017"},{"speaker":"澤田委員","kind":"質問","question":"すみません。ｉＰａｄを利用するということは今のところ考えていないという感じなのか尋ねました。","respondent":"與那嶺戦略広報課長","answer":"こちら利用するに当たっては、ｉＰａｄからインターネットを経由してできます。当然のように、これが使うことを前提として考えています。","id":"exchange-018"},{"speaker":"山本委員","kind":"質問・要望","question":"これがいいというところに決まったという、その選定理由を教えてほしいと求めました。それから、具体的にはどのように指名ということを考えていらっしゃるか、分かっていれば教えてほしいと求めました。","respondent":"與那嶺戦略広報課長","answer":"まさにこの事業全体、デジタルを通じた区政への参加を進めていくというところの、昨年の試行実施の際の分析も非常に熱心にやってくれたのです。今まさに事業所管である防災課と考え方をまとめているところなのですけれども、そういった構成について…","id":"exchange-019"},{"speaker":"山本委員","kind":"質問・要望","question":"ワークショップのほうもうまく連携して進めていただきたいと考えています。意見募集の結果についてもより多くの方々に知っていただきたいというところもあるのですが、その出し方のところなど、お考えがあれば説明を求めました。","respondent":"與那嶺戦略広報課長","answer":"素案のパブリックコメントを実施するであるとか、最終的には３月１１日に実際のものを出す、これは１つの成果になろうかと思います。ワークショップの実施経過などをレポートに最後まとめますので、または区ホームページなどでご報告できるという形で進めていこうと考えています。","id":"exchange-020"},{"speaker":"山本委員","kind":"質問","question":"１００件よりももっと多くの方々の意見を集められたらいいのかなと思っていますので、多くの意見が集まることを期待したいと考えています。最後に個別テーマの検討ですけれども、既に次に何かお考え、予定しているものなどがあれば教えてほしいと求めました。","respondent":"與那嶺戦略広報課長","answer":"個別のテーマについては、内部ではいろいろな候補が挙がっているところではあるのですけれども、まだそこがご報告できるほど煮詰まっていないということが正直なところですので、機を見て改めてご報告をさせていただければと思っています。","id":"exchange-021"},{"speaker":"須貝委員","kind":"質問・要望","question":"やはりその前に一歩立ち止まって、どうしたらもっと多くの方の意見が聞けるということを考えてほしいと求めましたが、ご見解をお聞かせください。私は無理にデジタルプラットフォームの実施を急いで進めるべきではないと思いますが、その辺についてご見解を説明を求めました。","respondent":"與那嶺戦略広報課長","answer":"こちらは一昨年度実施をいたしまして、これも事実ですので、またこれは１つ考えなければならないというところだと考えています。あなたの声によって区政がこう変わりましたよというような実感を持っていただくようなことが１つ成果としてあったのかなというように進めていきたい…","id":"exchange-022"},{"speaker":"須貝委員","kind":"質問・要望","question":"ですけれども、課長もお若いですから分からないと思うのですが、打ち込むのにやはり小さいのです。それは費用としてかかってしかるべき、合理化を進めて、継続できるようにしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"西本委員","kind":"確認","question":"１つはマイナーな意見などが出てきた場合や、あとは炎上するなど、そのようなことはあり得るのでしょうか。パブリックコメントをもらって、まさかこれだけで、このプラットフォームだけでこれを決めるのではないですよねということを確認させてください。","respondent":"與那嶺戦略広報課長","answer":"我々区や、そこは本当にひどい意見があった場合については、そこの投稿を削除するような対応を取ることもあります。ここのテーマに対して意見をいただきますというところを一定程度丁寧に説明した上で参加をしていただくというようなプロセスでいきますので。","id":"exchange-024"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、進めていただきたいと同時に、ユーチューブとかのところには宣伝があるではないですか。納得する形でつくっていただきたいという思いがありますので、その辺はよろしくお願いしたいと思いますが、いかがか尋ねました。","respondent":"與那嶺戦略広報課長","answer":"チェックはしてまいりますので、もちろんリスクマネジメントという観点もありますし、そこはしっかりと運営していきたいなと考えています。もう一つＳＭＳ対応での広告です。","id":"exchange-025"},{"speaker":"西本委員","kind":"意見","question":"これは私も自分で言っていいのかどうかという、費用対効果も含めて、検討してほしいと求めました。意見ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"松本委員","kind":"確認","question":"ですから、そこの、まず本人確認を含めた投稿する人の特定の仕方を、今回はどこまで考えていらっしゃるのかというところが１点です。そこが大事ではないかと思っているので、今回はどのように考えていらっしゃるのか伺えればと思います。","respondent":"與那嶺戦略広報課長","answer":"あまりにもこれが、まず間口を広げるという考え方の下に、最低限の表示名とメールアドレスのみの取得という形で考えているところです。規定に対してもあらかじめ示した上での登録という形で流してまいりますので…","id":"exchange-027"},{"speaker":"石田（ち）委員","kind":"提案","question":"ですから、やはり周知の方法というものを、今様々ありましたけれども、ほかの皆さんからの提案が。分かれば教えていただきたいということと、あと、その今後を教えてほしいと求めました。","respondent":"與那嶺戦略広報課長","answer":"今回のワークショップの回数なのですけれども、まだ確定はしておりませんが、複数回実施する想定で、今相談をしている形です。それはこれからのテーマ設定の考え方になってくるのかなと考えています。","id":"exchange-028"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですから、私たちも広げていても分かるのですが、区としても様々な工夫をしていただきたいなと。それで今後のパブコメ、パブリックコメントなどもぜひ取れるような工夫も考えていただきたいなとは思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"塚本副委員長","kind":"質問","question":"設定するのかというところを１つお伺いしたいということと、区民、進んでいるところなどもあるようです。ですかち、有効なのではないかなと思いますけれども、そのフィードバックということについてはどのようなお考えなのか説明を求めました。","respondent":"與那嶺戦略広報課長","answer":"この事業の目的や防災区民憲章の考え方、それぞれのご意見をいただくというような段階を踏んでいくという形で、ページをつくっているところです。それはまた区民の皆さんにお返しするということで、参加の結果を見えるようにしていきたいと考えております。","id":"exchange-030"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"西本委員","kind":"質問","question":"いろいろな市区町村ありますが、このようなときには協定を結んでという何か目安的な考え方など、そのようなものはあるのでしょうか。それは今度どのようなほうに持っていって、品川区がどう活力を活用されるのかをお聞きしたいと思います。","respondent":"野口官民共創担当課長","answer":"令和７年結んだ自治体などは、やはりこのような連携事業というものは、今後協議を進めていければと考えています。","id":"exchange-031"},{"speaker":"西本委員","kind":"質問","question":"ですから、私の感覚だと、もう少しやりませんかという。そのようなところはいっぱいあると思うので、ぜひお願いしたいなと思いますが、いかがか尋ねました。","respondent":"野口官民共創担当課長","answer":"今いただいたお声を政策に反映できるよう、いろいろ協議、検討をしていきたいと思います。そして検討しつつ、その点も踏まえて内部で検討しつつ、そのような方たちも巻き込んで考えを進めていきたいと考えています。","id":"exchange-032"},{"speaker":"須貝委員","kind":"質問・要望","question":"今回答すると、これだけ多々の自治体があるので、一遍にはできないと思うのですが、要望としてそのような資料をいただけるとありがたいなと思います。終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"山本委員","kind":"質問・要望","question":"実は、やはり多くの区民の方々にこういった都市と協定を結んでいることをまず知ってもらうことがいいのではないかなと思うのです。知ってもらうこと、それから相手をつなぐことを考えたらと思うのですけれども、いかがか尋ねました。","respondent":"野口官民共創担当課長","answer":"確かに委員おっしゃられる、そのようなところはどれぐらい効果があるかということを考えて進めていきたいと思います。それを進めていく上で、企業との連携を図っていくためということも改めて検討できればと考えています。","id":"exchange-034"},{"speaker":"山本委員","kind":"提案","question":"ご答弁ありがとうあります。ぜひそのような見やすく、分かりやすく、区民やメンバーの方から民間の皆様にご提案いただきたいということとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"},{"speaker":"松本委員","kind":"質問","question":"ですから、それで足りるのかどうなのかというところが、だからこのぐらいの連携をしているのだな」ということがつながっていくと思います。定量的なものというのは難しいとは思うのですけれども、そうしたところを区としても意識を持っていただけるとうれしいなと思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-036"},{"speaker":"塚本副委員長","kind":"質問","question":"３自治体と締結をされていて、それほど大きくそれぞれ変わらないというか、何かあったときはそれぞれ協力して支援し合いましょうというような。そもそも災害でお互いに連携し合って、災害時に支援し合いましょうというパターンというものもあるのかということを最初にお伺いしたいと思います。","respondent":"野口官民共創担当課長","answer":"この資料の１枚目にもありますように、高知県、坂井市に関しては包括的な協定が先にあると。ほかの自治体に関しては、それらに関してはすぐに災害時援助協定というものを締結しているということが現状です。","id":"exchange-037"},{"speaker":"塚本副委員長","kind":"意見","question":"災害援助協定というものはということを、地域的なことも含めて、この辺の地域とこれぐらいの数というようなものを計画的なものがあるのかということをお教えくださいとの意見を述べました。","respondent":"野口官民共創担当課長","answer":"そこのところも考えますと、そのような協定というものは１つの手段になると思うので、１つ考えるところではあるかなとは思います。","id":"exchange-038"},{"speaker":"塚本副委員長","kind":"質問","question":"自治体間の交流というところで、どのような方向性を区としては考えているのか。それ以上の、いろいろな形で交流を進めていきたいというようなことでの思いを持っていらっしゃるのか、そのようなところはいかがか尋ねました。","respondent":"野口官民共創担当課長","answer":"その後イベントというものを進めていることが実際というか、そのようなものを１つの契機として、イベント等でつながって人的な交流ができればとは思っております。","id":"exchange-039"},{"speaker":"石田（ち）委員","kind":"質問","question":"やはり３.１１以降など、この目的からすると、どの市町村とも広く交流はできるはずではないですか。それが、ではなぜなのかなということは、明確な基準的なものは本当にないのですかということを聞かせてください。","respondent":"野口官民共創担当課長","answer":"何か１つの基準をつくるということはなかなか難しいので、なかなかそこの点は難しいということが実情です。１つの基準というか、１つのベースになるかと思いますので、そのようにご理解いただければと思います。","id":"exchange-040"},{"speaker":"石田（ち）委員","kind":"質問","question":"災害のものはまあまああるなと、この資料を見ていて。これ２３区で見たとき、品川区というものはどのような感じなのか、分かれば説明を求めました。","respondent":"野口官民共創担当課長","answer":"お答えはできないところではあるのですけれども、いろいろな事業を進めていく中で、その先のほかの協定というものは選択肢の１つになり得るのではないかなと思います。","id":"exchange-041"},{"speaker":"石田（秀）委員長","kind":"質問・要望","question":"もう農園１つ借りるのが抽せんのようなものだった頃から、今なんか２個でも３個でも、どうぞやってくださいという感じではないですか。これではどうかなということもあるではないか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-042"}]},{"id":"topic-05","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"前回も申し上げたとおり、このたびは辞退します。それについては一緒に参加させていただけるなら、これは一緒に、この委員会の場で参加したいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/787454?Template=document&Id=7143#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":50123,"voices":107}},{"id":"r07-20250826-21","meetingId":"r07-cm08","date":"2025年8月26日","dateIso":"2025-08-26","committee":"子ども若者支援・共生社会推進特別委員会","time":"午後 １時００分～午後 ２時１６分","status":"正式会議録","sourceType":"formal","overview":"子ども若者支援・共生社会推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"公設民営保育園というのは、５園を民営化していくという方針になっていたと思うのですけれども、それがどこまで進んでいるのか伺いたいと思います。それから、運営委託されたところの保育士の待遇について、区としては把握されているのか、伺いたいと思います。","respondent":"芝野保育入園調整課長、染谷保育施設運営課長","answer":"三ツ木保育園、八潮北保育園、八潮西保育園、一本橋保育園、大井保育園、この５園が今、公設民営になっているというこです。こちらのほうに委託しています。 勤務される保育士の方の対応については、しっかりと十分な給与を支払いできるような体制を取って実施をしているものです。今後民設民営も進んでいくという中で、コストの面についてもしっかり確認をさせていただきながら…","id":"exchange-001"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そこら辺のところというのは実際どうなのかということを伺いたいのと、５園のうち社会福祉法人と株式会社が何園ずつなのかというのも教えてください。これからの計画というのですか、その後、そこら辺の今後の進め方というのもちょっと教えてほしいと求めました。","respondent":"染谷保育施設運営課長、芝野保育入園調整課長","answer":"同様の金額をお支払いしている中で、当然ながら給与という部分についても遜色ない形で、委託先のほうでお支払いいただいているというふうに認識しています。 これからの民営化の進め方ですが、公設民営として５年間運営させていただきまして、民設民営化に向けた検討を行っていくです。民営化ガイドラインには５園を示していますが、また改築等の契機を検証しながら…","id":"exchange-002"},{"speaker":"鈴木委員","kind":"確認","question":"５年間たった後で５園分をやるというのではなくて、１園が５年間だったら、１園ごとに検証するという形で進めていくということなのでしょうか。取りあえず今のところは５園というふうなことで、そこのところを確認させていただいていいかというのをお願いしたいと思います。","respondent":"芝野保育入園調整課長","answer":"５年たった段階で検証して、民設民営化のほうの検討を進めていくですので、５園を一遍にということではございません。民設民営化する場合にはまたご報告させていただきまして、効果検証のほうはそちらのほうでご説明させていただきたいと考えております。","id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問・要望","question":"５ページの２段落目のところ、令和８年度より国のこども誰でも通園制度が本格実施されるということで、そのことを教えてほしいと求めました。特に１・２歳児は、そこら辺のところの認識はどう考えられているのか、その点についても伺いたいと思います。","respondent":"芝野保育入園調整課長","answer":"ただし、今後の人口の推計も踏まえまして、本当につくるべきなのかどうかというのは慎重に検討していきたいというふうに考えております。いずれにいたしましても、しっかりと人口推計を確認してまいりまして、必要な確保方策を取っていきたいというふうに考えております。","id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問","question":"そうしますと、令和７年度が一番下で、この前提そのものが基本方針のときとは変わったというふうに捉えていいということなのでしょうか。改築に当たっての仮施設というのはどういうふうに確保するということで考えられているのか、その点についても伺います。","respondent":"芝野保育入園調整課長","answer":"品川区保育園等あり方基本方針は基本的には、こちらのほうはしっかりとやっていかなければいけないというふうに考えております。適切な施設を、仮設の園舎を建てられる施設をつくりまして、そちらで改築のほうを進めていきたいというふうに考えております。","id":"exchange-005"},{"speaker":"鈴木委員","kind":"質問","question":"そうしますと、統括園とかサポーター園とか、そういうのはこれからも検討は具体化していくということなのでしょうか。人口推計が変化したことによって統廃合のほうは、その推計に合わせて見直していくというふうなことで捉えていいのか、その点を伺いたいと思います。","respondent":"染谷保育施設運営課長、芝野保育入園調整課長","answer":"区内の１３圏域において、公立・私立で連携して、保育力の底上げを図る取組というのは現状も様々進めているところではあります。拠点としての役割というのは継続して担っていく中で、引き続き基本方針の具体化をしていく中で… 私からは、統廃合をどういうふうに進めていくかです。品川区保育園等あり方基本方針の中にあります統廃合を含めた再整備は、人口推計を見ながら、慎重に検討してまいりたいというふうに考えております。","id":"exchange-006"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それはそういう形で、区立保育園はぜひ統廃合しないでいただきたいということを意見として申し上げたいと思います。検証の結果を報告というのではなく、これ以上民営化の方向というのは進めないでいただきたいということも、意見として申し上げておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"澤田委員","kind":"確認","question":"幾つかお聞きしたいことがあるのですが、まずお伺いしたいのが、区立園であれば、障害児の受入れというのはマストだと思うのですけれども、私立保育園については、受け入れない園というのもあるのかというのを一度確認させていただいてもよろしいか尋ねました。","respondent":"佐藤保育事業担当課長","answer":"特別な支援が必要なお子様に関して、私立保育園で受け入れないということができるのかについてですけれども、新制度に移行して以降、応諾の義務がありますので、入園調整をさせていただいた結果、選ばれた園に関しましては、原則としてお受けいただいているというふうな認識です。","id":"exchange-008"},{"speaker":"澤田委員","kind":"質問","question":"新制度移行の私立保育園についてはという話だったのですけれども、新制度移行していないところについては選べるというか、その園の考え方によってはというところなのか尋ねました。","respondent":"佐藤保育事業担当課長","answer":"私立の認可保育園につきましては、全ての園で受入れをしていただいているというものでございまして、認可外の施設におきましては、様々な園の考え方や保護者の方の希望というのを併せながら、入園されていらっしゃるのではないかなというふうに考えております。","id":"exchange-009"},{"speaker":"澤田委員","kind":"質問・要望","question":"別の質問に移るのですけれども、ゼロ歳児というのは１歳児以降と違って、離乳食をつくる必要があると思うのです。私立園もどのくらいあるのかというのが分かれば教えていただきたいです。","respondent":"染谷保育施設運営課長、佐藤保育事業担当課長","answer":"ゼロ歳児園です。区立園で３２園あります。 私立保育園につきましても、ほぼ全ての園でゼロ歳児からお受けいただいておりまして、４園のみ１歳児からの園というふうになっております。","id":"exchange-010"},{"speaker":"澤田委員","kind":"意見","question":"４月の年度当初は４９１人だけれども、３月１日は７２９人と、定員をオーバーしたりするのです。ゼロ歳児の受入れというのを区立・私立ともに増やしていこうと思っていらっしゃるのかどうなのか、その辺の考えを聞かせてほしいと求めました。","respondent":"佐藤保育事業担当課長、芝野保育入園調整課長","answer":"面積の要件で、定員のほうが埋まってきた場合に、弾力枠を使って定員を増やすことができないかというような投げかけをさせていただいてあります。そちらにご協力いただいている園が複数ありますので… 区立保育園の件ですが、区立保育園は、定員ぎりぎりですが、こちらのほうは維持させていただき、また全体の定員の見直しの中で検討させていただきたいというふうに考えております。","id":"exchange-011"},{"speaker":"せらく委員","kind":"質問・要望","question":"確保方策について質問していきたいと思うのですけれども、結構細かく地域ごとに確保体制、提供体制が示されているのを確認しました。地域の実態を教えていただきたいと思いまして、１号認定の方がマイナスとなっていて、分かる範囲で教えてほしいと求めました。","respondent":"芝野保育入園調整課長","answer":"大崎地区の状況ですが、品川区こども計画上ではマイナスが生じたりしていますが、これは地区をまたいでお預けになっている方も多々おりますので、近隣の全体では十分満たしているというふうに考えておりまして、この計画が今つくられているところです。","id":"exchange-012"},{"speaker":"せらく委員","kind":"質問","question":"分かりました。そうなると、大崎地区で３歳から５歳児に対する今後の対策というのは特に考えていらっしゃらないということか尋ねました。","respondent":"芝野保育入園調整課長","answer":"対策というのは考えておりませんが、保育需要が高まって、しっかりとその対応をしていきたいというふうに考えております。現状ではそういう状況にはないです。","id":"exchange-013"},{"speaker":"せらく委員","kind":"質問","question":"本日の資料の６ページの区立保育園の再整備というところなのですけれども、病児保育の確保というのがこれまでもいろいろ話題になってきたと思うのですけれども、そういった部分の確保などもしていくような予定はありますか尋ねました。","respondent":"染谷保育施設運営課長","answer":"何度かご報告をさせていただいている中で、今回６月の補正予算でも２施設の追加ということで、１１月に向けて開設の準備を進めているところです。一定そこでカバーできるかなと見込んでいるところですけれども、開設については…","id":"exchange-014"},{"speaker":"鈴木委員","kind":"質問","question":"２０園の保育園が５０年以上たっているということで一覧表になっていますけれども、この改築計画というのは具体化されていないのでしょうか。検討委員会のメンバーについて、どんなメンバーになっているのかも説明を求めました。","respondent":"芝野保育入園調整課長","answer":"改築を進めていきたいというふうに考えておりまして、なかなか跡地が見つからないという状況で、申し訳ありません。品川区保育園等あり方基本方針は、検討委員会のほうが立ち上がりまして、今は品川区保育園等あり方検討委員会はございません。","id":"exchange-015"},{"speaker":"澤田委員","kind":"質問","question":"もう一度追加でお聞きしたいのですけれども、例えば兄弟児がいる場合は、それだと結構きついなというのがあると思うのですよね。どうしたらいいのかなというのがあるのですけれども、ゼロ歳児の人数がきつきつだと、その辺についてはどうお考えか尋ねました。","respondent":"芝野保育入園調整課長","answer":"第１から第８希望まで書いていただくところですが、大崎は五反田地区も近いということがありますので、その辺を選ばれることが結構多いかなと。なかなか書かないというか、記載されないので、おおむねご了解いただきながら入園のほうが進んでいるのかなというふうに考えておりま…","id":"exchange-016"},{"speaker":"大倉委員","kind":"質問・要望","question":"今５０年以上の保育園が２０件あるというところで、そういったところで働きかけの状況とかがあれば、教えていただきたいなと思います。いろいろ条件があると思うのですが、その辺の条件とかというのがある程度分かれば、併せて教えてほしいと求めました。","respondent":"芝野保育入園調整課長","answer":"跡地が見つかるということでございましたら、企画部と連携を取りまして、働きかけを行っていきたいというふうに考えております。そちらのほうもしっかりと、そちらのほうは使わせていただくというようなことを考えていきたいというふうに考えております。","id":"exchange-017"},{"speaker":"大倉委員","kind":"提案","question":"は取っているというよりは、企画部のほうも保育課のほうもちょっと探して、ぜひ提案していっていただけるといいのかなというふうに感じました。そういう意味ではデータとして全部出ていて…","respondent":"芝野保育入園調整課長","answer":"各園の敷地面積等々についてはしっかりと把握していますので、老朽度に応じてその敷地が賄えるかどうかというのはしっかり確認しながら、交渉のほうを進めていきたいというふうに考えております。","id":"exchange-018"},{"speaker":"大倉委員","kind":"意見","question":"敷地をどう捉えるかなのですけれども、そういうところも併せて柔軟に交渉していって、確保していただけるといいのかなというふうに思いましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"ゆきた副委員長","kind":"質問","question":"６ページのところの区立保育園の再整備、中延保育園では、休日保育が実施されていると思います。現在利用している方々の実際の現場の声などを把握しているようであれば、お聞きできればと思います。","respondent":"染谷保育施設運営課長","answer":"現状休日保育のほうを実施している園については、ニーズというか、必要数については、不足しているというお声は聞いておりませんで、そこは充足しているものと今認識しています。","id":"exchange-020"},{"speaker":"ゆきた副委員長","kind":"質問・要望","question":"実際に休日でないと預けることができないというご相談を受けたこともあるので、今後改築や再整備でさらに検討して進めてほしいと求めました。こちらは要望で終わりたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"つる委員","kind":"確認","question":"先ほど鈴木委員のところでもちょっと確認があった公設民営の保育園ということで５園、今後の先の検討とかの最初の園が５年を迎えるのは何年後か尋ねました。","respondent":"芝野保育入園調整課長","answer":"公設民営化園と今ご説明を進めておりますが、最初の園が、三ツ木保育園がちょうど今５年目になっていますので、来年４月に６年目になるかなというような状況です。","id":"exchange-022"},{"speaker":"つる委員","kind":"質問","question":"ちょっと分からないところもあるので教えていただきながら、４社から、そうした流れはあるのか尋ねました。","respondent":"芝野保育入園調整課長","answer":"今、区のほうで民設民営を検討させていただいているところでは、公私連携型の保育所制度というのを活用する。無償もしくは非常に低廉な価格で貸すということができますので、そちらもちょっと検討していかなければいけないかなというふうに考えております。","id":"exchange-023"},{"speaker":"つる委員","kind":"質問","question":"ただ、設備的なところについては、今言っていただいたような形で、ただ土地については無償ないし「低廉な」とありましたね。定期借地とかいろいろあったりすると思うのですけれども、この辺りは、土地については制度の関係でどういうようなものができるのか説明を求めました。","respondent":"芝野保育入園調整課長","answer":"公私連携型の保育所制度を活用した場合には、法律上では、こちらを活用できないかという検討はさせていただいている。もう一つの方策としては、デメリットがあるのかというのは今後検討して、またしかるべき時期にご報告させていただきたいというふうに考えております。","id":"exchange-024"},{"speaker":"つる委員","kind":"質問","question":"今の民設民営についてどういうふうにやっていくのが一番、先ほどどういう形がいいのかというのはおっしゃっていただいたのですけれども、その辺りも含めてちょっと説明を求めました。","respondent":"芝野保育入園調整課長","answer":"なかなか一概に答えは出せないところでありますが、１つ、民法の使用貸借というのは非常にメリットがあるかなと。一定の制約が出てきますので、今は検討の段階ですが、すぐにお返しいただくというのはなかなか難しいのかなというふうに捉えているところです。","id":"exchange-025"},{"speaker":"つる委員","kind":"質問","question":"それはただ、経常経費的なところの軽減だとか削減だとか、そういったところもいろいろあるわけです。逆に言うと、民法上の使用貸借だったら、事業者がなかなかそこには行かないとかというハードルになってしまうということなのか尋ねました。","respondent":"芝野保育入園調整課長","answer":"もちろん大前提として利用者がおりますので、「すぐに閉園、返してくれ」というのはなかなか難しいかなと。賃貸借も、どのやり方が一番適切なのかというのは、今後事業者としっかり話をして考えていきたいというふうに思っております。","id":"exchange-026"},{"speaker":"つる委員","kind":"質問","question":"投資額を回収できるのですかというのは、今回先ほどタイミングを伺って、事業者としての損益で見たときにはどういうスパンで時間軸を見ればいいのか尋ねました。","respondent":"芝野保育入園調整課長","answer":"今後事業者と話合いながら考えていかなければいけないところではあると思いますが、今事業者として５年やっていただいている。その事業者はほかにも園を数園持っていますので、今ご説明がありましたとおり、単独ではなかなか計れないかなというのが現状です。","id":"exchange-027"},{"speaker":"つる委員","kind":"質問","question":"保育園のことだけにエンクローズした話ではなくて、全体の行政ニーズで見たときに、最後どういうスパンで見るのかなと。１５年、２０年という、どういうスケジュール感で見ているものなのか尋ねました。","respondent":"芝野保育入園調整課長","answer":"量の見込みと確保方策をきっちりと整備させていただき、行政需要がもう見込まれないということであれば、そういった意味では公私連携型のこの制度でやったほうが機動性は高いのかなというふうに考えているところです。","id":"exchange-028"},{"speaker":"澤田委員","kind":"質問","question":"最後にお伺いしたいのが、品川区立品川保育園があると思うのです。複合施設というか、複合化とかというのは、区としてはどうお考えなのかなというのをちょっとお伺いしたいと思います。","respondent":"芝野保育入園調整課長","answer":"もちろんその検討は進めていくという中で、その地域のニーズをしっかりと捉えながら、検討を進めていきたいというふうに考えております。","id":"exchange-029"},{"speaker":"澤田委員","kind":"質問・要望","question":"多世代が交流して仲よくというのがあると思うので、いろいろハードルがあって難しいとは思うのですけれども、ぜひ進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/404196?Template=document&Id=7145#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=21&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":21365,"voices":73}},{"id":"r07-20250826-20","meetingId":"r07-cm08","date":"2025年8月26日","dateIso":"2025-08-26","committee":"ＳＤＧｓ推進・行財政改革特別委員会","time":"午後 １時００分～午後 ３時１５分","status":"正式会議録","sourceType":"formal","overview":"ＳＤＧｓ推進・行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ広げてほしいと思うのですけれども、プロポーザルにより選定された運用事業者はどちらになるのかを伺いたい。今後の展開なのですけれども、１年に１個ぐらいのテーマがベースになるのか尋ねました。","respondent":"横田デジタル推進課長、西澤ＤＸ戦略担当課長","answer":"現在、東品川、大崎、平塚橋、平塚、北品川のゆうゆうプラザ、計５か所に設置しております。これは国がやっていまして、問合せをしたのですが、実績を確認できませんで、現時点は不明ということになります。 もう１つのテーマは、これから検討というところです。プラットフォームも決まったので、それに合わせて、これから検討していくことになっております。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"標準化するのにかかる経費が１００とすると、どれぐらいを国が持ってくれて、金額などといったことをお伺いしたいと思います。そこら辺を伺いたいと思います。","respondent":"西澤ＤＸ戦略担当課長、横田デジタル推進課長","answer":"教職員向けのＡＩ研修については、まず昨日と今日で実施しておりまして、実際、学校の先生に来ていただいて、庁内で実施しております。スケジュールなどを保護者の方などに説明するとき… システム標準化でカスタマイズはできないのかですが、基本的にはできないということになります。こちらにつきましては、別システムを開発して、標準システムと連携させるというやり方を取っております。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"ＤＸａｗａｒｄという取組なのですが、今年度からの取組になるのかをお伺いしたい。仮に今年度からの取組だとしたら、現時点でもいいのですけれども、現場の反応や課題はどのような感じになっているのかを伺いたいと思います。","respondent":"横田デジタル推進課長、西澤ＤＸ戦略担当課長","answer":"申しわけありません。１回送信ボタンを押して、間違えたときには送信をきちんと取り消しましょうなどといった基本的な基礎・基本を再徹底したというところになります。 令和７年度からの実施になります。説明としては、各部から１つの課で３名以上となって、全部の課ではないことをご認識ください。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"すごく日進月歩の世界なので、難しい面もあると思うのですが、かなりトライアルのこともやりながらＤＸを進めているということは分かりました。大事なことだと思うのですけれども、やはり進める上では、実は職員の方々の現場の声をしっかり伺いながら、進めていっていただければと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問・要望","question":"それに対しての意見を求めることが目的だと思うので、そこに関しては所管課に全て任せるということなのか。Ｑ＆Ａということに関しては、それは、そのようなものを品川区でつくっているのかを教えていただきたいということが２つ目です。","respondent":"西澤ＤＸ戦略担当課長、横田デジタル推進課長","answer":"所管に課題を挙げていただいて、その中で、戦略広報課とデジタル推進課と３者共同で実施という形になっております。なので… 私からＣＩＳＯとＣＩＯについてお答えいたします。ＣＩＳＯ、最高情報セキュリティ責任者につきましては、情報セキュリティに特化した最高責任者になりま… 最後、１つお答えできていなかった別紙２のデジタルツールの特徴の一番下に書かれている生成ＡＩを用いた。そのようなものです。","id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問・要望","question":"それとも、新井副区長がそのようなことに対してすごく得意な分野なのかを確認したいというところです。新しい質問を幾つかさせていただいたので、もう少し確認をさせてください。","respondent":"西澤ＤＸ戦略担当課長、横田デジタル推進課長","answer":"実はこれは去年、令和６年度から実施しておりまして、そのとき最初に何をやったかというと、ＡＩにこの実施要項を読ませて、質問をつくらせました。そのように作業の効率化を進めておりまして、所管課がやって… デジタル推進課を担任の副区長がやっていることが多いです。ただ一方でデジタルにすごい力を入れている区ですと、外部から招き入れているというところが、３区か４区あったように記憶しております。","id":"exchange-006"},{"speaker":"筒井委員","kind":"質問","question":"総務委員会の資料では令和７年度中と書いてありました。現在分かる範囲で教えていただけると幸いです。","respondent":"西澤ＤＸ戦略担当課長","answer":"２つ目のテーマですけれども、今、所管課で、各所管等を含めて検討中というところです。現時点では、まだこれといったものは挙げられません。","id":"exchange-007"},{"speaker":"筒井委員","kind":"質問","question":"今までのパブリックコメントなどは、区のホームページから受付をしていたと思うのですけれども、今までの電子アンケートなどとどう違っているのか。その辺りを説明を求めました。","respondent":"西澤ＤＸ戦略担当課長","answer":"先ほどＤｅｃｉｄｉｍ（デシディム）の説明のところにありましたが、それに対して反応ができますので、透明性の高いものになってくるかと思います。これから研究にはなるのですが、幅広い活用が期待できると考えております。","id":"exchange-008"},{"speaker":"筒井委員","kind":"確認","question":"ある一定のテーマで、やはりその一定のテーマに関わるイベントに、ある程度アナログ的に周知をしていくといったことも考えていかれるのでしょうか。その点を今後どのようにお考えか尋ねました。","respondent":"西澤ＤＸ戦略担当課長","answer":"やはり区のホームページ、Ｘなどでの周知は、予定をしております。先ほど申し上げたとおりワークショップなども並行して開催していくので、そのようなところで周知・啓発を進めていきたいと考えております。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"より多くの方の意見がもらえるように、この画面の右のところの写真を見ると、品川区の公式ＬＩＮＥにも登載されるということでしょうか。そこの確認をさせてほしいと求めました。","respondent":"西澤ＤＸ戦略担当課長","answer":"誰かが投稿したものがリアルタイムに見られるのがいいところであり、特徴と考えております。公式ＬＩＮＥについては、こちらはもう９月１日から始めることもありまして、こちらでもアップできるように検討していきたいと考えております。","id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"皆さんに挙げていただいた意見のやり取りの中で、その渦中に区が何か返していくということは、途中経過の中ではあるのでしょうか。教育部門との連携をしながら子どもたちの意見を聞く場にもなってほしいとも思うのですが、そこら辺の考え方もまた教えてほしいと求めました。","respondent":"西澤ＤＸ戦略担当課長","answer":"やはり区の方針、全部を全部聞くのではなくて、やはり一緒につくり上げていくといったところがあると考えております。デジタルプラットフォームの目的でもありますので、そのようなところも幅広くテーマを選定しながらやっていきたいと考えています。","id":"exchange-011"},{"speaker":"新妻委員","kind":"質問","question":"途中過程の意見の中に対して区がどう反応するのかなのですけれども、もしそのような途中があれば、説明を求めました。","respondent":"西澤ＤＸ戦略担当課長","answer":"今回のデジタル化は、そのような機能も有しておりますので、検討に入れながら実施していくことになっています。そのようなところも実施していくと考えております。","id":"exchange-012"},{"speaker":"こしば委員","kind":"質問","question":"当たり前だと思いますけれども、そのような認識でよろしいでしょうか。ＤＸ人材の研修に入っているのでしょうけれども、その辺りを教えてほしいと求めました。","respondent":"横田デジタル推進課長","answer":"今回１１ページで取り上げた情報セキュリティの研修です。スマホよろず相談、東京都と連携して、そのようなスマホ教室をやったりといったところになってまいります。","id":"exchange-013"},{"speaker":"こしば委員","kind":"質問・要望","question":"ふだんの業務の中で、特にそのような区民と接することが多いところには、丁寧に研修の実施をしてほしいと求めました。その考えについて伺います。","respondent":"横田デジタル推進課長","answer":"ＤＸの推進の一方で、誰ひとり取り残されないという側面もありますので、そのような方の支援も含めて、各地域センターと連携しながら、いろいろなＤＸを推進していきたいと考えております。","id":"exchange-014"},{"speaker":"山本委員","kind":"質問・要望","question":"使った後に「よかったですか」ということを必ず確認するものが割と多いので、それをさらによくするために、そのような確認が必要なのか。質問の中で拾い切れない質問があったときに、要はその辺りのチャットボットで拾い切れているのか確認は、できるかを説明を求めました。","respondent":"横田デジタル推進課長、西澤ＤＸ戦略担当課長","answer":"ただ複数にわたって、この事業が実施されていますので、効果はあると考えております。ただ、どうやってこの辺りを検証していくかということは、今後、研究していきたいと考えております。 なかなか難しいところがありますけれども、所管課で業者に対して、このようなデータがありますと周知していく形になると考えています。参考になったか、参考にならなかったかというような機能を持った製品も確かにあるので…","id":"exchange-015"},{"speaker":"山本委員","kind":"質問・要望","question":"ＡＩチャットボットの満足度の確認ですけれども、これは機能として追加できると思いますので、これを機に進めてほしいと求めました。アンケート分析ツールの活用３件ということで、アクションプランで、それぞれ全てどのようなものが進んでいるのかを教えてほしいと求めました。","respondent":"西澤ＤＸ戦略担当課長","answer":"課によって課題意識やテーマなどに結構ばらつきがあるので、この中からどこまでデジタルで改善できるかというところは、今後の検討材料です。そこから統計的に取って、どのような施策を打ったほうがいいか、改善点はどうしていくかを検討している状況になっております。","id":"exchange-016"},{"speaker":"山本委員","kind":"質問","question":"ＢＩツールを活用した分析８件、多分８件はそれぞれエントリーがあると思っていまして、どのような項目かをお伺いします。難しいようでしたら、結構です。","respondent":"西澤ＤＸ戦略担当課長","answer":"１つ例を挙げるとすると、地域産業振興課で施設利用状況の可視化などといったところを実施しております。文化観光戦略課だと、イベントのアンケートの実施になります。","id":"exchange-017"},{"speaker":"山本委員","kind":"質問・要望","question":"せっかくなので、もしそれぞれどのようなことを進められるかが分かればと思ったのですが、またの機会でお伺いできればと思います。ＤＸａｗａｒｄが１３件あるということで、それぞれの部や課でのこのような使い方をまさに前に進めていただきたいと考えています。","respondent":"西澤ＤＸ戦略担当課長","answer":"区民の声を透明性をもって確認できるということなのですけれども、デジタル共創プラットフォームに求められるところかと思います。そのような公開の方向をどのような施策に反映させたのかは、今後、実施していく予定になっております。","id":"exchange-018"},{"speaker":"筒井委員","kind":"質問","question":"（３）アンケート分析、これは左の仮説立案の（２）、（３）と対応しているということでしょうか。括弧をしていないから、どうなのか。","respondent":"西澤ＤＸ戦略担当課長","answer":"（２）、（３）は誤植で何も意味を持たないものになっています。すみません、失礼しました。","id":"exchange-019"},{"speaker":"筒井委員","kind":"質問","question":"真ん中の（２）、（３）は、意味がないということですか。具体的に何か外部委託をされていると思うのですけれども、外部委託先について説明を求めました。","respondent":"西澤ＤＸ戦略担当課長","answer":"そのようないろいろなツールの特徴といいますか、得意分野に応じて使い分けをしていくのがいいと考えております。去年からこの方を雇っておりまして、それで実施している状況になっています。","id":"exchange-020"},{"speaker":"筒井委員","kind":"確認","question":"データ活用についてです。先ほどの住民参加型プラットフォーム、しなトークで得られたデータも、当然、今後のＥＢＰＭに活用するデータになるのか確認をさせてください。","respondent":"西澤ＤＸ戦略担当課長","answer":"もう１つのＤｅｃｉｄｉｍ（デシディム）でやっているものも、ものによっては検討になるかと考えています。このようなデータを幅広く、先ほどの東京都のＴｏｋｙｏＤａｔａＰｌａｔｆｏｒｍのデータも活用しながら政策に活かしていきたいと考えております。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"最新の年度で５９.６億円が年間に流出するということなのですが、制度が始まってからの累計流出額がもし分かれば教えていただきたいのが１つです。他区と比べてもかなり流出しているということで、その要因は何だと考えていらっしゃるのかを伺いたいと思います。","respondent":"宮澤税務課長","answer":"今回５９.６億円ということで、１７％増になっています。世田谷区も含めて、やはり２３区の伸び率が非常に高まってきておりますので、特別区を併せて区民の皆様に現状を説明しているところです。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"それを伺いたいということが１点です。そこら辺を教えてほしいと求めました。","respondent":"宮澤税務課長","answer":"税額控除を受けているかを見たところ、受けている方もいれば、受けていない方もいるというのは把握をしております。中間事業者に業務委託をしておりまして、いわゆる寄附者対応等々を含めた先ほど申し上げた業務内容は、寄附額に応じて約６％かかります。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"もともとの趣旨としては、または税の使い道を自らの意思で決めることを可能とするものということが制度の趣旨であるというのが、総務省の見解です。２３区長会では、例えば記者会見なども含めて、このような単独で廃止を含めた見直しを求めたことがあるのかどうかを伺いたいと思います。","respondent":"宮澤税務課長","answer":"制度自体に対する考えですけれども、先ほど単独で記者会見等とありましたが、そちらはございません。１０月を予定しておりますけれども、そのような現状を改めて区民に発信するので、区としての考えを発信するです。","id":"exchange-024"},{"speaker":"安藤委員","kind":"提案","question":"今度は１０月１日に特集号を組むということではありますけれども、総務省にメッセージとして発信していっていただきたいと要望したいと思います。さらにこの件を含めて、委員長にも要望させていただきたいのですが、本委員会としてそのような提案をしていってもいいのではないかとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"あくつ委員","kind":"質問","question":"しかも伸びとしては、非常にいい伸びを、４か月で既に１,５００万円ということになっています。積算根拠を説明を求めました。","respondent":"宮澤税務課長","answer":"商品型を４,５００万円、しながわ団体応援寄附を５００万円で、残りの２,０００万円はクラウドファンディングでやっております。ノウハウ等々を聞きながら、実際に到達できると思い、設定している金額です。","id":"exchange-026"},{"speaker":"あくつ委員","kind":"質問","question":"ふるさと納税でカバーするということは、なかなか難しい話であって、直近では一体どういうことを品川区がやっているのか。特別区長会の動き、議長会の動き等も含めて教えてほしいと求めました。","respondent":"宮澤税務課長","answer":"直近の動きとしましては、先ほど説明で言いました８月７日に区長会としまして、特別区の主張をまとめたところです。国に対する区単独での直接の動きはございませんけれども、引き続き特別区長会と連携を密に取りまして、品川区としても動いていきたいと考えています。","id":"exchange-027"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私も情報収集不足で、もし差し支えなければ、その３区はどこなのかを教えていただきたいということが１つ。前段の部分だけ説明を求めました。","respondent":"宮澤税務課長","answer":"毎年、総務省がふるさと納税の流出・流入額を調査しておりまして、これは総務省のホームページでも公表されております。世田谷区、新宿区、渋谷区になっております。","id":"exchange-028"},{"speaker":"山本委員","kind":"質問・要望","question":"以前５月に一度ご説明いただいて、ここまで進めていらして、ここは少し思いどおりではないというところがあれば教えていただきたいです。ご説明で店舗数４２店舗ということで、これは少し少ないのか、その辺り増やす方策などで考えていることがあれば教えてほしいと求めました。","respondent":"宮澤税務課長","answer":"先ほど説明で申し上げましたドウシシャの製品は、寄附額１万９,０００円で、寄附件数が伸びているところです。日々、ほぼ毎日のようにお店にアポを取って、ご説明に伺っているところです。","id":"exchange-029"},{"speaker":"山本委員","kind":"提案","question":"１つご提案になります。そのようなものも含めてさらなる充実に努めていただき、寄附額の増加に向けていってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"筒井委員","kind":"提案","question":"あのデザインを活用したグッズを作ってほしいというご要望も聞きましたので、寄附も入り、結構いい取組になると考えています。返礼品にしてみてはいかがかと思うのですけれども、区としては、その辺りをいかがお考えか尋ねました。","respondent":"宮澤税務課長","answer":"あれは一般でも販売しているものになっておりまして、返礼品のためだけに用意するということができない状況になっております。そのような基準を満たして、今、返礼品に用意できないか検討しています。","id":"exchange-031"},{"speaker":"筒井委員","kind":"質問","question":"先に一般販売をすればいいということですね。ある程度時間がかかるかもしれないですけれども、一般販売できる体制を整えてから、それを返礼品に使うということでよろしいか尋ねました。","respondent":"宮澤税務課長","answer":"基準の中に細かくありまして、一般販売している価格と同等数に抑える必要があることになっております。つまり一般販売を１００すれば、返礼品は１００の用意という形になっておりますので、どうできるか検討してきたところです。","id":"exchange-032"},{"speaker":"筒井委員","kind":"質問・要望","question":"先ほど私が申しました区民の団体もグッズを作ってほしいという声もありましたので、しっかり進めていってほしいと求めました。ぜひその辺り。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"まつざわ委員","kind":"質問","question":"結局これは、これ以上にこれから先に例えば社会福祉団体、文化事業の団体といった対象の拡大という可能性はあるのか。お伺いします。","respondent":"宮澤税務課長","answer":"今年度から始めさせていただきまして、まず区内にある学校法人という形で進めさせていただいているところです。学校法人で始めさせていただきまして、実績、動向を注視しながら拡大するかどうかは検討していきたいと考えています。","id":"exchange-034"},{"speaker":"まつざわ委員","kind":"質問","question":"要は先ほど返礼品目的ではないという話もありましたけれども、やはり地元を応援させる、そのような気持ちを高める工夫というのでしょうか。郷土にどう愛着を持たせていくのかという区の考えを説明を求めました。","respondent":"宮澤税務課長","answer":"区民の方では寄附はできないのですが、例えば返礼品を伴わないクラウドファンディングや団体応援寄附に関しましては、区民の方もできるものです。先ほど説明いたしました広報の特集号でもＰＲしていきたいと考えていますし、今後、区民の皆さんにお伝えできればです。","id":"exchange-035"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"勝手にこのようなことを言ったら、怒られるかもしれません。ＳＮＳなど広報の種類はいろいろあると思うのですけれども、いろいろなやり方でぜひ応援額の拡充を図ってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-036"},{"speaker":"新妻委員","kind":"質問・要望","question":"今、まつざわ委員からありました品川区民ができる品川区のふるさと納税について、もう一歩のアピールが必要かと思っています。今ありましたけれども、品川区民ができるふるさと納税のやり方は何があるのか、いま一度教えてほしいと求めました。","respondent":"宮澤税務課長","answer":"ふるさと納税の定義になるのですけれども、個人の方が自治体に対する寄附というのは、ふるさと納税、寄附という形になります。例えばクラウドファンディングであったり、ふるさと納税として２,０００円を超える部分は、その方の税額控除で対応できるという形になっております。","id":"exchange-037"},{"speaker":"新妻委員","kind":"質問・要望","question":"チラシ１枚にしても、たしか区内の団体事業者、企業などに対するふるさと納税のご案内はあったと思います。ぜひ作成をしていただきながら、あらゆるところで品川区を応援してもらいたいという発信の強化をしてほしいと求めましたが、いかがか尋ねました。","respondent":"宮澤税務課長","answer":"例年行っている子どもの未来を応援するクラウドファンディングを実施していくということで、区民に向けて配布していると聞いております。広報の特集号もしますが、定期的に通常の広報紙の中でも、ふるさと納税に関しては取り上げていきたいと考えています。","id":"exchange-038"},{"speaker":"新妻委員","kind":"意見","question":"この一文を目立つように工夫をしていただきながら、品川区民が品川区のために応援をしたいという思いで、そのような寄附をしてくださる方が多くなりますように工夫をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-039"},{"speaker":"こしば委員","kind":"質問・要望","question":"確認したいのですけれども、去年の１２月の件数が約４００件と、突然上がっておるのですけれども、時期に着目した取組が何か行われていたのか。残り８か月、これは時期に着目して取り組むものはおありなのかどうかを教えてほしいと求めました。","respondent":"宮澤税務課長","answer":"昨年、商品を展開したのがちょうど１２月で、ここに約２００万円強の寄附額が入っております。控除の限度額も確定してくるので、限度額いっぱいに寄附をしたいという方の寄附が、１２月に集中してくるということになっております。","id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/579883?Template=document&Id=7147#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=20&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":39351,"voices":107}},{"id":"r07-20250827-22","meetingId":"r07-cm08","date":"2025年8月27日","dateIso":"2025-08-27","committee":"まちづくり・公共交通推進特別委員会","time":"午後 １時００分～午後 ２時２０分","status":"正式会議録","sourceType":"formal","overview":"まちづくり・公共交通推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"えのした委員","kind":"質問・要望","question":"私も地元で交通量調査、ビーコンというのですか、かなり設置して、数か月にわたって行われたことがありました。キッチンカーとかが来たときに、その辺はもう学校とは全く違う人工芝の取扱いなのか、その辺を詳しく教えていただけますか尋ねました。","respondent":"中道都市開発課長","answer":"そういうところも調査できるみたいなことを聞いていますので、そういったところを今後こういった空間づくりには生かしていきたいと考えています。高圧洗浄機で定期的に洗わないと、そこではどうしても食べ物の残り物というのが問題になると考えていますので…","id":"exchange-001"},{"speaker":"えのした委員","kind":"確認","question":"人工芝はやはりそういったメンテナンスというのが必要になってくるというのが確認が取れました。９月１日に防災を絡めたイベントがあるというので、こういった中で、防災に関した何か取組というのはお考えいただいていますか尋ねました。","respondent":"中道都市開発課長","answer":"今、「なんだかんだ」という形で、イベントを様々地域のほうで取り組んでいるみたいなお話は聞いてありますけれども。先ほどのウォーカブルという形での居心地のよさというところに特化して調査を行っていきたいと考えています。","id":"exchange-002"},{"speaker":"えのした委員","kind":"質問・要望","question":"これからですけれども、ぜひそういった防災に関することも取り組んでいただければと、こちらは要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"松本委員","kind":"質問","question":"すごくいい、楽しい取組だなとも思うのですけれども、先日、千代田区に視察に伺った際には留意点が何点か挙げられていました。将来像としては、行政としては今、どのように考えていらっしゃるのか伺えればと思います。","respondent":"中道都市開発課長","answer":"検討中ですけれども、赤枠で飛び出している部分の外側、いわゆる灰色の道路の部分を自転車に通っていただくということを考えています。全面的に歩道を広げられることがいいのかどうかといった形で考えていくというところになってあります。","id":"exchange-004"},{"speaker":"松本委員","kind":"質問","question":"そういう意味では、車がいて自転車がいても一応十分な幅が確保できるというお見込みなのかというところを改めてお伺いいたします。この辺りの工夫はどのように、今、考えていらっしゃるのか伺います。","respondent":"中道都市開発課長","answer":"まずは第１回というところで、そのままの人の流れというのをまず現状で見ていきたいなと思ってあります。工夫といたしましては、入り口部分に板を貼るとか、看板を貼るとかして、人の動線が分かりやすいような形で取り組んでいきたいと考えています。","id":"exchange-005"},{"speaker":"田中委員","kind":"質問・要望","question":"その観点からお伺いしたいのですが、にぎわいを創出することを目的にこういう設置をするわけですから。まちづくり大井の方などが運営されるイベント開催時においての実証実験はどうなのかという、まずその辺をお聞かせほしいと求めました。","respondent":"中道都市開発課長","answer":"計画していたりとか、ちょっと何かここでそういったイベントをやってみたり、歩道を拡幅することを検討しています。まず行政としてこういった実験でお示しをして、そこに対して地域の方々の機運が醸成する促すといったことも進めていきたいなと考えています。","id":"exchange-006"},{"speaker":"田中委員","kind":"質問・要望","question":"そのときの評価というのはどういう基準で評価をされようとしているのか。あるいは先ほど言ったように、開業後のことも踏まえるとまだまだ第１弾としての実験になるのかな、その辺をお聞かせほしいと求めました。","respondent":"中道都市開発課長","answer":"実験の継続ですが、また区のほうで今後どうするかというのは検討していくというものにはなるかと思いますけれども、考えている状況です。やはりイベントを行うということでもちろん人は来るとは思うのですけれども…","id":"exchange-007"},{"speaker":"田中委員","kind":"質問・要望","question":"今後の展開としてはいろいろな部署との連携も含めて、踏まえて、この事業を大きく育てていただけるようにお願いをしたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"藤原委員","kind":"質問","question":"まずやってみて、区が考えているポイントといいますか数というか、この事業はもうこういうふうにするということで決まってしまっているのでしょうか。補助１６３号線でした」と発言訂正あり〕 あと、顔の表情から利用者の感情も分析と、そこまで今のＡＩカメラというのはできるのか尋ねました。","respondent":"中道都市開発課長","answer":"今回１回目ということと、あとやはり予算というところもありますので、限定した範囲の中でやるです。人が口頭で楽しかったよとかと回答したものが一致しているということも確認しておりますので、一定程度精度の高い分析ができると判断しています。","id":"exchange-009"},{"speaker":"藤原委員","kind":"確認","question":"一番最初に質問したみたいに、これで決定で、まだ地域の方には実験ですからというようなお話をしていいですねという確認です。社会実験の分析の結果、施策として本格的に進めていくか考えていくということで地域の方にお答えしていいのですよねという、再度の確認の質問です。","respondent":"中道都市開発課長","answer":"今回はあくまで実験というところで、地域の方にご説明していただければと思います。やはり最初に聞いたときは、そういった裏取りをして、きちんと高い精度で分析ができると確認しています。","id":"exchange-010"},{"speaker":"塚本委員","kind":"確認","question":"すみません、最初に１ページ目の地元意見の中で、イベントとして人はもう訪れていると。飲食店等をやられている方がより多くの人が訪れることで経済的効果があるよねということで捉えていいですかというところを確認したいと思います。","respondent":"中道都市開発課長","answer":"地域の意見ですけれども、今回検討会をやるに当たって、町会の方々、商店街の方を中心に検討会を行いました。その中で、やはり通るということは、既存の商店街または飲食店にもお客さんとして来るから、売上げというところも、そういったお話もあったです。","id":"exchange-011"},{"speaker":"塚本委員","kind":"確認","question":"かなり長期的な視野も入れた発言というところで受け止めましたけれども、それでよろしいですかという確認です。片道１車線にして、１時間３００円の駐車場のことですけれども、今の時点でどの程度を認識されているのかを伺いたいと思います。","respondent":"中道都市開発課長","answer":"やはり何かしないとというところで、今回の実験ということで、地域の方々とにぎわい創出に取り組んでいきたいと考えています。こういった継続して社会実験をやることで、そういったことも確認していきたいと考えております。","id":"exchange-012"},{"speaker":"塚本委員","kind":"提案","question":"これは区道ですけれども、区としてなくしても大丈夫だという判断でなくせる類いのものなのかというのを確認させてほしいと求めました。この実証実験されたところのからの提案というか、その考えについてのもうちょっと詳しい見解を伺いたいと思いますとの意見を述べました。","respondent":"中道都市開発課長","answer":"そういったことを目的にいわゆる空間をつくっていきたいという考えです。地域の方が継続してこういったにぎわいの取組というのをやっていただけるかどうかというところが非常に重要かなと考えていますので、そういった。","id":"exchange-013"},{"speaker":"塚本委員","kind":"質問・要望","question":"ご説明ありがとうございました。かなり地元の方々のやはり意向というのは、これまでの話も出ていましたけれども、実証実験をまずはしっかりと注視させてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"若林委員","kind":"確認","question":"お客さんをまちに呼び込めるかというところが当面の目標といいますか通過点というか、というふうにずっと質疑を聞いていて感じたのですが。大井町トラックスは来年３月末の開業ということで、もう今年の秋にやってしまいますよという意味なのか、そこを確認をさせてください。","respondent":"中道都市開発課長","answer":"この秋のハロウィンが１０月下旬にありますので、今、３週間を目指して調整を進めているです。","id":"exchange-015","title":"議員研修会の内容"},{"speaker":"若林委員","kind":"質問","question":"いや、来年度予算では、みたいな話だといけないと思うので、現在の見解は伺いたいと思います。関連性はいかがなのか尋ねました。","respondent":"中道都市開発課長","answer":"はその地域の方々で全体で大井町を盛り上げていくといったことを連携しながら進めていきたいと考えているところです。そこの部分も一層連携を深めていきたいと考えています。","id":"exchange-016"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"だから２週間だったら３回土日があるというようにして社会実験をやっていく、３週間なら４回あると、それだけお願いしておきます。そうなるのかな。","respondent":"中道都市開発課長","answer":"期間については警察との協議の中で決定したものもありますので、また前向きに検討させていただければと思います。","id":"exchange-017"},{"speaker":"のだて委員長","kind":"質問","question":"効果検証がそれでしっかりできるのかどうかというところを伺いたいと思います。今回の社会実験を同様のものにしてはいけないと思いますので、今回の社会実験が超高層の再開発につながっていくものなのかどうか伺いたいと思います。","respondent":"中道都市開発課長、高梨都市計画課長","answer":"地域の皆様の活動を継続的に行えるように、実験も取り組んでいきたいといったことが目的です。今回の社会実験につきましては、今、冒頭に申しました目的を達成するために行う実験となりますので… かもめ橋のライトアップおよび３つ下の勝島橋のライトアップは、ライトアップの新たな演出等の検討、実施を行ってまいります。右上２段目、ライトアップ空間の充実のため…","id":"exchange-018"},{"speaker":"藤原委員","kind":"意見","question":"どういう方を引き寄せるか、ライトアップすることでどうなっていくかというイメージを、大きな話いいので説明していただけますか。その後どういう形で人を呼び込むとか、こういうふうに変わるのですよとか、こういう戦略があるのですよというようなことを説明していただけますかとの意見を述べました。","respondent":"関根河川下水道課長","answer":"冒頭の説明の中でも、まさしくどういったライトアップをすればより魅力的なライトアップになるかという検討を今年度から実施していく予定です。検討においては、非常に魅力のあるライトアップを作っていきたいと、そのように考えてあります。","id":"exchange-019"},{"speaker":"藤原委員","kind":"質問","question":"ライトアップは結構お金がかかるではないですか、電気代も含め。課長、ワクワクするかしないか最初に答えていただいて、その後した質問において答えていただけますか。","respondent":"関根河川下水道課長","answer":"例えばそれだけではなくて何かストーリー性ですとか、そういったような何か付加的なものを持たせるといったことも有効ではないかなと考えています。今回の検討の中では、維持管理等についてもどのようにすれば効率的に実施できるか、そういった検討も併せて行う予定としています。","id":"exchange-020"},{"speaker":"藤原委員","kind":"質問・要望","question":"せっかくこれをやるわけですから、他自治体の方も見に来てくださって、ぱっとライトをつけただけで終わらせないようにしていただきたい。せっかくやるわけですから、本当に観光施策の一つとしても活用していっていただきたいと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"田中委員","kind":"質問・要望","question":"ではここをどう回遊性、ポイントを点を結んで線にして、またまちづくりという視点での面においての活性化につなげるということなのだと思います。こういうところは回遊性を求められないのでしょうけれども、例えば船着場とか、今日はこのポイントだけの話ということで受け止めていいのか尋ねました。","respondent":"高梨都市計画課長","answer":"前回の概要説明の場でも、回遊性を生かしたまちづくりといったところでご説明をさせていただいたところです。人々が楽しみながらこの運河周辺を歩いて回っていただくような取組といったところは引き続き継続して考えていかなければいけない。","id":"exchange-022"},{"speaker":"田中委員","kind":"質問・要望","question":"今年の１月だったでしょうか、トレーニングセンターを作るとか、それ伴って厩舎を移転するとかというお話もあります。あるいはまちづくりの視点で競馬場の協力を求めるという場面というのは、今まであるいは今後もあるのか、お聞かせほしいと求めました。","respondent":"高梨都市計画課長","answer":"もう１０年ぐらいたつかなと思っていますが、勝島地区のまちづくりについて、様々な情報交換を行うというような取組を進めてあります。等も含めながら、いろいろと意見交換をしながら、よりよいまちづくりにつなげてまいりたいと考えているところです。","id":"exchange-023"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひ連携を深めていただいて、まちづくりに対する協力もいただきながら、また、共ににぎわいの創出につなげてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/676877?Template=document&Id=7149#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=22&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":24157,"voices":62}},{"id":"r07-20250828-10","meetingId":"r07-cm08","date":"2025年8月28日","dateIso":"2025-08-28","committee":"議会運営委員会","time":"午後 １時００分～午後 １時２８分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を9件整理しています。","topics":[{"id":"topic-01","title":"令和８年度予算（議会費）","agenda":"令和８年度予算（議会費）","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"４つの点ですが、残念ながら今年も共産党の要望として上げていたものが入っていませんが、特に議事録の早期作成について毎年要望を出していますが。皆様と議長・副議長におかれましては、ぜひ現状をご理解いただいて、予算化していただきたいなと重ねて要望したいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"確認","question":"ご説明ありがとうございました。もう一回確認したいのですが、各会派から出ているものというとどこに当たるのかというのをお示しいただきながら教えていただけると助かります。","respondent":"大澤区議会事務局長","answer":"４番のオンラインについては、先ほどの説明と同様になります。共産は、９番の海外調査は予算計上しないというところです。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問・要望","question":"様々会派からの要望を尊重していただいてありがとうございました。これ、そもそもふれあい掲示板等にというところでの増額ということを求めているのですが、これを含んでの内容ということでよろしいか尋ねました。","respondent":"大澤区議会事務局長","answer":"議長から指示を受けまして、ふれあい掲示板に掲示分の増刷や配布の委託の経費等の要望はしていく予定です。","id":"exchange-003"}]},{"id":"topic-02","title":"広報会議からの報告事項","agenda":"広報会議からの報告事項","exchanges":[{"speaker":"せお委員","kind":"確認","question":"今年２月の議運で確認されておりますとおり、区議会定例会開催ポスター、これまで広報会議で検討を進めてまいりました。デザインの決定を受けまして、現在本番移行に向け、動作確認作業を進めております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"インタビューページなど新たなページを検討すると伺っていますが、その際、全体のページ数は増やさないようにするということです。一般質問の部分を削ろうという話も出ているとちょっと伺いました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今、ほかの何か新しい企画のために代表質問や一般質問の要旨みたいなものを削るというような方向性があるということなのでしょうか。確認させてください。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"せお委員","kind":"意見","question":"縦長に変えていただいて募集したり、横長でも使えるのですが、トリミングしたりといった形でまずは使わせていただく。写真に関しては、そちらも今後の検討かなという形にはなっていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"せお委員","kind":"質問","question":"ページ数はやはり増やせないので、もし特集ページを組んでいくのであればどこかしらをちょっと削るという検討はしていかないといけません。そこは皆さんと見て、意見を出し合いながら、今後検討していきたいなと思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"あくつ委員","kind":"質問","question":"どういう議論が今あるか私も詳細なところは分かりませんし、今、特に一般質問に触るというのは私もちょっと危険だなと。私の意見です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/888788?Template=document&Id=7151#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":8857,"voices":43}},{"id":"r07-20250917-10","meetingId":"r07-cm09","date":"2025年9月17日","dateIso":"2025-09-17","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時３０分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を11件整理しています。","topics":[{"id":"topic-01","title":"の常任・議運・特別委員会の構成","agenda":"の常任・議運・特別委員会の構成","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"やはり全ての会派から参加するということが第一優先であるべきだと思いますので、どういうふうに考え直すかというのはあるのですが、いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"松永委員","kind":"質問・要望","question":"今、特別委員会のところなのですが、木村議員が体調不良のため、私たちの会派のおぎの議員と交代させていただきたいと考えていますので、その辺のほどどうぞ。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"}]},{"id":"topic-02","title":"決算特別委員会","agenda":"決算特別委員会","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"毎回要望させていただいて恐縮ですが、１日延ばすということは不可能なのでしょうかということを、改めて事務局にお伺いしたいのですが。","respondent":"大澤区議会事務局長","answer":"区議会だよりのできるだけ早い発行を目指しておりますので、どうしても間に合わないということであれば、個別にご相談いただきたいと思います。","id":"exchange-003"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"どういうふうに確認していくかというのは、よく議員の意見を聞いて、みんなで決めていっていただきたいなと思っているところです。こういう確保策があったということを、もし分かるところがあれば少し教えていただきたいなというのが１つです。","respondent":"渡辺議長","answer":"これはやはり災害対応、それを見過ごすことは今後もあってはならないという思いで、報告をさせていただきました。もう一度状況も踏まえたり皆さんの意見を聞いて、対応を議長として、あるいは議運の皆さんとも相談しながらという思いで発言をしました。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問・要望","question":"議員の災害時の対応についてのところなのですが、今、それぞれ伺って、まさにそのとおりだなと。私どもの会派も７名、その次の日もまた回って現状を確認させていただいた中で、正直ベースで話しています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"せお委員","kind":"意見","question":"状況が分からないところもありますし、Ｘに載せられていたので大体は分かるのですが、ぜひご本人に発言いただけたらと思います。〔「委員長、委員外発言を……」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"せお委員","kind":"質問","question":"ご発言、ありがとうあります。１点だけ気になったのが、行かれたというお話を聞いているのですけれども、そちらに関してはどうなのか尋ねました。","respondent":"やなぎさわ議員、大澤区議会事務局長","answer":"そういったやり取りは、私はなかったと記憶しております。具体的にもしどの方がそういったことを指摘されたのかというのがあれば、教えていただきたいです。 本部は関係者のみであること、現場は混乱している状況が想定されるため、行かないでいただきたいということはお伝えしたというふうに報告は受けております。","id":"exchange-007"},{"speaker":"せお委員","kind":"意見","question":"今後どうやって対応していくのかというところで考えたいですし、そういうルール違反みたいなところが起こらないような対応というところも、考えていきたいなと思っていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そこら辺は重々考えていただきたいのと、先ほどせお委員からも、ほかにもやなぎさわ議員がこういうことがあったと。しっかりそれはご本人にも確認をしていく機会を設けてもらわないと、何でも失念したとか、それは必ず委員長にお願いをしておきたい。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"松永委員","kind":"質問・要望","question":"私の知る限りは多分３回目ぐらいかなとは思うのですが、品川区議会議員であるので、そうした品格や品位を守っていただきたいと改めて思っています。意見です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"確認","question":"１点だけ確認していいですか。だけど、そのときに、これから災害対策本部に行くのですというのをその係の人に言ったら、何も言わないでどうぞと言われたという理解なのか尋ねました。","respondent":"やなぎさわ議員、大澤区議会事務局長","answer":"その職員の方も災害対策本部まで、私は１人で行くと言ったのですが、一緒に同行していただいたのですよね。これはあくまでも私の一つの考えというか、そういったことも、もしかしたらあったのではないかなと推測しております。 職員の認識としては、そこに議員の方が行くと職員が困るだろうと思って止めたという認識は、職員は持っています。職員がそのまま状況を説明し、２３時３５分頃、次は課長が対応したということです。","id":"exchange-011"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/888788?Template=document&Id=7159#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":20687,"voices":119}},{"id":"r07-20250919-4","meetingId":"r07-c-settlement","date":"2025年9月19日","dateIso":"2025-09-19","committee":"決算特別委員会","time":"午後 ２時１１分～午後 ２時１９分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"若林副委員長","kind":"質問","question":"いずれにしても委員長にしっかり仕切っていただくという委員会です。いずれにしてもいい質問か悪い質問かは別に、そういう質問でないと少しまた矢が飛ぶかもしれません。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/766906?Template=document&Id=7249#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":2146,"voices":16}},{"id":"r07-20250922-6","meetingId":"r07-cm09","date":"2025年9月22日","dateIso":"2025-09-22","committee":"区民委員会","time":"午前１０時００分～午前１１時１７分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件整理しています。","topics":[{"id":"topic-01","title":"議案審査に入らせていただきます。 (1)第１０４号議案、品川区印鑑条例の一部を改正する条例","agenda":"議案審査に入らせていただきます。 (1)第１０４号議案、品川区印鑑条例の一部を改正する条例","exchanges":[{"speaker":"こんの委員","kind":"確認","question":"まず１点確認させていただいて、代理人の方の確認は、マイナ保険証がない場合には資格確認書でいいのかといったところを教えてください。本人確認に必要なものとして、資格確認書と記載し直すのだろうと思うのですが、この３点を確認させてください。","respondent":"築山戸籍住民課長","answer":"本人の住所地あてに照会書兼回答書というものを送付いたしますので、委任状を、そしてご本人が記載をした照会書兼回答書。３点目のホームページでのアップデートですが、これは施行日に合わせてホームページにアップデートをする予定です。","id":"exchange-001"},{"speaker":"こんの委員","kind":"確認","question":"そのときに、この確認は資格確認書でよろしいのですよねという確認だけでした。これで代理人の方の本人確認ができるのですかというところを確認をさせていただきたかったというところです。","respondent":"築山戸籍住民課長","answer":"資格確認書の場合は顔写真がありませんので、２種類の書類が必要になってきますので、本人確認ということにしています。","id":"exchange-002"},{"speaker":"こしば委員","kind":"確認","question":"確認したいのですけれども、今回、マイナンバーカードを持ってはいるのだけれども保険証にひもづけていない方もいらっしゃるかと思います。今７割後半か８割か、あえてしてない方もいらっしゃるかもしれませんが、それのパーセンテージは大体どのぐらいいらっしゃるか教えていただけますか。","respondent":"築山戸籍住民課長","answer":"マイナンバーカード自体は、現在７８％が今年６月末の保有率になっております。しかしながら、保険証とのひもづけをしていない方の割合については所管外になっておりまして、戸籍住民課では把握していないところです。","id":"exchange-003"},{"speaker":"こしば委員","kind":"質問・要望","question":"マイナンバーカードを持っている方に等しく健康保険証もひもづけていただけるような、それが結果的には医療行政の進歩にもつながってくると思いますので、その辺は柔軟に取り組んでほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"}]},{"id":"topic-02","title":"第１０１号議案、令和７年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第１０１号議案、令和７年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"おぎの委員","kind":"質問","question":"そういった強盗事件等が起きているのかということが１点と、申請を受けた後、今後の流れを説明を求めました。","respondent":"澤邉生活安全担当課長","answer":"１点目は、ちょっと私のほうでお答えできませんけれども、現在のところ耳にしているわけではございません。こういうのが当たるのかということで、事前にご相談いただくこともありますし、そういったところについては丁寧に説明をしています。","id":"exchange-005"},{"speaker":"おぎの委員","kind":"質問・要望","question":"流れなども、個人が購入して申請ということで、思っていたのと違って、より使いやすい制度だなと考えています。ぜひこちらのほうは広く告知をしていってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"こんの委員","kind":"質問","question":"４万円以上費用がかかっても、４万円まで補助してくださいますという、こういう理解でいいですかというのが１点です。その辺をお聞きしたいと思います。","respondent":"澤邉生活安全担当課長","answer":"２点目の申請の状況です。そうした場合は、紙ベースでのやり方も我々のほうでご説明を申し上げますので、こういった形については色々お知らせしてまいりたいと考えています。","id":"exchange-007"},{"speaker":"こんの委員","kind":"確認","question":"４万円までは補助しますけれども、それを超した部分は自費ですよといったところを確認しました。１４５台を予定していたのが１７３台ということで、この５月以降にも、方向性などを説明を求めました。","respondent":"澤邉生活安全担当課長","answer":"本事業は想定が１,６００件ですので、個々の事案の状況に応じて、そこについては対応できるものは対応していくことも考えていきたいと考えています。５月末で終わりにしますけれども、来年度も本事業の継続の検討をしておりますので…","id":"exchange-008"},{"speaker":"こんの委員","kind":"質問・要望","question":"先ほどの質問の答弁でありましたけれども、この先、万が一そういう事案が起きないとも限らない。ぜひ区の裁量で、そうしたことへの対応もしていただけるような考え方を持っていていただきたいというところですけれども、その点はいかがか尋ねました。","respondent":"澤邉生活安全担当課長","answer":"今ご質問いただきましたけれども、今回の町会・自治会等の補助というのは、そういった団体だからこそお願いするというようになっております。例えばですけれども、都の助成金を使用しないような形だとか、そういったところも含めて検討していければと思います。","id":"exchange-009"},{"speaker":"こんの委員","kind":"確認","question":"財政として予算の限りはあるわけですけれども、そうしたことをお考えとして持っていただいているということも今確認ができましたので、引き続き。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"おぎの委員","kind":"質問","question":"区も色々こういった伴走的な支援をされている窓口をつくっているという、それで年間４,０００件ほどご相談があるということをお伺いいたしました。国がということですが、どうか尋ねました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"戸籍住民課のほうで住民基本台帳のほうで管理をしていますけれども、事業者につきましては、そういったものがまずないといったところです。法人につきましては法務局のほうに登記をしていただく、正式に全体を把握する、そういったシステムがそもそもないといったところです。","id":"exchange-011"},{"speaker":"おぎの委員","kind":"意見","question":"そうしますと、事業者が出される開業届とかは国ですし納税とかは税務署なので、実際、どれだけの数の事業者が区内にいるという母数を把握するのが、まず区としては難しいということですねとの意見を述べました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"そうですね。それこそ免税事業者、課税事業者といった税の区分のところにつきましては、なかなか区のほうでは把握できないといったところです。","id":"exchange-012"},{"speaker":"おぎの委員","kind":"質問・要望","question":"やはり一番身近に寄り添う小回りがきくのは地方自治体ですので、できるだけそういった現状に寄り添っていただきたいとは思うのです。令和８年９月に切れますので、それまでに区としてできることなどを考えていただきたいと思うのですが、そういったことはいかがか尋ねました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"今、委員がおっしゃったように、２０２６年９月で２割特例が終了するというのは私どもも注視しています。２割特例の終了に当たって、多分、そういったことに対する不安の声などもきちんと拾い上げながら対応は考えていきたいというふうには考えております。","id":"exchange-013"},{"speaker":"おぎの委員","kind":"質問・要望","question":"も届いてない方とかに模索していただきたいというのと、区の商連などがあると思うのですが、そういったものに入るメリットというのはあるのか。一緒にお願いします。","respondent":"小林地域産業振興課長","answer":"我々としても、もちろん１対１の関係もありますけれども、あるいは東京都の制度なども一緒にメリットをご説明するような形にしております。そういったところへの支援ということも含めてご支援するというところを改めて周知をしっかり商連と一緒に区もやっていこうということでメ…","id":"exchange-014"},{"speaker":"おぎの委員","kind":"質問","question":"商店街とか、区とつながる商連とかもあった、メリットを今聞かせていただいたのですが、実店舗を持っていないフリーランスの方とかも入れるのか尋ねました。","respondent":"小林地域産業振興課長","answer":"例えば１人だけ、この店舗だけなのですけれどもとか、あるいはそういう店舗がないような形でも会に入っていただくようなことでご案内しています。","id":"exchange-015"},{"speaker":"高橋（伸）委員","kind":"質問","question":"もう１点、実態調査で、先ほど課長が、今、国が再調査をやっていますというお話がありましたけれども、その結果はいつ頃出るのですか。その１点だけ説明を求めました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"いつ発表になるかという通知ですとか、そういった話が一切おりてきていないので、実際のところは分からないといったところになります。ただ、調査の締切を見ますと、８月１日までとなっていたので、今、集計されて、秋冬ぐらいには公表されるのではないかと見込んでいるところで…","id":"exchange-016"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"分かりました。では、それは分かり次第、またお知らせをしていただいて、フリーランスの方にも手厚く知っていただくというのも今後進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"こんの委員","kind":"質問","question":"その辺、プッシュ型となると、現実どういうふうに考えられるのでしょうかというところが１点。どんな設問なのかという中身が分かれば、その辺をご説明というか、お知らせいただけますか尋ねました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"今年度はウェブ相談も実施する予定ですので、まずは区役所に来庁されなくても気軽にご相談できるという、そういった仕組みを整えているところです。そのような形は考えているのですけれども、まずは目に入れていただく…","id":"exchange-018"},{"speaker":"こんの委員","kind":"意見","question":"もう１点の実態調査のほうは、個人事業主の実態調査の中身で見えてくるものというのはとても参考になるのだろうと、今聞いていて思いました。なので、今進めていただいているところを引き続きやっていただくのがいいかなと感じましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"こしば委員","kind":"質問・要望","question":"インボイス制度による実態調査を区のほうへ求める請願の中に、区がすでに行っている実態調査のように区内の声を直接拾う調査は十分可能であると。そういった声も実際に聞いているところもありまして、国だと思いますけれども、どういったものがあるのかというのを教えてほしいと求めました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"発注者側のほうに対応を是正するですとか、そういったところの相談窓口が国のほうにありますので、そういったところをご案内するなどといったことが考えられます。","id":"exchange-020"},{"speaker":"おぎの委員","kind":"質問・要望","question":"ですが、２割特例の適用期間が切れる令和８年９月までには、区として何らかの救済策を考えていただきたいと強くお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"こんの委員","kind":"質問","question":"先ほども質問させていただきました。区としては色々な媒体で、それがないことにはプッシュもまだ行かないのだろうなというところで不採択でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"せらく委員","kind":"質問・要望","question":"プッシュ型支援の導入を求めるということなのですけれども、必要な情報にたどり着けるような工夫というのは、引き続きお願いしたいと思います。自らリサーチすることは、逆に１つあるのではないかと考えますので、今回は不採択でお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"こしば委員","kind":"質問","question":"実際にもう区のほうでもされて、また国のほうでもあるということですので、そこに着目をすべきではないのかなと。今の現状だと、区のほうで実態調査をするには詳細な情報をとることが難しいということですので、不採択でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"おぎの委員","kind":"質問・要望","question":"ちょっとどうかなと思って、全区民を対象とする広範囲な調査が必要となり、多大な時間と費用がかかることが予想されます。特定の業種に偏った結果も出る事態も考えられますということで、不採択でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"こんの委員","kind":"意見","question":"こうしたものが区の、いわゆる実態調査に近いところの努力をされているのだろうというふうにも受け取れるわけです。再度やっていることも１つ参考になるものでありますので、引き続きお願いしたいということで、本請願については不採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"せらく委員","kind":"意見","question":"この制度については、やはりこれだけ叫ばれている中、区として区内の事業者の思いだったり実態を把握してもらいたいと思っています。区での独自実態調査も反対するものではないというふうに考えまして、採択にしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"藤原副委員長","kind":"質問・要望","question":"明日でなくても、今日、要望だけしたいのですけど、せらく議員の質問の中で、五反田の件が出ましたよね。それで、課長、これは要望なのですけれども、やはり条例がある以上は条例を守ってもらわないと困るじゃないか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/414982?Template=document&Id=7165#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":23142,"voices":107}},{"id":"r07-20250922-7","meetingId":"r07-cm09","date":"2025年9月22日","dateIso":"2025-09-22","committee":"厚生委員会","time":"午前１０時００分～午後 ６時００分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を141件整理しています。","topics":[{"id":"topic-01","title":"議題に入ります前に、進行","agenda":"議題に入ります前に、進行","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"選考基準の評価項目・配点のところを確認したいのですけれども、１００点満点の基準で、掛ける４００点満点ということでいいのかどうかということ。電子で８ページですか、「委員の意見」の中で、財政的には赤字だという話が書いてあるのです。","respondent":"菅野高齢者福祉課長","answer":"３点ご質問を頂きましたので、順番にお答えします。電子では８ページの「財務評価について」というところで、月見橋在宅サービスセンター１つだけ見るのではなくて、今回は選定させていただきました。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"提案","question":"恐らくこの３つの、１０年経過していないから公募していない、手を挙げなかったのだろうと。各施設、先ほど２回目の答弁の中にもありましたけれども、提案がよかったなどといったところが読み取れるような報告であればありがたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"鈴木委員","kind":"提案","question":"引き続いてやっていただくということでの提案になっていると思うのですけれども、制度の趣旨からして、その点を１点伺いたいと思います。あしたの委員会の中でモニタリングの報告がありますので、それを見てみたのですけれども…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"鈴木委員","kind":"提案","question":"１０人という小規模であるにもかかわらず１,０００万円を超える赤字という状況で、４０点満点のところ、２６点ですか。ここはどう考えられて、改善というのはどういうふうに対策が提案されているのか、その点についても伺いたいと思いますとの意見を述べました。","respondent":"菅野高齢者福祉課長","answer":"説明会には、最終的には、現に指定管理をしている事業者のみが応募したという結果となっているというところです。小山の家という形で平成１０年に開設したものなのですけれども、そのコンセプトとは裏腹に、なかなか事業収支が難しいというお話はあります。","id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問","question":"この形で長い間、１事業者という状況に対しては、区としてはどういうふうに捉えられているかということもお聞かせいただけたらと思います。何というのですか、公募もなかなか手を挙げにくい、そういう構造的なところも含めてどう考えられるかも伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"事業者と共に今後も考えていかなくてはいけないところかと思います。モニタリングなども通じて事業収支等を十分分析した上で、事業者と共に安定した運営を目指していきたいとは思っております。","id":"exchange-005"},{"speaker":"鈴木委員","kind":"質問・要望","question":"いろいろあると思いますので、ぜひ声を上げていただいて、成り立つ事業というところにも声を上げていただきたいと要望しておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"吉田委員","kind":"質問","question":"ほかの自治体から法人などを呼び込むような方策というのは考えておられないのかというのを、１個、伺いたいです。働く方への方針というか、どこから読み取るべきというご指摘があれば伺いたいと思うのですけれども、その点はいかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"指定管理者３年目に実施していますので、その辺りも含めて特に問題がないとは、総合的には評価しています。２番の、離職率等も見していますので、総合的に判断はさせていただいているところです。","id":"exchange-007"},{"speaker":"吉田委員","kind":"質問・要望","question":"今まで何年かたってのモニタリングのときに労務の管理の視点を入れていただきたいと、ずっと要望してきたときには、本当に厳しい状況であるのは確か。もし何か見解があったら伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"この事業者にはお願いできるというような判断をしていますので、その辺り、この報告書の中では少し見えづらいというお話もございました。その辺りは今後、研究してまいりたいと思っているところです。","id":"exchange-008"},{"speaker":"やなぎさわ委員","kind":"質問","question":"先ほども議論があって、やはり通所介護事業所というのは４割近くが赤字ということで、その辺は本当に課題だと改めて感じております。今回の指定管理の選定の中で、処遇改善加算の取得に関して評価というか、基準として入っているのかどうか、お伺いしたいのですが、いかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"処遇改善加算につきましては、具体的には加算を取られていますかというような、そこの部分についての確認等はしてはいないのですけれども、その辺りは、離職率などといったところの全体的なバランスを見ながら、評価をさせていただいているというところになります。","id":"exchange-009"},{"speaker":"やなぎさわ委員","kind":"確認","question":"大崎在宅サービスセンターだけ、介護職員の処遇改善加算がＩではなくてIIの取得になっているというふうに、東京都の公共情報で出てきたのです。その辺はより厳格にするべきだと思いますので、処遇改善加算はＩを取るようなところをしっかり確認して、いかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"そこまでの現実的な処遇改善加算についても、処遇改善加算については、それぞれ事業者によって差が出てくる可能性もあるのかなと考えております。区内法人でもありますので、ご指摘の所得改善加算については…","id":"exchange-010"},{"speaker":"やなぎさわ委員","kind":"確認","question":"東京都が出している福ナビ、とうきょう福祉ナビゲーションの情報も確認したのですけれども、福ナビの情報がほとんど入っていないのです。区としても指定を与えているわけですから、その辺の指導はしっかりしてほしいと思うのですけれども、いかがでしょう。","respondent":"菅野高齢者福祉課長","answer":"事業者には、ぜひ活用してくださいというところで、今後働きかけをしてまいりたいと考えています。","id":"exchange-011"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"そうですね。やはり自分の地域でどういったデイサービスがあるのかなど、この辺は、指定を与えている事業所に関しては注意して見てほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"鈴木委員","kind":"確認","question":"まず伺いたいのですが、高齢化率も４割近く、高いですよね。継続的な資金の取崩しが確認されるなど、これは具体的にどう改善させていくのか、その点を１点伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"在宅介護支援センターや居宅介護支援事業所等に周知して、法人等からは聞いておりますので、その辺りを期待していきたいと考えています。そして収支の部分につきましては、その辺りは稼働率を上げることによって解消していってくれるのではないかと期待しております。","id":"exchange-013"},{"speaker":"鈴木委員","kind":"質問","question":"選定理由のところに、それの中身は具体的にどういうことなのか、伺いたいと思います。先ほどの選定理由で改善が見込まれるということと、実態の、どういう状況なのかという辺りをお聞かせいただけたらと思います。","respondent":"菅野高齢者福祉課長","answer":"資格を持った方が単発で応援に来てくれて、少しでも多くのご利用者を受け入れる体制を現在は整えていると、法人からは聞いております。ただ、あと外国人についても採用をいろいろ工夫されているというところもありますので…","id":"exchange-014"},{"speaker":"鈴木委員","kind":"質問","question":"どこかでは、三徳会全体になるのかどうなのか分からないのですけれども、財務状況というものの評価というのはされているのでしょうか。されているのであれば、どれぐらいの評価だったのかというのも伺えたらと思います。","respondent":"菅野高齢者福祉課長","answer":"ここは公募によらずですけれども、選定委員会をするに当たっては、経営分析等をさせてはいただいております。その中の文言等、こちらについて「財政状態は良好だが」という評価を一定程度、頂いているというところではあります。","id":"exchange-015"},{"speaker":"鈴木委員","kind":"確認","question":"ほかのところの指標では４０点満点のうち何点みたいなのが出ていたのですけれども、点数はつけてはいないけれども財務状況は良好だという評価だというところで、点数はつけていないということなのか、その点の確認だけお願いします。","respondent":"菅野高齢者福祉課長","answer":"こちらの報告書の点数が２６点というところのお話だと思うのですけれども、「収支計画に具体性、実現性があるか」という、財務評価のところのお話ですか。","id":"exchange-016"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ほかのどこだったか。４０点満点のうち何点というのが出てきていた議案があったのですけれども、もしもつけているのであればお聞かせいただきたいということです。","respondent":"菅野高齢者福祉課長","answer":"６ページの、「福祉サービスを安定的に提供できる経営基盤を有しているか」との部分があります。財務経営分析等や、あとは事業者のヒアリングを経て、その辺りはきちんと項目別には評価させていただいている次第です。","id":"exchange-017"},{"speaker":"鈴木委員","kind":"質問・要望","question":"その点数が分かるようであれば、何点だったのかというのを教えていただきたいということで聞いていました。","respondent":"菅野高齢者福祉課長","answer":"今回の報告書の中では、あくまでも指定管理者の指定の結果報告書についての報告様式等は、区の中での統一した報告様式となっておりますので、その中で点数は総合得点で示すこととなっておりますので、項目ごとについては差し控えします。","id":"exchange-018"},{"speaker":"吉田委員","kind":"質問・要望","question":"本来あるべきものとは少し違うかもしれないですけれども、これは三徳会が独自にやっているという理解でよろしいのでしょうかというのが１つ。なぜなら、もう少し制度としてきちんとしていくということも考えられるのかなと思って伺うので、ぜひ教えてほしいと求めました。","respondent":"菅野高齢者福祉課長","answer":"三徳会に限らず、ほかの区内の法人等でも同じように活用しているとは聞いております。区としては、とてもいいとは思っているのですけれども、区として応援するなどといったところにまではまだ至らないかなとは感じているところです。","id":"exchange-019"},{"speaker":"吉田委員","kind":"質問","question":"よく分かりました。そういう制度を使うことが結局、財政上の圧迫につながっているという理解でよろしいか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"委員がおっしゃるとおりです。本来の常勤職員として雇うのとはまた別の部分の費用がかかるので、どうしても費用が、そこの部分でかさんでくるとは捉えています。","id":"exchange-020"},{"speaker":"鈴木委員","kind":"提案","question":"提案内容評価と財務状況評価というのに分かれていて、その辺を教えていただきたいのと、どういう基準なのか。その点についても伺いますとの意見を述べました。","respondent":"菅野高齢者福祉課長","answer":"ご指摘の、先ほどご説明させていただいた小山在宅サービスセンターにつきましての採点結果のところです。ちなみに、財務状況評価につきましては、同じ法人ですので、同じ点で２６点とつけております。","id":"exchange-021"},{"speaker":"鈴木委員","kind":"質問","question":"ということは、財務状況評価というのは、単独のサービスに対しての財務状況というよりは、法人に対しての財務状況評価というところで捉えていいのか、その点も伺います。","respondent":"菅野高齢者福祉課長","answer":"すみません。同じ点数と言いましたけれども、同じ法人だからといって、必ずしも点数が同じになるとは限らないです。","id":"exchange-022"},{"speaker":"鈴木委員","kind":"確認","question":"ということは、きちんと黒字でやっていけますというところであれば、財務状況評価というのも高くなるし、法人全体としては大変であっても、サービスごとに財務状況評価というのは評価されて点数になるということでいいのかの確認だけお願いします。","respondent":"菅野高齢者福祉課長","answer":"お話を聞くことによって、施設については少し点数が高くなるなどといったことは、審査の中では起こり得るというふうにはなっています。","id":"exchange-023"},{"speaker":"やなぎさわ委員","kind":"確認","question":"電子８ページの「委員の意見」というところで、これは国に対しても、そういったところはあると私は思っております。今回、私は平塚橋特別養護老人ホームの直近の令和４年度を確認したのですけれども、そういったところは評価基準に入っていますか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"アンケートというのは、満足度評価というのが、指定管理者の指定期間の中で一度行わせていただくというシステムがあります。当然、そちらの辺りのアンケート結果等も加味しながら、今回は継続をお願いするという結果に至りました。","id":"exchange-024"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"個別の計画作成時に、利用者や家族の状況や要望を聞かれているかという質問に、「はい」が１０％、「いいえ」が９０％。この辺は今回の評価に関わっているのかなという質問ではあったのですけれども、改めて、アンケート結果の存在を含めて確認させてください。","respondent":"菅野高齢者福祉課長","answer":"そういった他の調査など、いろいろ様々あるとは思うのですが、そこの部分については今回の評価には入れておりません。そちらについては回答者が５４名というところで、「満足」４８％というところで、評価には入れてはおりません。","id":"exchange-025"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ちなみに、その調査の方式というか、対面なのか記述なのか、その辺を伺います。","respondent":"菅野高齢者福祉課長","answer":"こちらについては、指定管理者制度の中で実施していますが、対面なのか書面なのかというのは確認させていただきたいところではありますが、実際に施設で一定、ヒアリング等もしているとは聞いておりますので、確認事項はありますが、一定の信頼度はある評価だとは捉えております。","id":"exchange-026"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"確かに私が取り上げたのは１０人なので、人数は少ないけれども、一定の忖度が介入しにくいものになっているとは思うのです。どうしてそうなっているのかというのは、その辺もしっかりと見てほしいと求めましたが、いかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"そこの部分については改善を促したりするなどして、より指定管理の事業者と協議を重ねることによって、よりよいサービスを提供していくことに努めていきたいと思います。","id":"exchange-027"},{"speaker":"やなぎさわ委員","kind":"意見","question":"分かりました。かなり候補者選定の理由にいろいろ述べられているところと乖離してしまうのかなと思いますので、ぜひ注視してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"}]},{"id":"topic-02","title":"第１０１号議案、令和７年度品川区一般会計補正予算（歳出等 厚生委員会所管分）","agenda":"第１０１号議案、令和７年度品川区一般会計補正予算（歳出等 厚生委員会所管分）","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"本来、これは総務委員会等でやるべきことなのかもしれませんけれども、ここに委員会がかかっているので伺いたいということが１つ。一応、今後この１１月からですか、こういうインセンティブを出すことによって見込み数というものがあるのかどうかというところが１つ。","respondent":"東野福祉計画課長、佐藤障害者施策推進課長、松山障害者支援課長","answer":"こちらにつきましては、周知の事実だというところで認識しておりましたので、記載しなかったものです。そういったものが重なり合いまして、工期変更に三… これは、昨年度末の時点で３３事業所確認しておりましたので、今年度に入りましてから３事業所程度は増えてはおりますがというところではあります。… １８事業所にご対応いただいております。そして、新たな予算計上で、新規分として３事業所、計２１事業所を見込んでおります。","id":"exchange-029"},{"speaker":"あくつ委員","kind":"質問・要望","question":"喫緊の課題等についても伺ってしまいましたが、それはまた契約変更、また別の機会で伺えればと思っています。もうこれは各障害者の団体からたくさんご要望も頂いておりましたし、１つ、すごく時宜を得た施策だと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"吉田委員","kind":"確認","question":"２０２５年４月からは原則全ての建築物省エネ基準への適合が義務づけられたという、これでいいのか、これに基づいたものかという確認が１個。でも、国で決まった制度がこのとき分かっていたはずですから、その点のご説明をまず頂きたいと思います。","respondent":"東野福祉計画課長","answer":"委員からご指摘いただいた法が当てはまるのかどうかというところにつきましては、現在、答えを持ち合わせておりません。詳細につきまして改めて確認した上で、委員会に追加で報告できればと思います。","id":"exchange-031"},{"speaker":"吉田委員","kind":"質問・要望","question":"１点質問で、私の理解が間違っていると困るので伺いますが、ありますよね。確認させてください。","respondent":"松山障害者支援課長","answer":"吉田委員のおっしゃる、おそらく令和１１年度予定の建て替えに伴うということは、また今後の検討になるかと思われます。今回はあくまでも補正案ということで、今年度の補正案になります。","id":"exchange-032"},{"speaker":"吉田委員","kind":"質問・要望","question":"確かにこれは補正ですから、そういうことであれば、しっかり当初予算からつけなくてはいけないものだと思います。最後は要望にとどめておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"鈴木委員","kind":"質問・要望","question":"補助金も減額されるということで、補助金がどれくらい出るのかというのを確認させてほしいと求めました。どれに当たるのかというのを教えていただきたいのと、１.８倍出るということで、そこを確認させてください。","respondent":"東野福祉計画課長","answer":"一定程度の工事費に伴ってというところで申請はしています。今言った１.８倍というところにつきましては、適用の予定となっております。","id":"exchange-034"},{"speaker":"鈴木委員","kind":"質問","question":"所要量としてどれぐらい必要なのかというところは、区としてはどう考えられているのか、その点を伺いたいと思います。設けるのか、設けないのか、その点についても伺いたいと思います。","respondent":"東野福祉計画課長、佐藤障害者施策推進課長","answer":"八潮南特別養護老人ホームにつきましては、特別養護老人ホームの関係等の補助、それからグループホームの関係の補助も入る予定となっております。詳細の金額につきましては、補助協議をしているというところになりますので… まず必要量等の見込みというようなところですが、利用日数等の増加につきましては、まだ十分でないという認識はこちらでもしています。潜在的に利用したいと考えている利用希望の方に加えて、事業実施できたとすれば…","id":"exchange-035"},{"speaker":"鈴木委員","kind":"質問・要望","question":"途中までたしか１２か所ぐらいしかなかったような、それでもまだ６日しか通えないということなので、これだけ求められている事業だと思うのです。私たちも懇談のときに団体の皆さんからご要望いただいているところなのですけれども、愛の手帳１度～３度で、その点も説明を求めました。","respondent":"松山障害者支援課長","answer":"愛の手帳１度～３度、大体１割ぐらいの方です。ただし、ご利用できない理由は、１割の方については理由は様々であろうと推測されますが、特にこちらでは全てつかんでいるわけではございません。","id":"exchange-036"},{"speaker":"鈴木委員","kind":"意見","question":"中重度受入れの加算なのですけれども、裏のページで、加算を総額で出されているのですけれども、愛の手帳１・２度所持者への加算や３度の加算というのが、具体的にどれぐらいの加算になるのか、その点についても説明を求めました。","respondent":"松山障害者支援課長","answer":"それから１,０００円の加算になっていることから、１・２度所有者の単価を１,３００円、３度所有者の単価を１,０００円としております。時間単価×時間×人数、そして１月の日数×月数という式により算出しています。","id":"exchange-037"},{"speaker":"鈴木委員","kind":"質問","question":"１台当たり１か月１８万円出るということなのですけれども、これは運転専門のスタッフを雇うという場合のみが対象ということになるのか、その点について伺いたいと思います。","respondent":"松山障害者支援課長","answer":"今年度予算の補正予算ということで、１１月から対象で、来年の３月までということで、５月を計上しています。職員１名の方がどうしてもドライバーとして運転業務に関わらなければならないというような負担を考えまして、こちらの対象とするものです。","id":"exchange-038"},{"speaker":"鈴木委員","kind":"確認","question":"４月以降の中重度受入れ加算は来年度予算ということなので、引き続いて出していただけたら、お願いしておきたいと思います。不妊治療で１,１４０件まで増やすということで、東京都の助成とダブって受けることはできないということなのか、そのことだけ確認させてください。","respondent":"勝亦健康課長","answer":"東京都で先進医療の助成等は行っておりまして、こちらは、保険適用外の先進医療の補助だと認識しています。今、区で適用しておりますのは保険適用されている部分ですけれども、それに助成を出すものということで、助成の対象は重複していない形になります。","id":"exchange-039"},{"speaker":"吉田委員","kind":"質問・要望","question":"質の確保を具体的にどうやっているかというのも確認するのを忘れまして、そういうことをやっていただきたいという方向で聞いているのですけれども、お伺いしたいと思います。","respondent":"佐藤障害者施策推進課長","answer":"国の指針では３年に１回程度、この補正予算を実施できたとして、こちらの体制もしっかり整えていきたいとは考えているところです。","id":"exchange-040"},{"speaker":"吉田委員","kind":"質問・要望","question":"３年に１回かと、その辺はぜひ回数を、なるべく丁寧な点検をしていただきながら育成を図るということを目指してほしいと求めました。これは要望でとどめます。","respondent":"東野福祉計画課長","answer":"まだ全体の確定ではないのですが、現在、総整備費が９５億円余のところ、補助金額につきましては１２億５,０００万円の予定でおります。詳細につきましては、今後、契約変更等を加味して変わってくると思われます。","id":"exchange-041"},{"speaker":"やなぎさわ委員","kind":"確認","question":"放課後等デイサービスの助成事業なのですけれども、非常にすばらしいことなのですけれども、確認なのですが、今回の助成は新規開設の事業所に限るということでよろしいか尋ねました。","respondent":"佐藤障害者施策推進課長","answer":"開設費用等助成に関しましては、区内の事業所を増やすところを目的にしておりますので、新規開設のところを対象にというところで予定しているものです。","id":"exchange-042"},{"speaker":"やなぎさわ委員","kind":"確認","question":"これも確認ですけれども、今回、物件の初期費用や賃料、駐車場の補助が新規開設のところで出るというところなのですけれども、既存の施設に対して類似の制度は品川区は何か設けていらっしゃったか確認したいのですが、いかがか尋ねました。","respondent":"寺嶋福祉部長","answer":"それは、次年度に向けて引き続き検討させていただきたいとは思っておりますが、取りあえず今回の補正予算については新規開設に力を入れている。そういう理解でおります。","id":"exchange-043"},{"speaker":"やなぎさわ委員","kind":"質問","question":"（２）中重度受入れの促進事業なのですが、そこの2)のウなのですが、いわゆるカーリースというのが対象なのでしょうか。説明をお願いしたいと思います。","respondent":"松山障害者支援課長","answer":"こちら、ウの車両のリース料についてのご質問です。こちらは、購入ではなくリースということで、月に５万円を見込んだものです。","id":"exchange-044"},{"speaker":"やなぎさわ委員","kind":"質問","question":"これは、送迎車を買うときに、リースではなくて一括購入の場合も当然あり得ると思うのですが、車両リースに限定したところには何か理由があるのか尋ねました。","respondent":"松山障害者支援課長","answer":"購入ですと、今、購入してかなりの時間を要してしまいますので、リースでしたら比較的、早い時間で調達できるということがあります。そのため、補正ですので３月の間までにということを考えますと、やはりリースのほうが現実的であると考えたものです。","id":"exchange-045"},{"speaker":"やなぎさわ委員","kind":"確認","question":"来年の３月までというと、つまり先ほど話がありましたけれども、実質的には四、五か月半ぐらいになるということで、５か月だとして２５万円ぐらいが最大ですということで、その先についてはまた次年度ということになるという理解でよろしいか、確認です。","respondent":"松山障害者支援課長","answer":"ご指摘のとおりです。","id":"exchange-046"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"では、買おうと思っていたけれどもカーリースにしようといって選んで、後々後悔する可能性が。２５万円ぐらいで単年度で終わったとして、ミスリードにならないように気をつけていただきたいと思うのですが、いかがか尋ねました。","respondent":"松山障害者支援課長","answer":"委員のおっしゃる懸念点などということにつきましては、今後配慮して、事業所にも周知してまいりますし、来年度の予算につきましても、そういったことは配慮して検討してまいります。","id":"exchange-047"}]},{"id":"topic-03","title":"令和７年請願第１８号、国に対して次期改定を待つことなく介護報酬引き上げを求める意見書の提出を求める請願","agenda":"令和７年請願第１８号、国に対して次期改定を待つことなく介護報酬引き上げを求める意見書の提出を求める請願","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"品川で閉鎖となったデイサービスの件数とかも、この５年間ぐらいで分かればお知らせいただきたいのと、その理由についてもお伺いしたいと思います。経営がより厳しい状況にあるのではないかという思いが私はしているのですけれども、その点も含めていかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"要支援の方のサービスというところで、平成２７年から総合事業ができまして、区のほうで単価の設定ができるようになりました。国の動向も見ながら、区として事業者の声を聞きながら、適宜適切な単価設定を行っていきたいと考えています。","id":"exchange-048"},{"speaker":"鈴木委員","kind":"質問","question":"私はここの介護報酬の引き上げというのがどうしても必要だというふうに思うのですけれども、その点を区としてどう考えるのか伺いたいと思います。介護報酬の引き上げというのに対して、区としてどう考えるかという点についても伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"先ほどのご説明の中でも少し触れさせていただきましたが、介護報酬自体が国の調査や制度の枠組みの中で行われております。支援金を出すというような立場もありますし、あとは居住支援手当のほうで支給させていただいて、区としては心がけていきたいと思っているところです。","id":"exchange-049"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ぜひそういう改悪、議会も、区としてもそういうふうな立場で上げていくということが求められているのではないかというふうに私は思います。そういうふうなところでできたらいいなというふうに思っておりますので、ぜひ皆さんからのご意見もお聞かせいただければというふうに思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-050"},{"speaker":"やなぎさわ委員","kind":"質問","question":"鈴木委員のおっしゃることはごもっともで、先ほど質疑の中で、区内のデイサービスの倒産件数の把握はされていないということではあったのですけれども、逆に新規の状況はいかがですか、もし分かれば。","respondent":"菅野高齢者福祉課長","answer":"１事業者、指定したということがありますので、把握しています。先ほどご紹介した事業所も含めて、数箇所廃止というところは聞いておりますが、区内においては大きな変動はないのかなというふうに捉えております。","id":"exchange-051"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"改めて質問なのですけれども、訪問介護の報酬引上げを求めるような、同じような意見書の請願審査がありました。品川区がいろいろ言わずに待つべきだと、把握している範囲でお伺いしたいのですが、いかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"その中で、訪問介護サービス事業所安定運営支援金というのを補正予算で組ませていただきまして、介護報酬が下がってしまって影響を受けている。次の改定までは支援金をというような流れで、その辺りについては…","id":"exchange-052"},{"speaker":"やなぎさわ委員","kind":"質問","question":"その動向というのを、今現在どのように捉えていらっしゃるか教えてほしいです。","respondent":"菅野高齢者福祉課長","answer":"大変失礼いたしました。そちらについては、適切な介護報酬の単価設定をしてくださいという形で、区として意見を上げていきたいというふうに思っております。","id":"exchange-053"},{"speaker":"やなぎさわ委員","kind":"提案","question":"今国がこんなことを提案していて、何もないなら、区議会からしっかり声を上げていくべきだと思います。意見ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-054"},{"speaker":"あくつ委員","kind":"質問・要望","question":"もし所管の課長がご存じならば教えていただきたいのですが、たしか６月の骨太の方針には、引き上げを明確にうたっているはずなのです。その辺りについて、所管の課長、国の動きとして何かつかんでいるところがあれば、教えてほしいと求めました。","respondent":"菅野高齢者福祉課長","answer":"骨太の方針には確かに一部こういった文言が掲載されていると認識しておりますが、今のところその辺りは、国のほうは示されていないのかなというふうに捉えております。","id":"exchange-055"},{"speaker":"あくつ委員","kind":"確認","question":"それについて現段階では、期中改定があるのかどうかについては明確に示されていないということは確認させていただきました。意見については、後ほど述べたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-056"},{"speaker":"吉田委員","kind":"提案","question":"これはもう何とかしなければ、介護の日フォーラムですから、基本は今の介護の状況を何とかしなければいけないという方向のフォーラムだったわけです。よさげな提案として、自治体がつくっていくというような提案もあったようには思うのですけれども、教えていただけますかとの意見を述べました。","respondent":"菅野高齢者福祉課長","answer":"そういった形で、いろいろな手を借りながら、お互いに支え合いましょうというのが総合事業のスタンスの一つなのかなと考えています。そういったところでは、そういったサービスも提供するなど、少しでも総合事業が実現できるように努めているところです。","id":"exchange-057"},{"speaker":"吉田委員","kind":"提案","question":"２０００年でしたっけ、総合事業というのも提案されるようになって、私もとてもうまくいっている事例も聞きました。これはぜひ検討していただきたいのですけれども、いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-058"},{"speaker":"吉田委員","kind":"質問","question":"それでいいのですかというのがあります。だから、その辺の事業所への現状の聞き取りとか、状況把握はされているのか伺います。","respondent":"菅野高齢者福祉課長","answer":"結局そこからの手数料を取られてしまうといった、すごく詳細な、いろいろなお話は聞かせていただきました。それだけではなく、どうすることが事業者にとって一番いい施策なのかというのは、また常日頃考えていきたいと思っているところです。","id":"exchange-059"},{"speaker":"吉田委員","kind":"意見","question":"基本、介護保険の仕組みというのを維持するという方向は、一緒に考えていくべきだというふうに思っております。これは意見ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-060"},{"speaker":"鈴木委員","kind":"提案","question":"公費負担を６割にするという提案をしているのですけれども、公費負担の増加を図り、介護保険料の上昇を抑制するということを明記しているのです。いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-061"},{"speaker":"あくつ委員","kind":"質問","question":"訪問介護のときにもお聞きしたのですけれども、財源をどうされるかというところで、財源はどうされるのですか。もう一度伺います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-062"},{"speaker":"鈴木委員","kind":"意見","question":"公明党自らが公約にも書かれていたことなので、そのときには財源があったけれども、今財源がないということではないと思います。それなので、何を大事にするかというふうなところだと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-063"},{"speaker":"あくつ委員","kind":"質問","question":"共産党もかつて様々なことをおっしゃっていて、でも、そのことを言うと、多分水かけ論になってしまうと思うのです、いろいろ。２０１１年の公約か尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-064"},{"speaker":"あくつ委員","kind":"意見","question":"今ここで政党同士の公約ということを根拠にされるということ自体が、多分共産党も公約はいろいろ変わっていますよね。そのとき、そのときの情勢に合わせて、だから一致できるというのは牽強付会ではないかなと私自身は思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-065"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"単価の安い生活援助のほうを求められている、割が合わないと分かっていても頑張ってやっていただいているというお話がありました。１６万円黒字というところで、売上げの２０％というのは相当厳しい状況が各事業所、全体の報酬引き上げというのは急務かなというふうに思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-066"},{"speaker":"えのした副委員長","kind":"質問","question":"区の事業者の実態も伺いました。現段階では国の方向性がはっきり示されていないということですので、今後も国の動向を注視して、情報の収集をお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-067"},{"speaker":"大倉委員","kind":"質問・要望","question":"議会として国に意見書を求めるというところでありますが、皆さんのお話をいろいろ伺っていましたが、かなり影響が出てしまった。国に求めていくということも大事なのですが、これから行っていかれるという話も出ましたし、この請願については不採択でお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-068"},{"speaker":"あくつ委員","kind":"提案","question":"どこかから財源を移してくるのではなくて、これは日本として、政府として財源をつくるのだというような提案もさせていただきました。それは推進すべきだというふうに思っておりますが、まさに経済財政運営と改革の基本方針２０２５、不採択とさせていただきましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-069"},{"speaker":"鈴木委員","kind":"質問","question":"財源をどうするのかというふうなことでありましたけれども、税金というのは集め方、使い方をどうするかというふうなことに尽きると思うのです。防衛費とかはすさまじい勢いで増やしているわけですから、社会保障、そういうふうなところに充てるべきというのが私たち共産党としての考え方です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-070"},{"speaker":"吉田委員","kind":"提案","question":"ですから、はっきり言えば、皆さんが介護を必要とされたときには、その制度はなくなっているかもしれないということです。確かに具体的にここからという提案は、残念ながらできませんとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-071"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"３年に１回の報酬改定は１年半後ですか、そこまで待っていられないです。これは訪問介護だけですから、早急に改善を求めるために、賛成です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-072"}]},{"id":"topic-04","title":"令和７年陳情第３１号、国民健康保険の区民に対する資格確認書の一斉交付に関する陳情","agenda":"令和７年陳情第３１号、国民健康保険の区民に対する資格確認書の一斉交付に関する陳情","exchanges":[{"speaker":"鈴木委員","kind":"確認","question":"マイナ保険証、かなりマイナ保険証に登録していなくて、資格確認書で対応するという方がこれだけいるのだなというふうに思いました。登録を取り消すことができて、取り消せば、資格確認書が送られるということになると思うのですけれども。","respondent":"山下国保医療年金課長","answer":"昨年度につきましては、昨年１０月から今年の３月末までというところで、約１１１件でございました。本年４月からこの９月少し半ばぐらいまでになりますけれども、１００件を少し超えているような状況で、一定の推移をしているというような状況です。","id":"exchange-073"},{"speaker":"鈴木委員","kind":"質問・要望","question":"マイナ保険証の登録を取り消して、資格確認書で保険証と同じように使えるという周知はどのようにされたのかということを伺いたいと思います。それから、今でも、そういう周知というのを区民に対してどのようにされているのかということも伺いたいと思います。","respondent":"山下国保医療年金課長","answer":"実際そういう対応が必要な方、そういうお求めがある方にはしっかりと内容が伝わるような形で引き続き周知に努めてまいります。マイナポータルのほうからご登録いただきますと、資格に変更がない限りは基本的にそのまま引き続きご利用いただける状況です。","id":"exchange-074"},{"speaker":"鈴木委員","kind":"確認","question":"今年あたりがもう５年目に、２万円を出すので、どうぞマイナ保険証に登録してくださいというキャンペーンを張ったではないですか。その点をもう一回お願いしたいのと、資格確認書が自動的に届くということになるのかどうなのか、そこら辺のところも伺いたいと思ったのです。","respondent":"山下国保医療年金課長","answer":"資格として国民健康保険に加入された暁には、その資格というのは基本的に続いてまいります。従前の資格が情報としてうまく残ることで、そういったところも含めて、マイナ保険証の利活用についてお知らせしてまいりたいと考えています。","id":"exchange-075"},{"speaker":"やなぎさわ委員","kind":"確認","question":"確認なのですけれども、区として７月中旬頃に２万７,０００人の方に資格確認書を送付したと、３万４,０００人の方に何かお送りしたのでしたっけ。その辺を確認させてください。","respondent":"山下国保医療年金課長","answer":"７月中旬に、マイナ保険証にはこういう情報をご登録いただいていますといったものを約３万４,０００人の方にご郵送申し上げました。他方で、マイナ保険証はまだ利用されていないという方、約２万７,０００人の方に対しましては、資格確認書をお送りしたところです。","id":"exchange-076"},{"speaker":"やなぎさわ委員","kind":"確認","question":"それで、お伺いしたいのですけれども、資格確認書と資格情報のお知らせというのは、機能としては何が違うのか尋ねました。","respondent":"山下国保医療年金課長","answer":"その内容が入っているであろう資格情報のお知らせを目視で確認することで、従前の対応に類する形、柔軟な対応はできるということになっております。そういった対応でできるのですが、次回以降お待ちいただけるものをお持ちいただくようにご案内をということで…","id":"exchange-077"},{"speaker":"やなぎさわ委員","kind":"確認","question":"資格確認書を一斉交付していただけると、２万７,０００人に資格確認書ということで、一斉交付をしたほうがいいのかなというふうに思うのです。一応確認なのですけれども、福岡厚生労働大臣が最後は自治体の判断というふうに容認しているということに関して、これは間違いないか尋ねました。","respondent":"山下国保医療年金課長","answer":"少し混乱を来すのではないかというところは、電話等でご照会があり、丁寧に説明させていただいたところです。ご質問のございました福岡厚生労働大臣の発言の部分ですけれども、従前の委員会でもご説明申し上げたところかと思うのですが、自治事務であるので。","id":"exchange-078"},{"speaker":"吉田委員","kind":"確認","question":"１点、東京都後期高齢者医療広域連合では、後期高齢者である加入者に資格確認書を一斉交付する方針を示しています。それをこの間課長に伺うのを忘れてしまったような気がしていて、その点について、問合せとかがあるのか伺いたいと思います。","respondent":"山下国保医療年金課長","answer":"国民健康保険の中でも資格確認書と資格情報のお知らせが混在する方については、ご質問のご照会のお電話をいただいたというところは現実としています。区として非常に多くのご質問、社会的なところでは、一定そういった影響があったのかなというふうに受け止めているところです。","id":"exchange-079"},{"speaker":"えのした副委員長","kind":"確認","question":"理事者の方からも説明いただきましたけれども、区としては法令どおりに７月に資格情報のお知らせと資格確認書を郵送しているということです。課長からは発行依頼など、現場も混乱はしていないということですので、不採択といたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-080"},{"speaker":"あくつ委員","kind":"確認","question":"本日結論を出す、不採択でお願いします。区としては今、現段階では資格確認書を一斉交付する必要はないのではないかと考えますので、不採択でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-081"},{"speaker":"鈴木委員","kind":"質問・要望","question":"医療機関の中でも様々トラブルを起こしているというのが全国保険医団体連合会の先生方からも様々指摘されているところです。国民健康保険も資格確認書というのがそのまま全ての人に配布されたら、ぜひ資格確認書を全員にというふうなことでやっていただきたいのが。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-082"},{"speaker":"吉田委員","kind":"確認","question":"１秒と１０秒というのが負担になっているのだというご意見は、紙の資格確認書であれば、スムーズにいって１０秒かかるわけですよ。資格確認書の一斉送付というのは、この陳情については、採択を主張いたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-083"},{"speaker":"やなぎさわ委員","kind":"確認","question":"資格確認書というのは、何が送られてくるか、同じ家族でも違ったりすると混乱にもなります。区としても国民健康保険の方には全員資格確認証を送るというふうにしたほうが、業務の効率的にも楽なのではないか。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-084"}]},{"id":"topic-05","title":"の利用者に対し、自主的・先導的に独自の予算制度を創設し、所得の多寡に関わらず、財政措置を講じて、実質１０００円で高齢者区民がシルバーパスを利用することが可能と…","agenda":"の利用者に対し、自主的・先導的に独自の予算制度を創設し、所得の多寡に関わらず、財政措置を講じて、実質１０００円で高齢者区民がシルバーパスを利用することが可能と…","exchanges":[{"speaker":"鈴木委員","kind":"提案","question":"シルバーパスを１,０００円で買える条例の提案をしているところですけれども、ぜひ区でもやっていただきたいというふうに思っているところです。改めてちょっと伺いたいのが、７５歳以上の人口というのは、７０歳以上の人口というのを教えていただけたらと思いますとの意見を述べました。","respondent":"樫村高齢者地域支援課長","answer":"３点目の介護保険制度の１から７の支援区分というお話がございましたけれども、こちらにつきましては、すみませんが詳細を把握しておりません。それから、最後４点目のご質問で、１,０００円で買える方の割合につきましても、すみませんが、こちらのほうでは把握できておりませ…","id":"exchange-085"},{"speaker":"鈴木委員","kind":"質問・要望","question":"２万５１０円というのは結構高いので、そこで買っている人数というのはどれくらいなのかというのは把握されていないのか教えてください。１万１,０００円を区が助成するとなると、８,８００万円の予算が必要だということで、改めて確認させてほしいと求めました。","respondent":"樫村高齢者地域支援課長","answer":"それから、２点目のところです。８,８００万円と試算をしたですけれども、あくまで荒川区の予算編成を基に、品川区の人口で割り返して試算をしてみたです。","id":"exchange-086"},{"speaker":"鈴木委員","kind":"質問","question":"東京都が公表していないということなのですね。所管が違うから難しいかもしれないですけれども、もし分かったら、教えていただけたらと思います。","respondent":"樫村高齢者地域支援課長","answer":"コミュニティバスにおけるシルバーパスの運用につきましては、すみませんけれども、所管外なのでコメントは差し控えたいと思います。","id":"exchange-087"},{"speaker":"鈴木委員","kind":"質問","question":"コミュニティバスも使える自治体と使えない自治体があると伺ったのですけれども、シルバーパスが１,０００で買えて、そのパスがあれば。そういう観点からも、これは区としてもぜひやっていくべきではないかなというふうに思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-088"},{"speaker":"えのした副委員長","kind":"質問","question":"現時点において制度の見直しの途中であり、また今年度より大幅に価格が下げられることから、不採択とします。なお、理事者からの説明にもありましたが、都や他自治体の動向について、今後も引き続き積極的な情報収集をお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-089"},{"speaker":"大倉委員","kind":"意見","question":"そもそもこのシルバーパス制度ができてから、全員に配られていた時期があったかなというふうに思っております。今実質１,０００円でというところは難しいのだろうというふうに思っているので、不採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-090"},{"speaker":"あくつ委員","kind":"質問・要望","question":"都議会から要望もしてというところで、これから始まってくる中で、それは見極めなければいけない部分があるなと。荒川区とか、他のところで模索しているという状況もしっかり見極める必要があるという中で、現段階では不採択とします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-091"},{"speaker":"鈴木委員","kind":"提案","question":"昨年１２月にも一律１,０００円の条例提案をしているところですけれども、様々な条例提案を何度もしてきているところですけれども。今、東京都がやっていないわけですから、品川区がこれをやって東京都にやらせていくということも大事なことではないかというふうに思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-092"},{"speaker":"吉田委員","kind":"意見","question":"都内で行きたいところにどうやっていくかというのをやっていたのを、まだ元気な高齢者だったとき、そういう活用をしていたのを思い出します。品川区がそれをどのように促していくかというと、品川区としての独自の施策というのが必要になると思いますので…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-093"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"実は荒川区の公明党が推進しておられたという経緯があって、区長に対して要望書を提出して、シルバーパスの実質無償化を強く要望したと。物価高騰対策に関する緊急要望書という名目で出しているということで、本当だったらぜひ一緒に賛成していただければありがたかったです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-094"}]},{"id":"topic-06","title":"令和７年陳情第３６号、障害者施設の利用調整を区に求める陳情","agenda":"令和７年陳情第３６号、障害者施設の利用調整を区に求める陳情","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"基本的な質問になりますけれども、課長の今の答弁によると、障害者施設の利用調整はしているということになりますか。卒業されるときの調整はあるということですけれども、全体としての利用調整について説明を求めました。","respondent":"松山障害者支援課長","answer":"特別支援学校ですと施設のイメージは実際に体験をされないとなかなか分からないものですので、また、ご本人が難しかったりする場合もありますので。ですから、個別に対応するという今の方式を変える予定はございません。","id":"exchange-095"},{"speaker":"吉田委員","kind":"確認","question":"要は多くの人がなるべくその人に合う施設を一緒に選んでいるというイメージで間違いないですかということが１つ確認です。それとも、そんなことはなかったのか尋ねました。","respondent":"松山障害者支援課長","answer":"個別に実習の機会を設けるなどして対応しているというところですので、個別に利用は調整しています。どちらかといいますと、１８歳の壁の対応もありまして、非常に個別性を品川区としては重視しています。","id":"exchange-096"},{"speaker":"吉田委員","kind":"確認","question":"多分、キャパシティが決まっている中で多くの人が希望のところに行けるような仲立というのですか、調整をやってほしいという趣旨だと思います。私は、こういうことが多分地域拠点相談支援センターの役割ではないかと思っていたのですけれども、その点についても確認させてください。","respondent":"松山障害者支援課長","answer":"既に相談支援員がおそらくついている場合が多いですが、相談員をバックアップして区と地域拠点相談支援センターが相談員と一緒に支援しています。そして地域拠点相談支援センター、区のケースワーカーが間に入ってという形は今も取っていて、支援しています。","id":"exchange-097"},{"speaker":"吉田委員","kind":"質問・要望","question":"障害者支援課に行けば、基本的なそういう区内の情報ですから、その点についても教えてほしいと求めました。別に秘密の情報でも何でもないと思うので、その点について今はどのように工夫されていて、改善点があると思われるのだったら伺いたいと思います。","respondent":"松山障害者支援課長","answer":"今ですと相談支援員に問い合わせていただくとか、あとは相談支援員が区のほうにケースワーカーと情報共有をしながら情報提供をしたりとか。そういう形であれば、特にその時点での空き状況をお知りになりたいということであれば、必ずお答えはさせていただいているところです。","id":"exchange-098"},{"speaker":"吉田委員","kind":"質問・要望","question":"例えば、地域拠点相談支援センターとか計画相談のところとかにサービスを利用される方は必ず相談に行くわけですから。本当は今数を伺いたいのですが、こういう数字についてはぜひ伺いたいというふうに思うのですけれども、いかがか尋ねました。","respondent":"松山障害者支援課長","answer":"そこら辺はおそらくその方の障害種別、ご希望も含めて聞いて、そこの施設にお問合せするということが通常だとは考えています。明後日までにというのは、ちょっと難しいかと考えています。","id":"exchange-099"},{"speaker":"吉田委員","kind":"質問・要望","question":"例えば医療的ケアが必要な方とか、たんの吸引が必要な方とか、そのレベルであれば個人の特定にもつながらないかというふうに思います。要は、どこら辺まで表現するかはまたご相談ということですが、基礎的な情報としてぜひ教えてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-100"},{"speaker":"鈴木委員","kind":"質問","question":"品川区の施設が足りないということがやはりあって、他区に通所せざるを得ない。そういうところで品川区にそれぞれ他区でそういうサービスを受けているという方は何人くらいいるかということが分かったら教えていただけないでしょ…","respondent":"松山障害者支援課長","answer":"今、その数字は持ち合わせてはおりません。","id":"exchange-101"},{"speaker":"鈴木委員","kind":"質問","question":"そこら辺のところを区としてはどう捉えられているのか、その点も伺いたいと思います。それから、卒業の方は皆さん希望の施設に通えているというふうに区としては捉えられているのか、その点についても伺いたいと思います。","respondent":"松山障害者支援課長","answer":"は１８歳の壁にその施設が対応できるのか、それから職員のスキルといったものも考えながら、事業者と区と相談しながら調整を図っているです。もちろん就労継続支援Ｂ型につきましては、区内にも新たな種類の就労継続支援Ｂ型もできておりますので。","id":"exchange-102"},{"speaker":"鈴木委員","kind":"質問・要望","question":"通所施設についても計画的に区としてどれくらい必要なのかという所要量を出して、それをどう確保していくのかというふうな計画を出しているわけです。計画をぜひともつくって、施設の整備につなげていただきたいというふうに思っていますけれども、いかがか尋ねました。","respondent":"松山障害者支援課長、佐藤障害者施策推進課長","answer":"品川区としましては、今は非常に個別に丁寧にきめ細かく調整をしておりますので、１８歳の壁対応も含めて本当にオーダーメイド的に調整をしています。なので、今の方法でそのまま利用方法については行っていきたいと考えております。 令和９年度からの障害福祉計画に向けてということで、先般も基礎調査の実施等も報告をさせていただいたところですが、現在検討しています。そこも踏まえて検討しているところではありますが…","id":"exchange-103"},{"speaker":"やなぎさわ委員","kind":"質問","question":"私から、質問を１点だけ。今後する予定があるのか、もしあればお伺いしたいのですけれども、いかがか尋ねました。","respondent":"松山障害者支援課長","answer":"一括して一律押しなべてやるということに対して非常にどうなのかというところで、今のところ疑問が残るところではあります。ただ、今後他区で本当にいいような取組があれば、もちろん取り入れてはいきたいと考えております。","id":"exchange-104"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"さらにやはり高みを目指していただきたいという思いで、ぜひそういったところを積極的に情報収集していただければというふうに思います。これは、意見です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-105"},{"speaker":"えのした副委員長","kind":"意見","question":"理由としましては、各自治体で利用の手順の方法は異なるようですが、重要な役割として個別で品川区のほうは受入れの相談をしている。相談支援専門員、事業所と連携して細やかに対応しているということで、不採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-106"},{"speaker":"大倉委員","kind":"意見","question":"障害の特性に配慮しながらできるだけよりよい環境で当事者もご家族も過ごせるようにということで配慮しながらやっているということ。施設のところも入所率とかを見るとまだ空きがあるというところも少しそごがあるのかなというところもありますので、不採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-107"},{"speaker":"あくつ委員","kind":"質問・要望","question":"点数化されているかどうか分からないと課長も言っていましたけれども、この懸念はやはり先ほど改めて利用率ですか。より丁寧に、しかも皆さんの要望どおりできるだけこれからも調整をお願いしたいというところで、不採択といたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-108"},{"speaker":"鈴木委員","kind":"質問・要望","question":"出石のときもそうですけれども、透明性、そういうものが確保されるような仕組みというものはすごく大事なことかというふうに思っています。そういうものを立てて、具体的にそれをいつまでに何か所、どういう施設をというふうなところを明確に出していただきたいというふうに思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-109"},{"speaker":"吉田委員","kind":"質問","question":"この陳情の議論を伺いながら、言葉について何を選んでくるかなということは本当に難しいと思いました。希望者がそれぞれ交渉するのではなく、そういう仕組みをつくってほしいし、他区のような利用調整というのはそういうことを意味していると思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-110"},{"speaker":"やなぎさわ委員","kind":"意見","question":"やはりこういった陳情が上がってきて、困られていたりとか自分たちで交渉したりということで苦労されている方もいらっしゃるというところもあります。根本はやはり施設を増やすというところだし、そういった意味で私は趣旨ではありますが、採択とさせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-111"}]},{"id":"topic-07","title":"令和７年陳情第３９号、自殺対策の誤解を解くために啓発内容を改める陳情","agenda":"令和７年陳情第３９号、自殺対策の誤解を解くために啓発内容を改める陳情","exchanges":[{"speaker":"やなぎさわ委員","kind":"質問","question":"今のご説明の中で、自殺に関する５つの誤解というものが少しずつ解消されてきたというお話だったと思います。ということは、いわゆるここに書かれてある東京都の自殺に関する５つの誤解は既にこのような指導をしているということでよろしいか尋ねました。","respondent":"五十嵐保健予防課長","answer":"ゲートキーパー研修におきましては様々な状況、対象者に合わせまして情報発信をさせていただいているところです。ですので、やはり死ぬ死ぬと言う方が死ぬわけではないみたいなことはないということなど等は周知させいただいているところになっております。","id":"exchange-112"},{"speaker":"やなぎさわ委員","kind":"確認","question":"ということは、ここの５つのことはゲートキーパーの講習に入っているということで、一応確認のためにもう一度お願いいたします。","respondent":"五十嵐保健予防課長","answer":"入れしています。","id":"exchange-113"},{"speaker":"やなぎさわ委員","kind":"確認","question":"私も東京都自殺総合対策計画～こころといのちのサポートプランを確認させていただいたのですが。積極的にこの自殺に関する誤解というのは、重点的に区としても発信していく必要があるのかと思うのですけれども、いかがか尋ねました。","respondent":"五十嵐保健予防課長","answer":"今回このような陳情が上がってきたということもありまして、まだまだ周知が足りなかったかと考えていますので、こちらも含めて周知をしていきたいと考えているところです。","id":"exchange-114"},{"speaker":"鈴木委員","kind":"質問・要望","question":"この中で、国のほうでも今年の６月に改正した自殺対策基本法が成立というふうなことで、これはどんなメンバーでどれくらいされているのか。議事録が公開となっていたにも関わらず見当たらなかったので、公開されているのかについてもお聞かせほしいと求めました。","respondent":"五十嵐保健予防課長","answer":"議事録のほうは、要約したものを載せるような形にさせていただいているので、公開はさせていただいている状況かと思います。来ていただいて実施しているところですが、年に１、２回実施させていただいているような状況になってあります。","id":"exchange-115"},{"speaker":"鈴木委員","kind":"質問・要望","question":"なので、どこにあるのか分からなかったのですけれども、そこら辺がどうなっているのかを伺いたいと思います。違うところにお金を使っていきたいということはどういうことなのかも伺いたいと思います。","respondent":"五十嵐保健予防課長","answer":"それまでは、庁外の方で構成する会議に意見をいただきまして、庁内でやっている会議と合わせて実施させていただいているところになりますので。自殺対策の品川区独自の資料ということですけれども、ゲートキーパー研修などに力を入れていきたいと思っているところです。","id":"exchange-116"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それと、保健センターは子どもが生まれる前からのいろいろな支援から、本当に幅広いではないですか。自殺だったりとかそういうふうなところで精神的にもすごく追い込まれた方の相談を私たちも受けることがすごくあるのですけれども、いかがか尋ねました。","respondent":"飛田荏原保健センター所長","answer":"なかなか重い相談もありますので、そういう時は専門医の先生とも一緒に入ってもらって対応しているところです。いずれにしろ、今回はこういう自殺対応というところもありますので、その人それぞれの個別な、真髄というか、まずはお話をしっかり聞く。","id":"exchange-117"},{"speaker":"鈴木委員","kind":"質問・要望","question":"だから、私はここのところは保健センターの体制としてもっと充実をしていただきたいということをぜひ要望させてほしいと求めました。そこのところも説明を求めました。","respondent":"飛田荏原保健センター所長","answer":"経済的支援、そういうところはまた生活保護等の担当者とも連携しながら、生活保護の方と面談等もしていったりしているところです。病院にも入っていただきながら、また、施設のほうがいいのかというところで検討させていただいているところです。","id":"exchange-118"},{"speaker":"吉田委員","kind":"質問","question":"自殺ということで、自ら命を絶つことをどうにかしたいという気持ちは本当に同じです。具体的な、もう少し冊子を手に取ってしっかり読むとかいうことより、もう少しハードルの低い啓発のものは考えておられるのか伺いたいです。","respondent":"五十嵐保健予防課長","answer":"関心を持ってくださらない方たちに啓発していくというのは、とても難しいことだと感じております。何かいい手があったら逆に教えていただければ、こちらのほうも検討させていただきたいと考えていますので、よろしくお願いいたします。","id":"exchange-119"},{"speaker":"吉田委員","kind":"質問","question":"トイレの手を洗うところだとどうしても水分がありますので、カレンダーが有効かどうか分からないのですが、検討の余地はないでしょうか。いかがか尋ねました。","respondent":"五十嵐保健予防課長","answer":"インターネットゲートキーパーも含めまして、ゲートキーパー研修を皆さんに受けていただければと思っているところです。対策なりを考えていただけると本当は一番いいとは思っているのですけれども、なかなかそこにたどり着けないというところが現状かと思ってあります。","id":"exchange-120"},{"speaker":"吉田委員","kind":"意見","question":"ただ、この陳情の趣旨で言ったら、自死念慮のある方よりも周りへの啓発というか、そういうことが必要だよという趣旨だと思います。みんなが少しずつアンテナを高くするということが必要かと思いますので、難しいとは思いますけれども、今後も検討していただけたらと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-121"},{"speaker":"やなぎさわ委員","kind":"質問","question":"当然、実際に自殺者数の内訳も高校生が一番多くて３００人くらいですけれども、いわゆるゲートキーパー的な役割になると思うのです。１０代の方の自殺が増えているというところで、予定がもしあるのであればお伺いしたいのですが、いかがか尋ねました。","respondent":"五十嵐保健予防課長","answer":"新たに何かをやってくださっているかというところは難しい部分がありますが、計画のほうにも学校でいろいろなことをしていただいています。基本的にはまずはＳＯＳを出せるようにという教育をしてくださっているというふうに認識しています。","id":"exchange-122"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"所管が違うので難しいと思うのですけれども、一応学校の体制とかＳＯＳを出してもらうという自発的なところではなく周囲が気付く、今回の陳情がまさに啓発というところではあるのですけれども、その辺についてもし取組で分かることがあれば教えていただきたいのですが、いかがか尋ねました。","respondent":"五十嵐保健予防課長","answer":"保健予防課のほうで学校の先生たちを対象にしたゲートキーパー研修などは実施させていただいておりまして、受けていただいたりしながらその辺の生徒に対する対応とかを学んでいただいていると認識しています。","id":"exchange-123"},{"speaker":"鈴木委員","kind":"質問・要望","question":"２０代、３０代の死因第１位が自殺だし、４０代も悪性新生物に次ぐ第２位が自殺になっています。私はこの品川区の自殺対策計画の中間改定等がされたわけですから、せっかくこれだけの計画を出しているわけですから、いかがか尋ねました。","respondent":"五十嵐保健予防課長","answer":"区民に対する周知ですが、どこまでできるか分かりませんけれども、みんなと相談をしながら考えていきたいと思います。","id":"exchange-124"},{"speaker":"えのした副委員長","kind":"意見","question":"以前私も児童、生徒の保護者向けということで受講して、身近な人の悩み等に気づいたときにはどう関わっていくみたいなことは学ばせていただきました。理事者からもご説明がございましたが、自殺を防ぐ対策に取り組んでいただきながら…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-125"},{"speaker":"大倉委員","kind":"質問・要望","question":"例えば１０代の自死が一番多いというところでは学校での授業というのもありましたけれども、遊びと絡めてということは一つあるのかなと思います。区も様々やられている中でより一層やっていただくというところで、総合的にいろいろ進めていっていただければというところで、不採択とします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-126"},{"speaker":"あくつ委員","kind":"提案","question":"品川区自殺対策計画中間改訂が昨年あったということで、６つの基本施策の基に着実に進めていらっしゃる。この陳情の中にあるご提案ですけれども、課長のご説明とご答弁でそれに尽きると考えていますので、不採択としますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-127"},{"speaker":"鈴木委員","kind":"質問・要望","question":"品川区もこういう形で、これは本当に対策を取ることによって、だから本当に政治の課題として対策が求められているということだと思います。啓発や、それから相談体制の充実、そして具体的に支援というふうなところも含めて、もっと充実をさせることが求められていると思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-128"},{"speaker":"吉田委員","kind":"質問・要望","question":"陳情者が求めておられるのは周りへの啓発ですけれども、かなり難しい議論なのだということが分かりました。ですので、私としては継続で審査をしたほうがいいのではないかという思いです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-129"},{"speaker":"やなぎさわ委員","kind":"質問","question":"やはりそういった発信をするというか、啓発をすることは非常に大事なことだと思っていて、２００６年ですか。１万人くらいか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-130"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"本日結論出すということになりましたので、採択を主張させてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-131"}]},{"id":"topic-08","title":"令和７年陳情第４２号、犬猫の放置糞尿への対策と清掃費用の公平負担に関する陳情","agenda":"令和７年陳情第４２号、犬猫の放置糞尿への対策と清掃費用の公平負担に関する陳情","exchanges":[{"speaker":"やなぎさわ委員","kind":"確認","question":"この陳情に書いてあることの確認ですけれども、その辺の実態というのはいかがでしょうか。どれくらいの自治体があって、どういう罰則になっているのか、もしお分かりになればお願いいたします。","respondent":"赤木生活衛生課長","answer":"それ以外の自治体、２２区につきましては、特段罰則を設けているような規定はないというふうに認識しております。どちらかというと環境美化に関する条例の中で、犬の糞の放置に関して罰則を規定しているのが渋谷の条例というふうに認識をしています。","id":"exchange-132"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"具体的に分かればいいのですけれども、どういった過料になっているのか教えていただきたいです。","respondent":"赤木生活衛生課長","answer":"渋谷区の事例について、ご説明をします。公共の場所等で犬の糞を放置してはならないというところに違反した方につきましては、２万円以下の罰金に処するという形で制定をされております。","id":"exchange-133"},{"speaker":"やなぎさわ委員","kind":"質問","question":"その件は、承知いたしました。実際に、品川区にこういった犬猫の糞尿のトラブルというか、苦情の相談件数は大体年間どれくらいきていらっしゃるのか尋ねました。","respondent":"赤木生活衛生課長","answer":"前年度、令和５年度につきましては６６件で、令和４年度につきましては４１件という形です。令和５年度に比べますと、令和６年度については明らかな減少が見込まれておりまして。","id":"exchange-134"},{"speaker":"やなぎさわ委員","kind":"質問","question":"とういうことは、区としてはこういった啓発活動とか、そういったものを進めていくことによって、こういった陳情で出ているようなトラブルというのは減らしていけるというような、そういったお考えということでよろしいか尋ねました。","respondent":"赤木生活衛生課長","answer":"短期的にすぐに効果が出るものという形では思ってはおりませんけれども、粘り強く皆様方に正しいマナーの周知啓発というところをすることによりまして、こういった犬猫の糞尿被害に遭われる区民の方を１人でも少なくしようというふうに考えてあります。","id":"exchange-135"},{"speaker":"えのした副委員長","kind":"意見","question":"飼い主の基本的なマナーの問題でありますし、しつけの問題、マナーの啓発等を不採択の理由としております。引き続き、周知啓発の徹底をお願いいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-136"},{"speaker":"大倉委員","kind":"意見","question":"周知啓発については水をかけて少しでも尿を薄めていくとか、そういったこともやられている方が増えてきているのかと思います。マナー教室等様々やる中でこういった件数が減ってきているかというところも多少理解するところではありますので、不採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-137"},{"speaker":"あくつ委員","kind":"提案","question":"ご提案のような条例制定とか税金の付加というところのお気持ちは分かるのですけれども、行政として粘り強く取り組んでいく必要があるのかと思います。不採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-138"},{"speaker":"鈴木委員","kind":"意見","question":"結論を出すで、不採択でお願いしたいと思います。先ほどからも皆さんが言われているように、区の取組、そういうところを評価するということが最も大事なことではないかというふうに思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-139"},{"speaker":"吉田委員","kind":"質問・要望","question":"多分、これは糞のほうの話だと思うのですけれども、何年か前に尿のほうで電柱が倒れてしまったという事件があったのをご記憶ではないですか。でも、やはり公共物に実害が出たわけですから、そちらのほうの啓発も忘れずにぜひ進めていってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-140"},{"speaker":"やなぎさわ委員","kind":"質問","question":"夜よくジョギングをしていたものですから、下を見て走らないといつ踏んでしまうか分からない。かなり気苦労をされているのではないかとも思いますので、そういった方には個別にしっかりと寄り添った対応をしていただければというふうに思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-141"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/238890?Template=document&Id=7163#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":115042,"voices":399}},{"id":"r07-20250922-8","meetingId":"r07-cm09","date":"2025年9月22日","dateIso":"2025-09-22","committee":"建設委員会","time":"午前１０時００分～午後 ３時２４分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を91件整理しています。","topics":[{"id":"topic-01","title":"第１０５号議案、品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","agenda":"第１０５号議案、品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"この開発地域なのですけれども、地権者数について改めて伺いたいのですが、土地所有者数と借地権者数と集合住宅の区分所有者数を教えてください。地権者の中の賛同率、すなわち仮同意書を出した数と同意率というのですか、それを知りたいので、伺いたいと思います。","respondent":"森建築課長、大石まちづくり立体化担当課長","answer":"私からは敷地面積の最低限度の根拠についてご説明いたします。建築面積２００m2以上を確保するために敷地面積が２５０m2以上必要だというところから、最低限度を定めております。 区分所有のマンションといたしましては、３棟あるというように聞いてあります。賛同率につきましては、都市計画決定時点では７９.３％、約８割の方から仮同意をいただいているというように聞いてあります。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"すみません。それでマンションが３棟あるということなので、その区分所有者数も伺っていますので、説明を求めました。","respondent":"大石まちづくり立体化担当課長","answer":"集合住宅の区分所有者数については、区のほうではちょっとまだ聞いていないです。","id":"exchange-002"},{"speaker":"安藤委員","kind":"意見","question":"地権者の同意率は７９％と、８割いっていないということです。私たちとしては、これに賛同するわけにいかないなと考えておりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"範囲など、何か変更があったのか、ちょっとそこをご説明ほしいと求めました。「建築確認申請時の審査対象となるよう」ということはどのようなことなのか、専門用語過ぎるので、かみ砕いてご説明いただけたらと思います。","respondent":"大石まちづくり立体化担当課長、森建築課長","answer":"委員ご指摘のとおり、当初は五丁目１０番地区としてまちづくり検討がされていたところなのですが、平成３１年から段階的に。範囲につきましては、７番地区と１０番地区に対しまして… 工事着手前の届出の際、地区計画に適合していない建築物に対し、適合していませんと勧告することしかできない状態になっております。この制限条例に当てはめますと、確認申請時に審査されますので…","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"北地区ということで、当初は五丁目１０番地でしたけれども、五丁目７番地の方も確認が取れた。建築用語というものは難しいですから、考え方としてはそのようなことなのか、そこを伺いたいと思います。","respondent":"森建築課長","answer":"条例化すれば、適合していない建物は着工できないということになります。こちらは既に都市計画決定されているものと同じになっておりまして、それ以外の条例化はできないというように決まっております。","id":"exchange-005"},{"speaker":"中塚委員","kind":"確認","question":"そのようなわけではないのでしょうか。建築確認審査で着工できるように進めていくというものなのか、そこが、改めてかみ砕いてご説明いただけたらと思います。","respondent":"森建築課長","answer":"敷地の最低限度２５０m2以上、壁面の位置は２ｍ以上離れたところ、ブロック塀等をつくれないようにするという制限です。この条例から直ちに高度な、高層な建築物をつくるというような制限にはなってございません。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問","question":"この建設委員会にも、この地域でのタワーマンション建設はやめてほしいと地域住民の方々の請願・陳情が寄せられている状況です。この中でこのような条例改正は、区民の声を正面から受け止めているものではないと私は思いますけれども、いかがか尋ねました。","respondent":"大石まちづくり立体化担当課長","answer":"防災性の向上やにぎわいの維持向上を図るためにどうすればよいか、自ら考え、長い時間かけて検討してきたものです。今回の地区計画を含みます都市計画につきましても、上位計画に基づきまして、将来像の実現に向けて区としても必要な計画と考えているところです。","id":"exchange-007"},{"speaker":"中塚委員","kind":"意見","question":"にぎわい創出といってこの間つくられているものは、１階、２階の低層部分へのテナントが入るだけです。利益を確保するためにつくっているものだと思いますので、これ以上の再開発は進めるべきではないと意見を述べておきたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"安藤委員","kind":"意見","question":"補助２９号線整備を契機に計画され、膨大なＣＯ２も新たに発生させ、共産党としては反対しています。それを実現、具体化させるための条例改正なので、反対ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"建設委員会の議論そのものとしては、これ以上の再開発は進めるべきでないという声が、圧倒的だと思います。これも１つの区民の民意の表れだと思いますので、新たな再開発を進める立場は見直しを検討していただきたいと、加えて要望したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"}]},{"id":"topic-02","title":"令和７年陳情第４０号、私有地のベンチ設置を支援する制度を求める陳情","agenda":"令和７年陳情第４０号、私有地のベンチ設置を支援する制度を求める陳情","exchanges":[{"speaker":"松永委員","kind":"質問・要望","question":"令和６年度が８件ということなのですが、その中で杉並区として、課題というものを伺っていたら教えてほしいと求めました。設置してくれという要望があれば対応するということなのですけれども、実際、今の現在、どのような形でお声を伺っているのか、現状を説明を求めました。","respondent":"櫻木地域交通政策課長","answer":"はやはり思っていたよりもちょっと申請が伸びないというか、なかなか申請する側にもハードルがあるというようなお話を聞いているところです。予算等様々、安全面等条件整えば、区としては設置を検討していきたいと思っているところです。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問・要望","question":"現状として、この間そういった要望について、お休み石に限らず、区にどれぐらい届いているのかということを伺いたいです。区のお休み石の分布の現状の認識について、何かあれば教えていただきたいなと思います。","respondent":"櫻木地域交通政策課長","answer":"基本的にこのお休み石の設置につきましては、やはり道路状況、歩道の状況が大きく影響してまいります。八潮に関しては、バス停が多いということで一定ベンチの代わりになっているのかなと考えているところです。","id":"exchange-012"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、それはぜひやっていただきたいと思うのですけれども、いかがでしょうか。私有地内のベンチ設置を増やすこと、区内にベンチ等を増やすことについて、進めたいという考えを持っていらっしゃるのかどうか伺いたいと思います。","respondent":"櫻木地域交通政策課長","answer":"２点目が、ご要望に応じて、そこが適地かどうかという形で対応させていただければと考えています。私有地につきましては、先ほど説明の中で申し上げたとおり、一定課題があるのかなと考えています。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"ご要望に応じて対応していきたいということです。ただその要望について、区民としても要望は出せませんし、もったいないなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"幾つか伺いたいと思うのですけれども、このしながわお休み石事業というのでしょうか、結構長く続いていると思うのです。例えば１基当たりどれぐらいの寄附なのか、それとも１００％区の予算でやっているのか、全体像をご説明ほしいと求めました。","respondent":"櫻木地域交通政策課長","answer":"お休み石の設置についてです。基本的には委員ご認識のとおり、例えば名前を入れて設置したもの、または区が１００％設置したものと。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"導入当時はそのような趣旨で始まったけれども、区民の方の要望を受けて、１００％区の予算で設置をしているところもあるということなのですね。利になるというか、優しいまちになるのではないのかなと思うのですが、その点についても伺いたいと思います。","respondent":"櫻木地域交通政策課長","answer":"今、基本的に区では維持管理をベースにしております。は維持管理に努め、必要に応じて検討させていただきたいとは思っておりますので、そのような形で対応させていただければと考えています。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"要望があればお休み石の設置も検討するということですけれども、ただ、いわゆる民有地での設置というものは基本難しいという立場なのでしょうか。何というのですか、結構広めに取って、そこで様々な行事をしている。","respondent":"櫻木地域交通政策課長","answer":"陳情にありますように、民有地へのベンチの設置です。デメリットありますので、そこを勘案してご検討いただくことが、現時点ではよろしいのかなと考えています。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問","question":"ですから、このしながわお休み石としての設置は、今、民有地はできないということでよいのですよね。すみません。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"ゆきた委員","kind":"確認","question":"１点だけ確認できればと思います。杉並区は、閑静な住宅街が多いという、印象があるのですけれども、実際のところ、この容積率というものはどうなのかを教えてほしいと求めました。","respondent":"森建築課長","answer":"今、準防火地域内の準耐火建築物以上ですと、実質品川区の場合はほぼ建蔽率７０％の広さまで建てていいということになっております。そのため、あまり敷地に余地がない状態が発生しています。","id":"exchange-019"},{"speaker":"ゆきた委員","kind":"確認","question":"建蔽率の間違いでございました。確認できました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"松永委員","kind":"質問","question":"杉並区の先ほどの現状をお聞きしますと、やはりまだ様々な課題がある。今後に向けてはいろいろ議論しながら進めていただければと思うのですが、今回については、現状等を鑑みまして、不採択といたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"杉並区の例が出されていましたが、こちらは建蔽率がかなり違うので、簡単に当てはめることもできない点も確認させていただきました。今後も区民の声を聞いて、ニーズのあるところへは精査をして設置を進めていただくことを要望して、不採択でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"安藤委員","kind":"意見","question":"採択でお願いしたいのですが、まだまだ地域的な偏りなどもあり、ベンチがない地域もたくさんあります。民地への設置支援も含めて、ベンチを増やしていくということは大変重要なことではないかと思いますので、採択でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問・要望","question":"要望があればしながわお休み石を設置していきたいということでしたけれども、いわゆる民有地での設置は行っていないということが確認できました。その中で生活しているわけですから、一人ひとりの区民の暮らしのしやすさ、そこにしっかり目を向けることが必要ではないかなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"}]},{"id":"topic-03","title":"令和７年陳情第４１号、小山三丁目第一地区本組合設立申請取り下げ、「直近総事業費」・「資金計画」・「工期計画」・「時価補償費」等の確認と公表を求める陳情","agenda":"令和７年陳情第４１号、小山三丁目第一地区本組合設立申請取り下げ、「直近総事業費」・「資金計画」・「工期計画」・「時価補償費」等の確認と公表を求める陳情","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"そして区分所有者の方々はじめ、同意されていない実人数というものは何人なのか、改めて確認させていただきたいということが１つです。この間様々再開発を進めてきた現場にいるわけですけれども、法改正の必要性というものを感じているのかいないのか、伺いたいと思います。","respondent":"中道都市開発課長","answer":"マンションの区分所有者を１とみなすことといったことについて、まずは行政として対応するというところがあると考えています。先ほどもご説明したとおり、１名ご理解が得られるように調整を行いまして、今現在８４％の方が同意をしているというような状況です。","id":"exchange-025"},{"speaker":"安藤委員","kind":"確認","question":"何か前もちょっと間違えてしまっていたようなので、確認です。ちょっとそこだけ先にお願いします。","respondent":"中道都市開発課長","answer":"すみません。未同意の方は３５名になります。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺いたいことは、この資料に任命と委嘱というように書いてあるのですけれども、任命と委嘱の違いというものは何なのか教えていただきたいということ。それと現在、現状会長と副会長の方はどのような方が就任されているのか伺いたいと思います。","respondent":"高梨都市計画課長","answer":"区長が任命した人を、品川区としては都市計画審議会の委員として、手続としては委嘱をする、お任せをするということで考えているところです。会長の職務代理者、こちらについては、別の区でまちづくりのご経験のある学識経験者の方を任命しています。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、少なくとも十分な判断の材料を集めるべき、そのような情報提供というものを行わなければいけないと思うのです。そういったように改善していく必要があると思うのですが、いかがか尋ねました。","respondent":"高梨都市計画課長","answer":"開発事業の名称ではお答えはできませんが、区建築職として、幅広く区内のまちづくりの事業に携わった人材であるというように把握しています。２つ目の、今ご提案がありました現地視察等々の実施につきましては、区としてそれを実施するということは考えてございません。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問・要望","question":"それで３つ目なのですが、この資金計画等、まず認可申請が出された現在の事業費と補助金額を改めて伺いたいと思います。伺いたいと思います。","respondent":"中道都市開発課長","answer":"資金計画の件についてですけれども、すみません、今資金計画に関する資料がないので、後でご説明いたします。どの程度変更なのかというところもありますが、その認可申請というものは特に変更するものではない、取り下げるものではないと考えています。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問・要望","question":"８ページの下のほうでもそうなのですが、工期計画等の公表を求めているのに、それを明らかにしないということが許されるのかなと。これがまともな開発準備組合の運営と言えるのかなと思うのですけれども、その点についてはいかがか尋ねました。","respondent":"中道都市開発課長","answer":"令和７年７月１７日から７月３１日に事業計画書の縦覧期間というものがあります。こちらのほうは、窓口またはホームページ等で縦覧可能というところで、その中で資金計画も記載されているです。","id":"exchange-030"},{"speaker":"安藤委員","kind":"質問・要望","question":"今、直接理事長から説明を伺いたいのだと面談を何度も求めているのですけれども、それで品川区に仲介を求めております。品川区としては、このささやかとも言える地権者の方の求めに応じて、どう対応しているのか尋ねました。","respondent":"中道都市開発課長","answer":"全員が話すのではなくて、話す人間も限定するので、その１７名で話せないかというところを言われているような状況です。〔傍聴席にて騒ぐ者あり〕","id":"exchange-031"},{"speaker":"安藤委員","kind":"質問・要望","question":"最低限、この面談というものが実現するまでは、東京都に対して認可の決定は行わないでほしいというように求めるべきだと思うのです。それは、私は最低限のやらなくてはいけない、この決議にあるような努力だと考えていますので、そこについてどう考えるか伺いたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"},{"speaker":"安藤委員","kind":"質問・要望","question":"要望に応えず、東京都に出したのは品川区なわけですし、都市計画決定したのも品川区なわけです。ですから、会議のセッティングに向けて努力していますということは伝えて、もう一度伺いたいと思います。","respondent":"中道都市開発課長","answer":"法律にのっとって、行政としては対応していくものです。条件が様々ありますけれども、区としては会談が成立するよう、引き続き調整はしていきたいと考えています。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですからその中で、では品川区は何も一言も言えないのか、何も口出せないのか、何も意見を言えないのかというと、そのようなことはないと思うのです。ですから、ぜひ強く現状をまず東京都に伝えていただきたいということを申し上げたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"中塚委員","kind":"質問・要望","question":"順番に伺いたいと思うのですけれども、まず陳情要旨の１番目に、根拠を明らかにしてほしいと求めましたと声が寄せられております。伺いますけれども、森澤区長が引き継いだ区の計画で区民が苦しめられていると、その自覚はあるのか伺います。","respondent":"高梨都市計画課長","answer":"今現在の品川区において、必要なまちづくりの方針であるというように認識しています。この方針に従って進めてまいりますけれども、そこに住む住民の方々がしっかりと話し合っていただいて形づくっていくもの、このように認識しています。","id":"exchange-035"},{"speaker":"中塚委員","kind":"質問","question":"以前もこのことを伺うと、いやいや、策定委員会を開いて、パブコメもやって策定したもので、今後も続けていきたいと、言っていました。少なくともそうした声が上がっていることに、私は正面から受け止めるべきだと思いますが、改めていかがか尋ねました。","respondent":"中道都市開発課長","answer":"区といたしましては、日々準備組合に対しては、地権者の方々に対して丁寧な対応を行っていただきたいということは指導しているというような状況です。これが組合になった際には、生活再建といったところも、より具体に丁寧にご説明をしていきたいとは考えてあります。","id":"exchange-036"},{"speaker":"中塚委員","kind":"質問・要望","question":"有権者の発言は一切なくというところで、率直に言って私も形骸化されていると考えていますけれども、区の認識はいかがでしょうか。あまりにも独立性の担保になっていない、私はそう思いますけれども、いかがか尋ねました。","respondent":"高梨都市計画課長","answer":"そういった対応を行って、丁寧な対応を行わせていただいていますので、区としては。元部長が会長をやっているからといって、区の事業に対して恣意的なものが働いているという認識は、区としては持ってございません。","id":"exchange-037"},{"speaker":"中塚委員","kind":"質問","question":"その１７名ですか、代表質問の質問、この都市計画審議委員の方々に伝えられているのか。自民党の代表質問ぐらいですか、品川区まちづくりマスタープランに則って武蔵小山にタワーマンションをさらに進めてほしい、そのようなことの発言は。","respondent":"高梨都市計画課長","answer":"今後区の中でも、今そういったご指摘があったといったところを受け止めて、考えてまいりたいと感じております。次に、事前説明の際に特段議会の質疑の詳細を記載したようなペーパーをつくって説明するというようなことは行っておりません。","id":"exchange-038"},{"speaker":"中塚委員","kind":"質問・要望","question":"それはそれで一人ひとりの意見ですから、それは審議委員の方々が自分の責任で判断すればいいのですけれども、議会の質疑が伝わっていない。議会の質疑は審議委員に、口頭ではなく資料もつけて伝えてほしいと求めましたが、いかがか尋ねました。","respondent":"高梨都市計画課長","answer":"審議の内容がご覧いただけます。今までもしてきたつもりではおるのですけれども、改めてこれからもご案内をしていきたいと考えています。","id":"exchange-039"},{"speaker":"中塚委員","kind":"質問・要望","question":"これは今日の冒頭の説明では特に触れられていなかったので、配られていたのかどうか伺いたいと思います。家賃、これらが高騰しているという認識なのか、併せて伺います。","respondent":"高梨都市計画課長、中道都市開発課長","answer":"私からは、都市計画審議会での配付資料についてお答えをいたします。国会決議の資料につきましては、都市計画審議会では配付してございません。 今現在工事費が高騰しているというところで、こちらのほうは資材の高騰や、または人件費の高騰といったところが原因です。ですから、市街地再開発事業がこのマンション事業に対しての価格をつり上げているのかというところは…","id":"exchange-040"},{"speaker":"中塚委員","kind":"質問・要望","question":"これは審議会を待たずに配っていただきたいと要望しますけれども、いかがでしょうか。その１つの資料がこの国会決議だと思いますので、審議委員の方には直ちにまずは配ってほしいと求めましたが、いかがか尋ねました。","respondent":"高梨都市計画課長、中道都市開発課長","answer":"審議会での資料の配付のご要望についてなのですが、ご要望として承りまして、今後考えてまいりたいと思います。 昔に比べて、今つくれる住宅の面積が減っているというところで、需要と供給が原因というところもあるかというような考えです。市街地再開発事業自体が、そういったマンションの価格をつり上げているというような考えではございません。","id":"exchange-041"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後にこのことについて伺いたいのですけれども、かつて濱野区長は、こう述べておりました。なぜならば、その森澤区長の引き継いだ計画で区民がこれだけ苦しめられているわけですから、いかがか尋ねました。","respondent":"中道都市開発課長","answer":"そうした地域住民の声により耳を傾けて真摯に受け止めていくということをご発言なさいました。皆様が合意の上でまちづくりが進められるように、また、行政としても調整などを行っていきたいと考えています。","id":"exchange-042"},{"speaker":"中塚委員","kind":"質問","question":"というところが濱野区長との違いといいますか、森澤区長による追加といいますか、ということになるのでしょうか。もう一度ご説明ください。","respondent":"中道都市開発課長","answer":"森澤区長のほうで、繰り返しになりますけれども、様々な声がまちづくりにはあるというところで、そういった声により耳を傾けて、真摯に受け止めていくとしています。","id":"exchange-043"},{"speaker":"中塚委員","kind":"質問・要望","question":"聞きたいことは、１７人の何が問題なのかということと、理事長は現れず、事務局長が来たと、これ問題ではないですか。伺います。","respondent":"中道都市開発課長","answer":"そういった対話を重ねていくことがまちづくりのプロセスと考えているです。〔傍聴席にて騒ぐ者あり〕 その地区の中だけでなくて、再開発事業全般の考え方など、そういった考え方なども聞きたいというところで１７名と聞いてあります。引き続き区といたしましては、会合が成立するように調整はしていきたいと考えています。","id":"exchange-044"},{"speaker":"中塚委員","kind":"質問・要望","question":"森澤区長自身がいろいろ耳を傾けてまいりますと言っているわけだから、要請に応じて応える、それを準備組合に求めていく。住民の皆さんに少しご遠慮くださいなどということはとんでもない話だと思いますけれども、いかがか尋ねました。","respondent":"中道都市開発課長","answer":"一方で相手方といたしましても、そういった様々な再開発について聞きたいことがあるというところで１７名でとおっしゃっているですので……。〔傍聴席にて騒ぐ者あり〕","id":"exchange-045"},{"speaker":"中塚委員","kind":"質問・要望","question":"いずれも求められているわけですから、直ちにこの会合を設定してほしいと求めました。これ最後にしますので、いかがか尋ねました。","respondent":"中道都市開発課長","answer":"以前はこういったフリージャーナリストの方も含めた区へのお問合せといった形では、私のほうで対応などしてきました。準備組合の考え方、相手方の考え方というものがありますので、会合に結びつけていきたいと考えているところです。","id":"exchange-046"},{"speaker":"松永委員","kind":"意見","question":"主な理由は３点あります。地権者の賛同について地権者の８割弱の方がこの計画に賛同しており、３つ目が、陳情第４１号の陳情につきましては不採択といたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"},{"speaker":"ゆきた委員","kind":"確認","question":"２についても、見識のある構成メンバーへ、事前に資料と説明があった上での審議である点を確認できました。３、未同意の地権者により丁寧な対応を進めるように継続して準備組合の組合のほうには指導している点が確認できましたので、不採択でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-048"},{"speaker":"安藤委員","kind":"質問・要望","question":"私たちは採択を求めるのですが、重要な決定を行う都市計画審議会を改善してほしいという内容、国会決議に基づいて区が指導を強めてほしいという内容。その実現を区に対して求めている理事長との会談というものは、さらなる、品川区としても意見を述べてほしいなと改めて要望したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-049"},{"speaker":"中塚委員","kind":"質問・要望","question":"議会の質疑の圧倒的は再開発に反対、再開発の中止、やめてほしいが質疑の圧倒的な時間を割いております。これも議会の姿だということで受け止めていただきたいということと、そのことを伝えていただけるよう要望して終わりたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-050"}]},{"id":"topic-04","title":"大崎駅東口第４地区に関する都市計画案","agenda":"大崎駅東口第４地区に関する都市計画案","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"これは仮同意書というものを提出を求めていると思うのですが、それがどれぐらい提出されているのかお伺いします。マンション、集合住宅の区分所有者は何人いるのか、そして同意率はどれくらいなのかということをお伺いしたいと思います。","respondent":"中道都市開発課長","answer":"１番のこれまでの経緯にも記載のとおり、改定といったところを行いまして、この地区をどのようなまちにするかといった意見を踏まえて進めてきたです。今委員からお話のございました仮同意というところも、今回こういったまちづくりを進める上で…","id":"exchange-051"},{"speaker":"安藤委員","kind":"確認","question":"いや、もう猶予期間を２年間あるとはいえ、７月１日から外れているのですが、外れた地域という認識でよろしいかということを確認させてください。そういった意見について対応は取られたのか、それとも未対応のまま区は都市計画手続に入ったのか、そちらを伺います。","respondent":"中道都市開発課長","answer":"事業者説明会といったところを令和６年７月から行ってございまして、特に影響等はございません。事業者説明会から約１年ちょっと期間があったですけれども、早急に何か対応しなければいけないというところではないというところは。","id":"exchange-052"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後にもう一つ、今回の計画でものづくり産業をリードする拠点というものは、どこに何ができるのでしょうか。お伺いします。","respondent":"大石まちづくり立体化担当課長、中道都市開発課長","answer":"その後に３月に、今回の１７条に基づく説明会ということで、案の説明会という形で、区としては２回の説明会となっています。事業者の説明会を含めますと、令和６年の１２月に事業者説明会をやっておりまして… こちら地区計画は、ブリリアタワーの周辺も含めて地区計画を定めているというところで、別紙１でいきますと、Ｅ地区がブリリアタワーになります。大崎のもともとのものづくりというところは継承しつつ…","id":"exchange-053"},{"speaker":"安藤委員","kind":"質問","question":"１０月にあるということなのですけれども、これらの意見を踏まえて、この案を作成する上で何か変更することというものはあったのでしょうか。この段階では、もし何も変更しないということなら何のための説明会なのか、意見書提出なのかということを伺いたいと思います。","respondent":"中道都市開発課長","answer":"品川区としましては３０年以上まちづくりを進めてきたというところで、そこは今後ご理解をいただくようにお話をしていきたいと考えています。東京都といたしましては、原案に対して、今回の案を変更するものではないというようなところで進めているというように聞いてあります。","id":"exchange-054"},{"speaker":"安藤委員","kind":"質問・要望","question":"何というか、拙速に開くべきではないと思いますけれども、いかがでしょうかということを伺いたい。相談した上で、この説明会の案内を送付を求めますけれども、いかがか尋ねました。","respondent":"中道都市開発課長、高梨都市計画課長","answer":"様々な上位計画の中でまちづくりの方針を示し、一定程度の同意もある中で進めていくものですので、区といたしましては手続を中断するといった考えはございません。 都市計画審議会委員への説明会の案内についてですが、ご要望として受け止めさせていただいて、考えてまいりたいと思います。","id":"exchange-055"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ考えた上で実行に移していただきたいなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-056"},{"speaker":"中塚委員","kind":"質問・要望","question":"大崎駅東口第４地区の開発事業を進めている事業者にも、こうした議会の議論を伝えてほしいと求めましたが、いかがでしょうか。都市計画原案の説明会、これを行うということに許可したのは誰か、伺いたいと思います。","respondent":"中道都市開発課長","answer":"そういった説明会等があった際には、または事業者のほうにも、区として報告をするといったところです。準備組合のほうは平成２７年、そうした中でまちづくりの検討を行い、現在の状況に至っているです。","id":"exchange-057"},{"speaker":"中塚委員","kind":"質問","question":"もちろん規模が大きいですから、ぜひ進めてほしいという立場なのか、そこを伺いたいと思います。それに対して森澤区長は、なぜこれを進めたい、期待したいと言うのか、そこも伺いたいと思います。","respondent":"中道都市開発課長","answer":"今回地区計画の決定権者、区といたしましてもこれを進めるというところを決定して、東京都と意見交換を行っているです。進める理由ですけれども、または副都心といった形で選定されている地区であるなど、総合的に踏まえて進めているです。","id":"exchange-058"},{"speaker":"中塚委員","kind":"質問","question":"本会議で区長が述べた住民本位のまちづくりとは、２割が反対しても進めるということになるではないですか。いかがか尋ねました。","respondent":"中道都市開発課長","answer":"一方で、今回８割という数字の方々が都市計画を進めてほしいという意見もありますので、区としては、今回こういった形で手続を進めているです。そうした中で、いわゆる、１人でも多くの方に理解をいただけるように進めていきたいと考えています。","id":"exchange-059"},{"speaker":"中塚委員","kind":"質問・要望","question":"まだよく分からないという意見も伺いますけれども、やはり再開発は人の人生も財産も奪う、ひどい計画だということを述べておきたいと思います。ここで書かれている意見や質問や主な意見というものを、ぜひ私に見せてほしいと求めましたが、いかがか尋ねました。","respondent":"中道都市開発課長","answer":"今回、この意見書の提出というところで、概要の部分を主な意見として載せてあります。今回こういった意見書の取りまとめは東京都が行っているところですので、そういった意見があったということを東京都のほうに伝えてまいります。","id":"exchange-060"},{"speaker":"中塚委員","kind":"質問・要望","question":"伺いたいことは、この言葉でなぜタワーマンションと高層オフィスビルの乱立になるのか、私には理解できないのです。なぜタワーマンションになるのか、なぜ高層オフィスビルになるのか、これでなぜここで言っている課題が解消するのか伺います。","respondent":"中道都市開発課長","answer":"今中塚委員からいただいたご意見を都に伝えてまいりますという形でご回答させていただいたです。そうした中で大街区化を進めると、または緑の緑地率も上がるというところで、そういった中で様々なある課題を解決して整備していきたいです。","id":"exchange-061"},{"speaker":"中塚委員","kind":"質問・要望","question":"そのオープンスペースをつくるために、なぜ１４０ｍものマンションを２棟、１００ｍものオフィスビルを２棟つくるのですか。こうしたまちづくりは抜本的に改めるべきだと思いますが、いかがか尋ねました。","respondent":"中道都市開発課長","answer":"意見書ですけれども、次に都市計画案の説明会があり、また、意見募集を行います。そうした中で緑地率も上がり、オープンスペースもあるというところ、様々な効果の中で市街地再開発事業を進めていくというものです。","id":"exchange-062"},{"speaker":"中塚委員","kind":"質問・要望","question":"復旧するには、許可を得た専門家の人が立ち会って安全を確認しないと復旧できません。どのようなまちがいいか住民とよく対話して、まちづくりマスタープランの改定も強く求めて終わりたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-063"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"１点だけ確認させてほしいと求めました。こういったお声を柔軟に受け付けてほしいと求めましたけれども、この辺のことについて要望も含めてお聞きできればと思います。","respondent":"中道都市開発課長","answer":"防災力に向上したまちづくりというものを進めていきたいと考えています。地域の声は柔軟に対応していきたいと考えています。","id":"exchange-064"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"避難動線としての機能について、このデッキの高さと、あと広場の空間の整備というところにおいても、私も確認させていただきました。さらに区民の要望を柔軟に取り入れていただけるように努めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-065"}]},{"id":"topic-05","title":"道路法第３７条に基づく道路占用の禁止又は制限区域等","agenda":"道路法第３７条に基づく道路占用の禁止又は制限区域等","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"都道や国道の緊急輸送道路はどのようになるのかということを伺いたいということと、このタイミングでの実施するのはなぜなのかということが２つ目。３つ目として、今回のこの制限で、この地域というものは具体的にどのように変わっていくのかと、もう少しイメージを教えていただきたいなと思います。","respondent":"川崎土木管理課長","answer":"災害に強い道路の整備というところでは、この緊急輸送道路において新設の電柱の占用を禁止するという取組を実施していきたいと考えています。３点目、この新設電柱の占用制限措置に取り組むものになりますので、災害に強い道路の整備というものを目指していきたいと考えておりま…","id":"exchange-066"},{"speaker":"安藤委員","kind":"質問","question":"電柱の新設は条件かなり制限されて、このルールの変更というものは分かるのですけれども、実際に無電柱化をしていくということになるわけでしょうか。その辺についての現時点での考えというのですか、このルール変更と併せての考えをお伺いしたいと思います。","respondent":"森道路課長","answer":"無電柱化につきましては、推進計画に基づいて優先順位を設定して、着実に進めているところです。現在も３路線で行っているところですけれども、抜く事業をやるということと、もう一度道の安全を進めていくということになるかなと思います。","id":"exchange-067"},{"speaker":"中塚委員","kind":"質問・要望","question":"伺いたいのですけれども、道路の占用の禁止ということ、これは要するに、新たな電柱は駄目ですよということでよいのか。理屈上１本もないことが一番安全なわけだけれども、なかなかそうもいかないというのであれば、そこをどう考えていらっしゃるのか伺いたいと思います。","respondent":"川崎土木管理課長","answer":"当面の間というものはどのぐらいかということで、非常にこの考え方は難しいとは思うのですけれども、やはり、そうですね、当面の間。やはり地域住民が受けているサービス利用の継続性、こちらにも十分配慮しながら慎重に進めていく必要があります。","id":"exchange-068"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後にやむを得ない事由による仮電柱のことですけれども、原則２年間は認めると。この協議というものは、最終的に認めるか認めないかは区の判断ということでよいのか、そこだけ最後確認させてほしいと求めました。","respondent":"川崎土木管理課長","answer":"そうですね。区の判断ということになります。","id":"exchange-069"},{"speaker":"ゆきた委員","kind":"確認","question":"別紙の道路法第３７条指定路線図にて、桐ケ谷通りを確認できたのですけれども、元なぎさ通りは確認できませんでした。こちらの理由について教えてほしいと求めました。","respondent":"川崎土木管理課長","answer":"3)の、ちょっと下に短く、かぎ括弧の下の棒のような、お分かりになりますでしょうか。そこが元なぎさ通りになります。","id":"exchange-070"},{"speaker":"ゆきた委員","kind":"質問","question":"分かりました。3)から7)にかけてつけられている赤い線が元なぎさ通りということでよろしいか尋ねました。","respondent":"川崎土木管理課長","answer":"3)が元なぎさ通りで、7)がちょうど東品川公園前辺りです。ちょっと分かりづらくて申し訳ございません。","id":"exchange-071"},{"speaker":"ゆきた委員","kind":"確認","question":"確認できました。新設電柱の配置の抑制に含めていく必要があるのではないかというように感じられますが、こちらについてのお考えについてお聞きできればと思います。","respondent":"川崎土木管理課長","answer":"根拠法に基づくと道路法第３７条第１項、まずこの８路線について制限する、今回実施するものになります。今後進めていく中で、支援に大きな支障が出るよう可能性も含めて、この大前提である最優先の緊急輸送道路についてかけていくものになります。","id":"exchange-072"}]},{"id":"topic-06","title":"勝島歩道橋補修工事","agenda":"勝島歩道橋補修工事","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今回橋梁の長寿命化の補修工事ということなのですけれども、耐用年数をいつからいつまで延ばそうという工事なのか伺いたいと思います。","respondent":"森道路課長","answer":"今回の勝島歩道橋、約４０年間経過しています。８０年、できれば１００年というように１つの目標を置いて、予防保全を進めていくです。","id":"exchange-073"},{"speaker":"中塚委員","kind":"質問・要望","question":"橋梁の長寿命化修繕計画ということで、計画どおりしっかり進めていただきたいと要望しておきたいと思います。だから、そこについてちょっとご説明ほしいと求めました。","respondent":"森道路課長","answer":"５年に一度定期点検を行いまして、また次の５年後に見させていただいて、少し難しいところがあるかなと思います。委員おっしゃるように、やはりまずはしっかりと機能を果たすというところをメインに考えながら、進めていきたいと考えています。","id":"exchange-074"},{"speaker":"ゆきた委員","kind":"質問","question":"この歩道橋の通行については閉鎖される期間というものがあるのかということが１点と、かなり不便を感じられるようになると思われます。その点と、利用への安全確保の対策、どのように行われるのかお聞きできればと思います。","respondent":"森道路課長","answer":"ですから、多少ご不便をおかけすることにはなろうと思いますけれども、そういった形で対応させていただきたいと思います。近隣の方々にしっかりとご説明をする、現地への掲示をあらかじめするなど、対応させていただければと考えています。","id":"exchange-075"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"この通勤の朝の時間と夕方の時間、この時間は避けて、進めてほしいと求めました。こちらについては要望で終わりたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-076"}]},{"id":"topic-07","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"共産党の石田ちひろ議員の質問で、区長は従来の海上ルートに戻すよう国に求めよから、羽田新ルートについて質問をしたいと思います。区長が大臣と会ったときのやり取りなのでしょうか、海からのルートを求めていきたいと、そのような趣旨の答弁があったと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-077"},{"speaker":"安藤委員","kind":"質問","question":"９月１８日のこしば議員の一般質問で、コミュニティバスの大崎ルートについての質問がありました。令和８年度上半期での実証実験開始を視野に入れてというような答弁があったと思うのですけれども、この間、伺えればと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-078"},{"speaker":"安藤委員","kind":"質問・要望","question":"あるいは今工事をされている最中の建設途中の排水施設の能力も含めて、改めて総点検というのですか、していただく必要があるのではないかと。なるべく被害が出ないようなハード整備につなげていってほしいのですけれども、点検というのですか、いかがか尋ねました。","respondent":"羽鳥防災課長","answer":"半地下の建物といったところは被害を受けているという状況で、今回、全域にわたって被害が発生したという認識です。ソフトも含めて、各課と情報を共有しながら、対策を進めてまいりたいと考えています。","id":"exchange-079"},{"speaker":"安藤委員","kind":"質問","question":"いざというときに、どうやったら皆さんの財産を守れるかというところで、やはり区の啓発メッセージというものは非常に大きいと思うのです。どのようなメッセージを考えているのかも含めて伺いたいと思います。","respondent":"羽鳥防災課長","answer":"品川区といたしましても、防災ポータル、防災アプリというものも今年度から実施をしていますので。メールを含めて、５月の段階では風水害の特集記事を書いておりますが、また改めて広報紙のほうで周知することも検討してまいりたいと考えております。","id":"exchange-080"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはり品川区も、一人で悩まず連絡くださいというようなことも含めて、ふだんからぜひ啓発してほしいと求めました。いつ災害が来てもおかしくない状況の中で、区としての日頃からのアナウンスというものは非常に大事にしていただきたいなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-081"},{"speaker":"松永委員","kind":"質問・要望","question":"設置状況について教えていただきたいということと、見舞金や被災証明証等を含めたコールセンターについて、どのくらいまで設置をされる予定なのか。もう終わってしまっているということを防ぐためにも、そういったところを区民への周知は必要だと思うのですが、いかがか尋ねました。","respondent":"羽鳥防災課長","answer":"夜間の対応もありますので、併せて翌日には電子申請を立ち上げまして、電子申請でも受け付けられるように体制を整えたところです。今後人材派遣等も検討しながら、なるべく通常業務のほうに職員戻したいと考えていますので、状況を見ながら整理して進めていきたいと考えています。","id":"exchange-082"},{"speaker":"中塚委員","kind":"提案","question":"その上で、まず伺いたいことは、１つ目は先ほど言ったように、今回のような降り方、私も今後も起きるのではないかと、思うのです。様々な委員からいろいろな提案がされるかと思いますけれども、今回の事態を何を教訓に、何を次回活かしていきたいと思っているのかとの意見を述べました。","respondent":"羽鳥防災課長","answer":"今回のような大雨が今後もあるのかどうかという区の認識ですけれども、品川区以外の地域で同じような大雨の被害があるというところです。今は支援メニューということで、そのような体制を取ってまいりたいとは、現状では考えてあります。","id":"exchange-083"},{"speaker":"中塚委員","kind":"質問・要望","question":"２時４５分ですから、結構もう降っている状態で立ち上がったなという印象なのです。基準があるのであれば、それをもっと今回の実態を反映したものに対応すべきなのではないかと思うのですが、いかがか尋ねました。","respondent":"羽鳥防災課長","answer":"７月１０日のときもそうでした。本部の設置基準といたしましては、すぐ本部立ち上げて、すぐ初動が取れるような中での体制づくりというものは必要なのかなと考えています。","id":"exchange-084"},{"speaker":"中塚委員","kind":"質問・要望","question":"応急処置が終わっているのですけれども、今後どうなるのか、その点だけ伺いたいと思います。も上がってしまったので、何とか追加の対策が必要かなと思うのですけれども、最後にいかがか尋ねました。","respondent":"関根河川下水道課長","answer":"今ご質問いただいた２点、回答します。あるいは区も連携して進めている、こういった取組を着実に進めていく、こちらが重要かなと考えているところです。","id":"exchange-085"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"現場を回ってくださって、被害状況を確認してくださっている姿を、防災服を来た職員の方々が回っている姿を拝見させていただきました。今回のような態勢は今回初めて行われたのか、今までも実施されてきたのか、そういったところも含めて教えてほしいと求めました。","respondent":"羽鳥防災課長","answer":"２５％未満以下の全職員を動員して本部を立ち上げるという態勢で、人数といたしましては約２００名を超える職員が対応に当たったという状況です。今週いっぱいは１００名態勢で、必要なサービスというものは継続できるように、外部の人材等の導入も検討しているという状況です。","id":"exchange-086"},{"speaker":"ゆきた委員","kind":"確認","question":"確認できました。両隣、例えばその申請があったご自宅の両隣についてもお声かけをしてくださっていたのか、この点についてお聞きできればと思います。","respondent":"羽鳥防災課長","answer":"周辺回って不在の方に関しましては、ご案内のチラシや何かをお入れさせていただいて、後で連絡取れるような体制で動きました。そのような形で対応させていただきました。","id":"exchange-087"},{"speaker":"ゆきた委員","kind":"質問","question":"ということは、申請があったご自宅の、先ほどと重複してしまうのですけれども、その周辺についてもお声がけをされているということで間違いないか尋ねました。","respondent":"森道路課長","answer":"それからその次の日の見舞金の対応につきましては、公園課等の土木部で対応させていただきましたので、私のほうからお答えをします。できる限り被災に遭われた方々に、見舞金など、区の支援を届けたいということでやらせていただいたところです。","id":"exchange-088"},{"speaker":"ゆきた委員","kind":"確認","question":"最後に１点なのですが、過去の浸水のときに、見舞金についてその場でお受けすることができたというお声もありました。こういったことは実際にあったのか、ここについても確認できればと思いますが、お願いいたします。","respondent":"羽鳥防災課長","answer":"今回の見舞金につきましては、当日、用意できている金額の範囲で１０軒の方には手渡しでお渡しができました。ただ、手元にあるのは限られた金額でしたので、それ以外の方は後日ご連絡いただいて、請求書を送っていただくような対応で現在も運用しております。","id":"exchange-089"},{"speaker":"せお副委員長","kind":"質問・要望","question":"１点だけなのですけれども、今回は落雷もひどくて、私も大井町をちょうど雷のひどいときに通っていました。そのようなことがあるものなのか、そういった想定などはあるものなのか、ちょっと教えていただきたいです。","respondent":"羽鳥防災課長","answer":"火災ではなく倒壊も、やはり大きな衝撃の場合はあると思いますので、一定の家屋への火災以外の被害というものも考えられるのかなと考えております。今、被害の状況等整理をいたしまして、そういった情報があるかどうかというところも、今後整理してまいりたいと考えています。","id":"exchange-090"},{"speaker":"せお副委員長","kind":"質問・要望","question":"ちょっとお困りのようだったので、ぜひお声聴いていただきたいです。要望で終わりたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-091"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/109228?Template=document&Id=7209#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":75086,"voices":245}},{"id":"r07-20250922-9","meetingId":"r07-cm09","date":"2025年9月22日","dateIso":"2025-09-22","committee":"文教委員会","time":"午前１０時００分～午後 ２時５１分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を89件整理しています。","topics":[{"id":"topic-01","title":"第１０６号議案、品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","agenda":"第１０６号議案、品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、国の政令や都の条例が改正されたので、区の条例を改正するというご説明がありました。経緯にはどういったことがあったのか伺いたいのと、今回この変更をすることによって、東京都とは変更が一緒なのかどうかを伺いたいと思います。","respondent":"石井学務課長","answer":"これを受けて、国家公務員も給与法の改正により各種手当が変更となったところです。東京都につきましても同じような形で改正を行い、東京都と補償内容を同一としておりますので、東京都と同じような形の補償となっています。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"私が聞いた背景というのは、人事院勧告が出た背景です。国が変更した背景を伺いたいのですが、いかがか尋ねました。","respondent":"石井学務課長","answer":"詳しい内容は人事院の資料になってありますが、私が今把握している限りでは、こちらは、子育てのしやすい環境を整えるというところから扶養手当の見直しを行ったと聞いております。","id":"exchange-002"},{"speaker":"のだて委員","kind":"意見","question":"配偶者の加算をなくすべきではないと思いますが、子どもへの加算を上げるというのと、介護補償を引き上げることはよいことだと思いますので、賛成いたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"}]},{"id":"topic-02","title":"第１０１号議案、令和７年度品川区一般会計補正予算（債務負担行為 文教委員会所管分）","agenda":"第１０１号議案、令和７年度品川区一般会計補正予算（債務負担行為 文教委員会所管分）","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"ほかにもあれば伺いたいと思います。今回は、新たに令和８年度の債務負担行為をするものではないということでいいのか、確認したいと思います。","respondent":"荒木学校施設担当課長","answer":"もう１つの債務負担行為の変更ですが、今年度分は変更ございません。令和８年度以降の出来高分にこちらのインフレスライドの増額分を載せている状況です。","id":"exchange-004"}]},{"id":"topic-03","title":"令和７年陳情第３５号、「税負担化」を「無償化」と言い換え、子どもにツケを回す修学旅行無償化事業の廃止及び、歳出削減と減税を求める陳情","agenda":"令和７年陳情第３５号、「税負担化」を「無償化」と言い換え、子どもにツケを回す修学旅行無償化事業の廃止及び、歳出削減と減税を求める陳情","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"前回６月３０日、似たような制服無償化の廃止で減税をというものがあったと思います。修学旅行費が１人当たりどのくらい負担になっているのか伺いたいのと、減税できる額を計算していましたら、伺いたいと思います。","respondent":"石井学務課長","answer":"高いところについては、今回につきましては７万９,０００円が一番高いところです。この形で実施した場合にどれほど減税ができるかということにつきましては、試算はしてございません。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問","question":"陳情の中に、公的支出の拡大が現役世代の手取り所得を減らすということが書いてありますが、実際そういうことになるのかどうか。答えられる範囲で伺いたいです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問・要望","question":"私としては、修学旅行費無償化をやったとしても、現役世代の手取り所得を減らすということにはならないと思います。自治体が、今回の修学旅行無償化も憲法２６条にもある義務教育の無償化をさらに区として進めていく一歩だと思いますので、ぜひ進めていただきたい。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"筒井副委員長","kind":"意見","question":"そして、今回の修学旅行費無償化の事業は令和７年度の予算で、新規の事業ということと、減税の効果も年額数百円で薄いということです。そうしたもろもろのことを考慮して、本件を不採択としますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"若林委員","kind":"意見","question":"これをどういうふうに再分配していくかというのが、端的に財政という言葉で表されると思います。そういう理由からも不採択という結論ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"のだて委員","kind":"質問・要望","question":"本日結論を出すということで、不採択です。私たちも義務教育無償化を求めてきた中で、修学旅行無償化を進めてほしいと求めましたので、不採択です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"品川区の皆さんの社会全体で支えていくというお話があったので、そういったところから、修学旅行無償化事業は進めてほしいと求めました。不採択です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"横山委員","kind":"意見","question":"区民の皆さんのベーシックサービスのベースになった考え方みたいなところが、もしかしたらちょっと分かりにくいところがあるかもしれません。そういった区の考え方を引き続き伝えていただきながら、お一人お一人のお気持ちにも寄り添った丁寧なご対応をお願いいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"}]},{"id":"topic-04","title":"令和７年陳情第３８号、区内公立校の校庭などにサンシェード（日よけ）の設置を進める陳情","agenda":"令和７年陳情第３８号、区内公立校の校庭などにサンシェード（日よけ）の設置を進める陳情","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"改めてその状況を区がどのように把握しているのか伺いたいのと、毎日放送の福岡県宗像市の玄海ゆりの樹幼稚園の放送を私も見ました。こうしたサンシェードを設置すべきと思いますが、補助制度もあるということですが、他自治体の取組などは調査しているのかどうか伺いたいと思います。","respondent":"荒木学校施設担当課長","answer":"ＷＢＧＴ、午後のすまいるスクールの時間などであれば校庭で遊ばせるといった形で、全く１日通して遊べない状況ではないということで認識しています。今後とも何かシェードに代わるものがないかというのは、調査研究を進めて改善策を検討したいと思います。","id":"exchange-013"},{"speaker":"のだて委員","kind":"質問","question":"すまいるスクールの時間というと、３時か４時ぐらいには遊んでいるということなのか改めて伺いたいのと、ＷＢＧＴがどういう値だと遊べなくなるのか。幼稚園や保育園についてもぜひ検討を進めていただけたらと思いますが、いかがか尋ねました。","respondent":"荒木学校施設担当課長、染谷保育施設運営課長","answer":"こちらは少し詳細な説明になりますが、主に熱環境に影響を及ぼすものとして、湿度と温度とあとは日射や輻射といった周辺の環境があります。３１以上になりますと… 各園の実情に応じて、現状もシェードをつけたり、場所によってはミストをつけたりという対応はしております。園と調整をしながら、今後もそういった設備も含めて、熱中症対策の物品の購入ができればというところは検討しております。","id":"exchange-014"},{"speaker":"のだて委員","kind":"質問・要望","question":"保育園、幼稚園では、現状もシェードを設置しているところがあるというお話でしたが、今、何園あるか分かれば伺いたいと思います。学校の校庭で遊べるかどうかは、熱中症にならないというのは前提ですが、ぜひサンシェードの設置を検討してほしいと求めました。","respondent":"染谷保育施設運営課長","answer":"現状の区立園３８園のうち、シェードが何園に設置されているかということにつきましては、申し訳ございません、今、手元に数字がございませんので、お答えは控えします。","id":"exchange-015"},{"speaker":"筒井副委員長","kind":"質問","question":"ピロティはどのぐらいの大きさで、具体的に一定の時間が来たら使うようにしているのか。運用方法を説明を求めました。","respondent":"荒木学校施設担当課長","answer":"こちらは全ての学校に設置しているわけではありませんが、代表的なところで言いますと、すぐに校庭からこういった日陰の部分に行き来できる状況です。例えば体育の時間に、先生から何か指導する際に…","id":"exchange-016"},{"speaker":"筒井副委員長","kind":"質問","question":"スプリンクラーで校庭を濡らすということですが、それは授業開始前にある程度濡らしておいて、それから授業を始めるということでよろしいのか尋ねました。","respondent":"荒木学校施設担当課長","answer":"スプリンクラーの利用時間帯ですが、授業開始前と部活動の開始前にも使用している学校もあると聞いております。","id":"exchange-017"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"自然災害のリスクもありますし、台風などの際、飛ばされる危険もあるというのが１点です。そういうのを今以上にしっかり活用していただいて、子どもたちが元気で遊べる環境の整備を、引き続きやってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"筒井副委員長","kind":"質問・要望","question":"今回のサンシェードは今後の参考の１つだと思いますが、サンシェードの設置は、現時点では難しいと考えております。熱中症対策をしっかり取りながら、サンシェード等も含めていろいろな暑さ対策をぜひ研究して、それを積極的に進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"若林委員","kind":"意見","question":"で、これはもう昨今の酷暑・猛暑の中では現実になっていますので、どうしたら子どもたちの健全な体づくりや運動の機会を確保できるのか。考えなければいけないと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"のだて委員","kind":"質問・要望","question":"いろいろ課題をクリアしながら、ぜひ進めてほしいと求めました。採択です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"高橋（し）委員","kind":"質問","question":"ですから、先ほど課長がおっしゃっていましたが、体育館などを活用した運動も学校で工夫しながら進めてほしいと求めました。ということで不採択です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"横山委員","kind":"質問・要望","question":"校庭に熱が籠もりにくくなるような土を利用するなど、様々な手法を研究してほしいと求めました。活動範囲の制限、安全性、メンテナンス作業等の課題があると考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"}]},{"id":"topic-05","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"単純な確認なのですが、資料を見ますと普通に道路を横断してきたということで、普通に見ると、運転していたら確認できる感じがしますが、なぜ交通事故になってしまったのか、伺いたいと思います。","respondent":"荒木学校施設担当課長","answer":"夕刻５時ぐらい、薄暗い時間に、学校施設の現場から帰ってくる職員が起こした事故です。その対向車に気をとられてしまい、その陰から横断してきた歩行者に気づかなかったという状況を聞いてあります。","id":"exchange-024"},{"speaker":"のだて委員","kind":"質問・要望","question":"暗い中だったということですが、今回、骨折もされているので、今後こういったことがないように十分気をつけてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"若林委員","kind":"質問","question":"この間、どういう経緯をたどってきたのか。この写真を見るとここは横断歩道もない場所なので、過失割合は何対何だったのか、詳細をお聞きしたいと思います。","respondent":"荒木学校施設担当課長","answer":"もう一点の昨年の１０月発生時からこの間まで間が空いたというところですが、特にこれは裁判になったものではございません。さらに賠償額の交渉を続けておりまして、ようやく両者で合意が図られましたので、このたび専決処分という形で処理をしたものです。","id":"exchange-026"}]},{"id":"topic-06","title":"学校プール施設の在り方の検討状況について（中間報告）","agenda":"学校プール施設の在り方の検討状況について（中間報告）","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"3)の屋上プール（屋根なし）というのが１７校で、９４％の実施率、平置きプールの屋根なしというのが１９校で、８２％の実施率ということです。１２％と結構差がありますが、なぜこうなっているのかというのを伺いたいのと、何度低くなったのかが分かれば伺いたいと思います。","respondent":"荒木学校施設担当課長","answer":"１点目のプール種別の3)の屋上プール（屋根なし）と4)の平置きプールの水泳授業実施率の差ですが、分析としては。幅が３メートル少ししか張っておりませんので、これを今後さらに広い範囲に設置することで、さらなる温度低減効果が期待できると考えています。","id":"exchange-027"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひそうした対策も進めてほしいと求めました。水泳授業を実施する前提の話になってしまうのですが、実施に当たっての判断基準は、どのようなものか、伺いたいと思います。","respondent":"荒木学校施設担当課長","answer":"水泳授業の実施の判断基準というところで認識したものですが、暑さ指数ＷＢＧＴの確認と、あとは熱中症警戒アラートが出れば当然中止という判断をしているものです。","id":"exchange-028"},{"speaker":"のだて委員","kind":"質問","question":"判断については暑さ指数もあるということですが、プールの水温とかプールサイドの温度といったことは関係ないのか尋ねました。","respondent":"荒木学校施設担当課長","answer":"詳細に答えられませんが、暑さ指数の確認と熱中症警戒アラートが出ていないかどうかという確認を行った上で、水泳授業を行っております。","id":"exchange-029"},{"speaker":"のだて委員","kind":"質問・要望","question":"熱が籠もりやすくて、水温も下がりにくいとあったので、水温がやはり関係してくるだろうということで確認させていただきました。しっかりと計画どおり水泳授業を実施できるように、基本屋根つきということで進めてほしいと求めましたが、いかがか尋ねました。","respondent":"荒木学校施設担当課長","answer":"資料に記載のとおり３０クラス相当以上、おおむね１学年５クラスを超えるような大規模校で、効率的な授業運営のために設置しているものです。ですので、資料で言うところの屋上プールに対して、シェードを設置するという方向で現在は暑さ対策を進めていこうと考えています。","id":"exchange-030"},{"speaker":"のだて委員","kind":"質問・要望","question":"建築の課題もあるというお話でしたが、ぜひ水泳授業が計画どおりに実施できるように進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"まつざわ委員","kind":"意見","question":"平置きプールはやはりなかなか稼働率が悪いというのが現状であって、サンシェードで５度、３度低くなったという実証実験は大変すばらしいです。例えば屋上プールに今サンシェードは検討の中にあるとのことですが、平置きのプールにそういう検討があるのかないのか…","respondent":"荒木学校施設担当課長","answer":"今回のサンシェードですが、今回の実証実験に関しては、屋上プールに設置しました。今年度中に4)の平置きプールに関しましてもシェードを設置して、来年の水泳授業に臨んでいこうと考えています。","id":"exchange-032"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"大きいから設置するのではなくて、小さくともプール授業ができない子どもはみんな一緒ですので、そこら辺のバランスはしっかりと考えていただきたい。そういった考えもいいと思っているのですが、そこら辺の課題に対して、今現状どういうことが話し合われているのか、説明を求めました。","respondent":"荒木学校施設担当課長","answer":"源氏前小学校などで、他校のプールを利用するためにバスを借り上げて、実証実験的にバスを運行してみようかと考えています。これで効果が得られれば、ほかの学校にも波及できるか検討したいと思います。","id":"exchange-033"},{"speaker":"横山委員","kind":"確認","question":"全ての子どもたちに水辺で身を守る知識と技術、水辺から命を守る総合水泳能力を身に付けてほしいと私は考えています。品川区において、どのような水泳教育が今後必要であると区はお考えなのかというのをまず確認させてください。","respondent":"荒木学校施設担当課長","answer":"さらには技術の向上を目指す中で、他者とのコミュニケーション力育成という観点からも、水泳授業の推進をしている認識です。今後も水泳授業を大切に実施していくために、熱中症予防をしっかりと取り、今後も水泳授業を絶やさぬように続けていきたいという考えです。","id":"exchange-034"},{"speaker":"横山委員","kind":"確認","question":"水辺の教育であったり、身を守るための教育であったりを品川区では大切に思っているということを確認できました。この５番、ここでまとめられた部分が表示されていると思いますが、詳細についてご説明いただけないか尋ねました。","respondent":"荒木学校施設担当課長","answer":"自校だけではなくて、水泳授業を行うには適した、非常に効率よく行える環境のプールを共同利用することも加えて検討を進めております。昨年度も実施した水泳授業実施状況調査を今年度も各学校に実施いたしますが、このような評価結果から、対策を向上させていこうと考えています。","id":"exchange-035"},{"speaker":"横山委員","kind":"質問","question":"５月や９月などに授業の時期をずらすという取組等があるかと思いますが、もしほかに教育委員会として何か事例等を把握していましたら教えてください。それぞれのメリット、デメリットについても教えていただけないか尋ねました。","respondent":"荒木学校施設担当課長","answer":"教育委員会としては、その授業期間と授業実施率との相関関係を各学校で共有できるようにするですとか、あとはプールの共同利用につきましても。その辺りは来年度の試行実施を踏まえて、対策を考えたいと思います。","id":"exchange-036"},{"speaker":"横山委員","kind":"質問・要望","question":"例えば防災教育など知識を付けるという総合的な観点から、子どもたちに水難事故の防止の部分で力が身に付くことが大切だと思っています。そうした防災の観点からも、体育に限らず、それを達成するための現実的かつ効率的なプールの在り方の検討をぜひ進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"},{"speaker":"高橋（し）委員","kind":"質問","question":"その辺りの方針は、まだ出てなければ出ていないでよろしいですが、今後の方針を伺いたいと思います。２つ目は、先ほどの共同利用の温水プールは、これは義務教育学校の４つを活用するという認識でよろしいか尋ねました。","respondent":"荒木学校施設担当課長","answer":"今後の施設の整備方針については、3)の屋上プールを基本として、シェードを設置する対応を進めていきたいと思います。来年度においては、委員がおっしゃっていただいたような区内の義務教育学校を中心とした温水プールの活用で共同利用していきたいと考えています。","id":"exchange-038"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"これは要望ですが、そういったところにも注意して、安全に進めてほしいと求めました。これは要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-039"},{"speaker":"若林委員","kind":"質問","question":"２割減ですか。各学校、屋上と平置きで構造が違うので何とも言えませんが、１校当たりのシェードを設置するための金額はどのぐらいなのか尋ねました。","respondent":"荒木学校施設担当課長","answer":"既存の設備、壁などで設置する場合であれば数百万円程度で済む場合もあり、かなり差が大きくなっています。そこに関しましては、安全でなおかつ経済的な方法を取れるように検討していきたいと考えております。","id":"exchange-040"},{"speaker":"若林委員","kind":"質問","question":"バスはどういうふうに調達するのかも含めて、先ほど７番の今後の進め方で、年度内に在り方という悠長なことを言っているのでしょうか。来年度きちんと３６校、少なくともきちんと手当てできるのか尋ねました。","respondent":"荒木学校施設担当課長","answer":"一方で、実施率が大分低く、６割、７割程度しか達成できなかった学校があります。こういったところを優先的に整備していくということで、来年度以降、継続して天候影響対策に取り組んでいければと考えています。","id":"exchange-041"},{"speaker":"若林委員","kind":"質問","question":"実施率というよりも、学校単位で見ていくほうが現実的みたいなのですね。平場にしても屋上にしても、そんなに温度が変わることはないような気がしますが、学校によって違う原因、要因は何か尋ねました。","respondent":"荒木学校施設担当課長","answer":"プール種別3)に関しましては、やはり高層部に設置してありますので、温度上昇の低減に役立っていると分析しています。基本的には、このシェード対策についても、4)の学校の実施状況を踏まえた上で対策を進めていくのがいいと現在考えております。","id":"exchange-042"},{"speaker":"若林委員","kind":"質問","question":"どうしても対応しなければ実施率が下がってしまうと、維持できないところについては、確実に担保していただくことが大事だというのが１つです。バスについての答弁をお願いします。","respondent":"荒木学校施設担当課長","answer":"バスの借り上げにつきましては、来年度は区役所のバスではなくて、民間のバスを確保するための予算を組もうと考えています。こちらもやはり１校当たり１００万円、こちらもより効率的に運行できる計画を立てたいと考えています。","id":"exchange-043"},{"speaker":"筒井副委員長","kind":"質問","question":"屋根を造る工期と、サンシェードを取り付ける工期の差というのは、どのくらいなのでしょうか。分かる範囲で。","respondent":"荒木学校施設担当課長","answer":"屋上プールの屋根に関しましては、整備段階のコストをご覧いただくと分かるかと思いますが、約７.５億円という非常に大きな額になっております。改築時に関しましても、基本的には3)の屋上プールを基本としながら、日よけシェードで天候対策をしていこうと考えています。","id":"exchange-044"},{"speaker":"筒井副委員長","kind":"質問","question":"プールの民間施設の活用です。区内にそれほどあるのかなという感じですが、大体何か所ぐらいを想定しているのか尋ねました。","respondent":"荒木学校施設担当課長","answer":"ただ、１０施設が全て使えるという状況ではなく、ヒアリングしたところで言いますと、そのうち数える程度しか使えないとは思っております。さらには当然コストもかかりますので、優先順位としては低いと考えています。","id":"exchange-045"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ですから、そこはぜひ教育委員会として実現するように、財政担当に要望してほしいと求めました。いかがか尋ねました。","respondent":"米田教育次長","answer":"その上で今後予算要求を行います。教育の所管としては、できることは次からやっていきたいと考えているところです。","id":"exchange-046"}]},{"id":"topic-07","title":"光林荘におけるトコジラミ発生に関する対応","agenda":"光林荘におけるトコジラミ発生に関する対応","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"６年生の移動教室も全て中止になったので、今までと大体同様の行程で行くのかどうか伺いたいのと、キャンセル料は幾らぐらいになるのですか。伺います。","respondent":"石井学務課長","answer":"なので、全く同じ行程になるかは、これから旅行会社等と検討した上で進めます。キャンセル料につきましては、もろもろこれまでかかったバスのキャンセル料がありますので、今計算しています。","id":"exchange-047"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、検討中とのことでしたが、ぜひ代替策をしっかりと実施できるようにしてほしいと求めました。今後の光林荘ですが、使用開始時期など見通しはどうなっているのか、伺いたいと思います。","respondent":"石井学務課長","answer":"光林荘は、教育委員会で実施する林間学園や移動教室等の受入先であると同時に、保養事業も実施しております。他の施設で実施することを考えておりますが、万全な対策を付した上で、来年度については光林荘で実施できるように進めていきたいと考えております。","id":"exchange-048"},{"speaker":"高橋（し）委員","kind":"質問","question":"その実施に向けてほぼ全校が行けるような感じなので、５年生、６年生の児童そして保護者の方にとっては楽しみな行事になると思います。いろいろな手だてを使って宿を探していただいていると思いますが、その辺の情報収集について、お話しできる範囲があればお伺いします。","respondent":"石井学務課長","answer":"まず我々学務課の職員が調べたところと、あと移動教室や林間学園を実施する際には、バスのところで旅行代理店を通じて行っております。さらに葛飾区が日光に施設を持っていることも我々は把握しておりましたので、そういったところの調整もしながら進めてきたという経緯です。","id":"exchange-049"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"事故やあるいは行程もいろいろ考えなければいけないと思うので、その点までしっかりと把握して、現場は大変だと思います。学校現場が円滑に日程をこなせるように協力していただきたいのですが、その辺りはいかがか尋ねました。","respondent":"石井学務課長","answer":"もちろん事業の実施に当たっては、現場職員による実地踏査は確実だと考えています。その一方で、これまでは光林荘という固定の施設で実施することを前提にプランが組まれていたものですから、今回分散するに当たっては。","id":"exchange-050"},{"speaker":"高橋（し）委員","kind":"意見","question":"毎回５年生、６年生が行っていたので、宿が変わってしまったから少しこういうところがみたいにならないようにお願いしたいのですが。最後、それだけですとの意見を述べました。","respondent":"石井学務課長","answer":"葛飾区の施設につきましては、同じような形で林間学園を実施していますので、児童・生徒にとっての対策は一定程度できているということ。ただ、日程も変わりますので、例えば夏季に実施する場合と今回別の日程で実施する場合でも配慮事項は変わってくると思います。","id":"exchange-051"},{"speaker":"まつざわ委員","kind":"質問","question":"以前、議論があったかもしれませんが、光林荘自体が安全宣言、できますよというのは、何を基準に誰が判断するのか、説明を求めました。","respondent":"石井学務課長","answer":"一義的には、保養事業として実施の部分があります。今、施設運営事業者と教育委員会と、あとは保養事業の所管である地域活動課が連携した上で判断することになろうかと考えております。","id":"exchange-052"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"例えばこういうのが出たときに、光林荘以外の区の施設とか、契約というと大げさでしょうか。要望です。","respondent":"石井学務課長","answer":"これは施設側と実施する側でまたいろいろ視点は異なりますが、トコジラミと疑われる虫と遭遇した場合のマニュアルを作成しました。そのときにはやはりそういった確認の徹底や発見したときの対応というもの、そして清掃の強化を求めていくと形になろうかと考えています。","id":"exchange-053"},{"speaker":"若林委員","kind":"確認","question":"８月１２日、過去の一般利用者からトコジラミの痕跡確認。経緯を説明を求めました。","respondent":"石井学務課長","answer":"こちら、８月１２日の過去の一般利用者は、教育委員会が実施しているものとは違う方なのですが、今年度、光林荘に泊まったことがあるという方でした。今のところ何か大きな被害があったということではなかったのですが…","id":"exchange-054"},{"speaker":"若林委員","kind":"意見","question":"８月１２日に情報提供があったと。過去がいつなのか、指定管理者はそのことをどういうふうに把握していたのか、していないのかというところは分かりますかとの意見を述べました。","respondent":"石井学務課長","answer":"報告があったのは８月１２日なのですが、品川区のこの事例がＳＮＳで大きく話題になったものですから、それでお電話をいただいたです。なので、それ以外の保養事業でもそういった話があったというところをお互い共有しながら、地域活動課と連携して今進めております。","id":"exchange-055"},{"speaker":"横山委員","kind":"確認","question":"先ほども議論で出てきましたが、マニュアルを作成したとお聞きしました。例えば今後発見した際の対応は、具体的にどのようなものなのかを確認させてください。","respondent":"石井学務課長","answer":"様々なフェーズにおいて対応方法が考えられると考えています。現場の先生がきちんと判断できるようにすることが一番ですので、そういった観点でマニュアルを作成したところです。","id":"exchange-056"}]},{"id":"topic-08","title":"学校給食における有機農産物等活用推進事業","agenda":"学校給食における有機農産物等活用推進事業","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"９月に最大実施しているところでは何日間やっているのかなど、現在の実施状況を詳しく伺いたいと思います。先ほど慣行品も見ながらどんな感触かという話でしたが、実際どういうことを検討、比較したのかを伺います。","respondent":"石井学務課長","answer":"すみません、今、数えたところで、何日連続で実施するかについては、細かい数字を持ち合わせてはいないのですが、学校によってかなり様々です。この試行実施期間に全品目実施できるように頑張りたいというのもありながら…","id":"exchange-057"},{"speaker":"のだて委員","kind":"質問","question":"なかなか大変そうな感じも受けますが、来年１月に全校で本格実施を予定しているということで、本格実施はどういうことなのか。その中身を伺いたいのと、この間実施してきている中での課題などがあれば、伺いたいと思います。","respondent":"石井学務課長","answer":"区立学校全４６校で本格実施予定とは、まずはやはり現場の負担なく、きちんと有機野菜を使った給食が提供できること。こちらを本格実施という形でさせていただきたいと考えております。","id":"exchange-058"},{"speaker":"のだて委員","kind":"質問・要望","question":"現場の負担なく給食を提供できるということでしたが、それは品目数とか日数とかも含めて、そういう部分は特になくということなのですか。改めて伺います。","respondent":"石井学務課長","answer":"先ほど説明の早期に申し上げましたが、今回いろいろメニューを試していく中で、やはり物理的にないものも多分出てくると思います。それらの課題をきちんと潰した上で実施するということで本格実施を考えてあります。","id":"exchange-059"},{"speaker":"まつざわ委員","kind":"質問","question":"ヒアリングについて、青果事業者は何社というのはお聞きしましたが、栄養職員というのは、結局３６校全校の栄養職員を集めたのか。ある程度試験的な導入ということで、まずはそこの職員のお話を聞いたのか、説明を求めました。","respondent":"石井学務課長","answer":"実施に当たっては、まず栄養職員で構成されている栄養職員会の幹部職員にはじめに意見を伺いました。それ以外に、月に一遍栄養職員会という会議が開かれておりますので、その会議の場で学務課の職員が説明をするプロセスを経ました。","id":"exchange-060"},{"speaker":"まつざわ委員","kind":"質問","question":"試験実施を踏まえて１月ぐらいから本格実施をしていこうというご予定がある中で、全学校分の野菜の量は、もう確保されているものなのか。まだそこら辺は確保していないけれど、最低限、少しずつならできるということなのか、現状を説明を求めました。","respondent":"石井学務課長","answer":"令和６年度に利用した野菜の品目から考えますと、ニンジン、もやしというものが全野菜の大体６割ぐらいの割合を占めてあります。当然生産者の協力が不可欠ですから、市場関係者でも生産者の理解を得られるべく、今いろいろと話合いを進めているところです。","id":"exchange-061"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"現場の方からも話を聞いているので、そこは本当に慎重に、また柔軟に対応してほしいと求めました。何が子どものためになるのかというところを念頭に置いた計画は持っておいていただきたいと思っていますが、いかがか尋ねました。","respondent":"石井学務課長","answer":"これはすごく大事なことであると考えております。これは日本の農業を応援していく上ですごく大事なことではありますが、そのために本末転倒になるようなことは避けたいと考えております。","id":"exchange-062"},{"speaker":"高橋（し）委員","kind":"質問","question":"それはプラス分ですから、１２円掛ける１００食という計算で、小・中学校でやっていたと思います。今回のこういった進め方だと、２,８００万円には届かないと思いますが、その辺りの予算的な今の見込みを説明を求めました。","respondent":"石井学務課長","answer":"ただ一方で、試行実施期間を含めて、本当に費用がどれぐらいかかるのかというものも併せて試行実施期間で検討するような形で進めております。これを持続可能にするためには、やはり費用もどれだけかかるのかも見ていかねばならないので、今そういった形で進めております。","id":"exchange-063"},{"speaker":"高橋（し）委員","kind":"質問","question":"３つ目は、２,８００万円は寄附で賄うという話が、この寄附金の扱いはどうするのでしょうか。ごめんなさい、所管が違ったら、そこで結構ですけれど。","respondent":"石井学務課長","answer":"そうしますと、単純計算で言いますとその２倍が年間かかる見込みです。年間の予算を立てるに当たっては、実勢に応じた上で、昨今の物価高騰といったことも含めてきちんと適切に対応していく必要があると考えています。","id":"exchange-064"},{"speaker":"高橋（し）委員","kind":"意見","question":"３月の段階でオーガニック等についていろいろ予算立てしていただきましたが、こういうふうに様々な変化について対応していかなければいけないと思いますので、今後また本格実施になったときには、適切に柔軟に対応して進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-065"},{"speaker":"横山委員","kind":"確認","question":"９月の試行実施の開始で、誰に対して、どのようなことを抽出してフィードバックを行うのか。抽出してフィードバックして、それがどのように反映されていくのか、スケジュール感と流れを確認させてください。","respondent":"石井学務課長","answer":"調理時の課題の抽出・フィードバックにつきましては、こちらは各校から週ごとに報告をもらうことになっております。どういうメニューで何を実施して、それをまた翌週には各学校にフィードバックしていくということを不断に行っていく想定で考えております。","id":"exchange-066"},{"speaker":"横山委員","kind":"確認","question":"１月の本格実施ということで、このタイミングなのかこの後になるのか分かりませんが、確認するところがあると思います。どうぞ。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-067"},{"speaker":"筒井副委員長","kind":"確認","question":"６月から８月がサンプル品比較会で学校栄養職員、当然ご意見を伺ったと思いますが、意外とポジティブな意見が多かったと思っています。結局ポジティブな意見が多かったのかどうかを確認したいと思います。","respondent":"石井学務課長","answer":"そういった中で、我々もきちんとできるということを信じながら進めてまいりましたが、どういった形になるのかは非常に不安ではありました。そういった課題が見つかった部分もありますので、引き続き現場と連携しながら進めていきたいと考えております。","id":"exchange-068"},{"speaker":"筒井副委員長","kind":"質問","question":"一方、全校の実施というのは来年１月ですが、スケジュールがもう立てられているということです。何か大きな課題があったら、検討や修正のために立ち止まるということも当然あり得るということでよろしいか尋ねました。","respondent":"石井学務課長","answer":"もちろんこの事業に関しましては、様々な方の意見を取り入れながらつくり上げていくという姿勢で臨んでいきたいと考えております。そういった意見を取り入れながら、一つ一つ進めていきたいと考えております。","id":"exchange-069"},{"speaker":"筒井副委員長","kind":"質問","question":"今回２,８００万円の寄附を受けたわけですが、３月の予算特別委員会で、その手続はどうされるのかということが結構話題になりました。それについて、８月の広報しながわの寄附者一覧には１行載っていましたが、その辺の公表のお考えというのは何かありますか尋ねました。","respondent":"石井学務課長","answer":"農林水産省の支援につきましては、残念ながらいわゆる金銭的支援はなく、好事例集の作成といったところを進めているということでございました。公表につきましては、１０月の功労者表彰といった場できちんと皆様のところに周知がされると考えているところです。","id":"exchange-070"},{"speaker":"若林委員","kind":"質問・要望","question":"要望もたくさんあり、まさに地元の青果事業者等から丁寧に話を聞いてくださいということが、大きく１つあったと思います。そういった内容を、複数になりますが、概要を教えていただきたい。","respondent":"石井学務課長","answer":"全品目の野菜を見たわけではありませんが、小松菜、白菜といったサンプル品の比較を実施いたしました。品川区が１０月に実施するということで、メールでできればその後の進捗状況をお聞かせいただきたいという連絡がございました。","id":"exchange-071"},{"speaker":"若林委員","kind":"質問・要望","question":"農林水産省ありきの話には、国の農水行政のまさに根本、発信基地なわけですから、バックアップというお言葉もあったというご説明でした。教育委員会も区長部局も含めてしっかりとそこら辺は進めていって、取り返せるものがあったら取り返してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-072"}]},{"id":"topic-09","title":"（仮称）子ども・若者活動拠点 事業説明会","agenda":"（仮称）子ども・若者活動拠点 事業説明会","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"その位置づけというか、違いを伺いたいと思います。先週の金曜日に説明会が行われたということですが、どういった意見や要望があったのか、伺います。","respondent":"柴田子ども施策連携担当課長","answer":"続きまして、説明会においていただいたご意見についてご報告します。今は敷地に屋外グラウンドがあり、今後つくらない予定なのですが、そういったものができるのかというご質問をいただきました。","id":"exchange-073"},{"speaker":"のだて委員","kind":"質問","question":"子どもたちも参加したのかどうかを伺いたいです。そうした中で、活動する場所、広いところで遊んだり動いたりできる場所は別に確保されていると考えていいのか、伺いたいと思います。","respondent":"柴田子ども施策連携担当課長","answer":"こちらは建設に関することですので、１０月の説明会でお答えいたします、具体の説明は専門の担当からするということでご理解いただきました。資料の右側の１階部分にアリーナ（体育館）をつくらせていただき、あとは２階に多目的ホール、比較的広いスペースを予定しております。","id":"exchange-074"},{"speaker":"のだて委員","kind":"質問","question":"これは体育館の１階部分だけということですか。そうなった経緯を伺いたいと思います。","respondent":"柴田子ども施策連携担当課長","answer":"２点目のご質問の３,５００m2ですが、以前のご説明から大幅に減った理由といたしまして、大きく２つあります。１点目は当時、地下階の設置も検討しており、それが３,５００m2に入っていました。","id":"exchange-075"},{"speaker":"のだて委員","kind":"質問・要望","question":"地下階ができなくなった理由を伺えればと思います。今回４階部分が結構後退しているので、どれだけ取れるのかというのはあると思いますが、広場があるのかを確認させてほしいと求めました。","respondent":"柴田子ども施策連携担当課長","answer":"屋上に関しましては、３階と４階、資料の右側の図に少し緑色に塗ったエリアの２か所に屋外のリラックススペースを配置しております。子どもへの説明会の参加といった周知は、折を見てしっかりとやっていきたいと考えています。","id":"exchange-076"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"渡部前議員もこの１８歳以上の居場所というのをずっと訴え続けて、どうやっていくのかというのは非常に私も興味があります。そこを説明を求めました。","respondent":"柴田子ども施策連携担当課長","answer":"資料の図面の１階にありますが、こちらは誰でも利用できるフロアとしておりまして、こちらで地域の方がゆっくりしていただく。ただいま委員からアドバイスいただいたボランティアといったところを共有する場にはなると思いますので、検討してまいりたいと考えています。","id":"exchange-077"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"好事例を１つでも教えていただきたいのと、ここの南品川の伝統というか文化は、やはりおみこしなのです。そういったところに具体的な計画があるのか、説明を求めました。","respondent":"柴田子ども施策連携担当課長","answer":"その委託の事業者につながっている大学生のボランティアが５０人ぐらい、団体でして、得意分野がそれぞれ実にいろいろなのです。せっかくつくる施設、新しいものですから、子どもたちが来たいという思いを大きく抱いてくれるような準備を今後していく考えです。","id":"exchange-078"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"やはり子どもたちが、ここが居場所なのだと感じることができるというのが非常に大切なことで、それがこの施設に求められていると思っています。いかがか尋ねました。","respondent":"柴田子ども施策連携担当課長","answer":"子どもたちの参画は、ぜひ私どもも実現したいと考えています。ぜひ子どもたちのやりたいというものを実現させることができる、後押しができる施設にしたいと考えています。","id":"exchange-079"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"段階的に分かれていて、若者がいるという部分があると、階ごとでばらついてしまうことになってくるものではないでしょうか。例えば臨時親子サロンなど、代替の施設をどこかにやっていこうという計画があるのか、最後に説明を求めました。","respondent":"柴田子ども施策連携担当課長","answer":"計画段階から代替地を模索してきたのですが、適地が見つかっておりませんで、代替の場所を特別に設ける予定はございません。冒頭にありました階ごとで世代間交流といったものも、貴重なご意見として検討します。","id":"exchange-080"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今どうするというのが具体的にあれば、どういう活動で動いていただくかは、今分かるところで結構です。まだ先ですから、なければあれですけれど。","respondent":"柴田子ども施策連携担当課長","answer":"近くの大学のボランティア登録が半分ぐらいを占めておりましたので、まず区内大学にもご協力いただけないかというのは考えていきたいと考えています。そういった関係性で、子どもたち同士の、少しお兄さん、お姉さんも含まれますが…","id":"exchange-081"},{"speaker":"高橋（し）委員","kind":"提案","question":"リバースメンターの高校生の提案の中に、１年間ばっちりやりましょうでなくて、参加しやすい。これは要望でお願いしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-082"},{"speaker":"横山委員","kind":"質問","question":"管理運営の部分の、令和８年度頃までにどういった形でやっていくかというのは検討を進めると構想には書いてあります。その体制について、現時点でどのように考えているのか、説明を求めました。","respondent":"柴田子ども施策連携担当課長","answer":"それ以上の子ども・若者に関しては、午後８時ないし９時までといった形で検討を進めております。ただ、直営のところも見たいということで、そちらも併せてしっかりと検討を進めます。","id":"exchange-083"},{"speaker":"横山委員","kind":"質問・要望","question":"子どもたちにとっても参加のしやすい様々な形を考えていくときには、コーディネイト機能、ハブの役割が大変重要になってくると思います。どういった管理運営方法を取るにせよ、そうした部分の機能をしっかり担保していただきたいとお願いをしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-084"},{"speaker":"筒井副委員長","kind":"確認","question":"今回、子ども・若者活動拠点ということで、１８歳以降の方の居場所の確保ですが、まず、若者の定義ですが、２０代、２９歳までということでいいのか。厳密に若者が使えるフロアは入室制限していくのかということを、まず確認したいと思います。","respondent":"柴田子ども施策連携担当課長","answer":"まだ、検討段階ではありますが、２０歳代の若者までという形で検討しております。３階、４階は子ども・若者が年齢層を問わず使えるのですが、この点はしっかりと利用者に認識してもらって使い分けをしていきたいと考えております。","id":"exchange-085"},{"speaker":"筒井副委員長","kind":"確認","question":"確認を含めてですが、残りの２４館の児童センターも、こうした子ども・若者活動拠点にしていくのか。その辺りのお考えを説明を求めました。","respondent":"柴田子ども施策連携担当課長","answer":"ほかの２４館の児童センターも同様になるのかにつきましては、現時点では、まだどのようになっていくかは決めておりません。未定ということでお答えします。","id":"exchange-086"}]},{"id":"topic-10","title":"その他","agenda":"その他","exchanges":[{"speaker":"高橋（し）委員","kind":"質問","question":"すまいるスクールがあったらすまいるスクールをどうするかというところで、３０分待っていてというところもあり、混乱したと伺っています。統一するのがいいか、学校ごとの判断かというのがあると思いますが、その辺りはどのようにお考えか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-087"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"もう１つは、要望です。これは要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-088"},{"speaker":"のだて委員","kind":"質問","question":"大崎図書館の分館がまだ休館状態ということですが、今後再開の見通しはどうなっているのか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-089"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/200387?Template=document&Id=7161#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":59879,"voices":272}},{"id":"r07-20250922-5","meetingId":"r07-cm09","date":"2025年9月22日","dateIso":"2025-09-22","committee":"総務委員会","time":"午前１０時００分～午後 ３時１３分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を106件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"その後電気工事、設備工事に入ると思うのですが、なぜこれを議案として一緒に今回やらなくてはいけないのでしょうか。人件費が上がりましたということで、そのままどんどん工事も何もしないのに、またここで金額の改定というのが行われてしまうのではないか尋ねました。","respondent":"佐藤経理課長","answer":"区としましては発注にあたっては、そういったもので予定価格を計上するなどしまして、不調にならないような形で対策は取っております。ただ、応募しやすい入札条件というところは、引き続き検討しつつ対応していきたいと考えております。","id":"exchange-001"},{"speaker":"須貝委員","kind":"質問","question":"そして、一応規約としても２者以上やはり入札をするような仕組みを品川区も取っているわけですから、それについてもう一回だけ教えてください。そして、この１００億円という額なのですが、私はかなり高いと思うのですが、これは国や東京都からの補助金というのは何か出てくるのか尋ねました。","respondent":"佐藤経理課長、東野福祉計画課長","answer":"最初の２点について、私のほうからお答えします。その前の参加できる条件で発注しているかどうかというところは区の責任ですので、そこは担保していきたいと考えております。 委員のほうからご質問がありました補助金なのですけれども、東京都の補助金のほうが入る予定となっております。詳しい資料が今手元にはないのですが、一定程度の補助金が入ってくるということです。","id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"当然返済というのもあるわけであって、そこがどのように変わってくるのかというのを、これから財政も含めて全体を見たときに本当に大丈夫ですか。その辺はどのようにシミュレーションしているのか説明を求めました。","respondent":"佐藤経理課長","answer":"設計労務単価は１３年連続で伸びているというところですので、ただ制度に沿って、インフレスライドという形で契約変更が必要だろうと考えております。これを越える場合は補正予算なり、そういった形で予算の担保をした上で契約変更をしていくということになろうかと思います。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"シミュレーションをしているのですかと聞いているのです。令和７年度は歳入を高く見積もって予算を立てていますけれども、工事費が軒並み上がっているという状況になると、それはどう考えているのか尋ねました。","respondent":"佐藤経理課長","answer":"どういう手順を考えているかというところだと思いますけれども、その範囲内で予定価格を立てて入札に移行しているということです。ただ、施設の総合計画等も立てているところですので、そういったところで区としては把握しているということだと思います。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問・要望","question":"計画的にこれをやると言っても、債務負担行為という形でやっていくけれども、それで行くのかどうか。何か起きたときにどういう対応をしていくのかというお考えは多分あると思うので、そこの見通しを教えてほしいと求めました。","respondent":"加島財政課長","answer":"それはやはり財政課としては、今回は基金を投入して、この小山台住宅跡地高齢者福祉施設等の施設整備が必要だと認めたところです。小山台住宅跡地高齢者福祉施設等につきましては、今回起債はしておりませんので、償還が滞るということにはならないということです。","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問","question":"今、ここに出ている数字というか契約の数字を足し合わせると約１００億円になってくると思うのです。この総事業費としては、この施設の総事業費というのはどれくらいになるのか、分かれば伺いたいと思います。","respondent":"長尾施設整備課長","answer":"今ご質問いただいた駐車場・駐輪場といった外構に当たる部分だと思いますが、こちらの整備については、その建築工事の契約の中に含まれておりますので、それも含めての金額となっております。","id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"では、ここに出ている契約金額を全部足し合わせた数字が総事業費ということになるのかということと、あと、北棟と中央棟と南棟の３つに分かれていると思うのですけれども、それぞれの建築費というのが分かれば教えていただきたいと思うのですが。","respondent":"長尾施設整備課長","answer":"各棟の整備費で幾らぐらいになるかというところですが、ざっくり感覚的には延べ面積の比率におおむね比例すると捉えていただければと思います。南棟で２４％程度というような面積の内訳になっておりますので、金額もおおむねそれに比例してくると捉えていただければと思います。","id":"exchange-007"},{"speaker":"石田（ち）委員","kind":"意見","question":"私たちも過去に特養ホームを建てるのに、資材高騰も含めて、人件費等も含めて大分それと変わってきていると思うのです。今回ここは特養ホームとしてはショートステイも含めると８８名分ということで、今、分かりますかとの意見を述べました。","respondent":"長尾施設整備課長","answer":"今回建物が３棟ありまして、３棟ともその用途が混在して複合建物になっておりますので、今、委員がおっしゃっていたようなこういう建物を建てる場合にどのぐらいのコストがかかるかという目安を出そうとすると、なかなか難しいと感じております。","id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"特に法月建設は令和１１年９月まで源氏前小学校の改築工事に今入っています。その辺について、ご見解を聞かせてください。","respondent":"佐藤経理課長","answer":"建築でいけば５者ＪＶということで、それぞれ一定の割合で出資いただいて一つのＪＶを構成いただくというところを要件にしております。特段問題にはしていないところですので、発注の条件に合っていれば、資格としては問題ないと考えております。","id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"それだけの期間と人員が配置されるわけですから、そういうところを見たら私は非常に違和感を覚えるのですが、もう一度だけ教えてください。その辺はどうなのか尋ねました。","respondent":"佐藤経理課長","answer":"２点目の区内の事業者が対応できるかどうかというところですけれども、順次少なくなっていくというところです。技術者ですとか実際の工事ですとか、そちらを分担していくということですので、そのＪＶの中で役割分担ができているということで認識しております。","id":"exchange-010"},{"speaker":"須貝委員","kind":"確認","question":"それも、技術者の配置が困難だと明確に書かれているわけですね。やはりきちんと品川区としてもそこら辺は確認して、そして変な疑惑を持たれないように、私はしっかりやってほしいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問","question":"今の関連で少しお聞きしたいのですが、どういう決まりがあるのかということと、区は知らなくてもいい範疇なのですか。その５者であれば５者がある程度分かっている、けれども多分出資額が大きいというか、そういうのは区のほうは情報を持っていないのか尋ねました。","respondent":"佐藤経理課長","answer":"１点目のＪＶを構成する事業者数というところですけれども、そういったものを勘案して、発注時に決めているです。ＪＶの中の役割分担ですけれども、その協定書を区のほうには提出いただいて、出資割合に応じて工事の責任を持っていただいているというところです。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"だって極端な話、１者でできれば１者でいいわけではないですか。それは疑いをかけられてもしようがないのではないかなと聞いていて思ったのですけれども、その辺はいかがなのか尋ねました。","respondent":"佐藤経理課長","answer":"ＪＶの考え方ですけれども、そういった観点からＪＶを組んでいただいて、受注いただくということを定めております。１者ができればいいではないかというところでいくと、区としましてはそういった意味でＪＶを採用しているということでご認識いただければと思います。","id":"exchange-013"},{"speaker":"西本委員","kind":"質問","question":"初めから何者などと決めたら、無理矢理その５者は５者で募るのではないのですか。やっているとは言いませんが、そういう疑いをかけられても仕方がない、そう見られるような状況になっていませんかということはいかがか尋ねました。","respondent":"佐藤経理課長","answer":"全体の事業の中でそれだけ区内の事業者が請けているということで、いわゆる育成ですとか受注機会の確保が図られてということになろうかと思います。そちらに関しては、区としては区内事業者の受注機会の確保に重点を置いているということでご認識いただければと考えています。","id":"exchange-014"},{"speaker":"西本委員","kind":"質問・要望","question":"例えば５者と言ったときに、もしかしたらかぶっている可能性だってあるではないですか。どういう資金繰りをしていくのかというのを、もう一回教えてほしいと求めました。","respondent":"石田（秀）委員長","answer":"答えてもらうけれども、西本委員、これは契約の案件なので。質疑が行ったり来たりはやめてもらいたいと思います。","id":"exchange-015"},{"speaker":"西本委員","kind":"質問・要望","question":"そこだけは言わせてほしいと求めました。資金繰りをお答えいただければ。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"石田（ち）委員","kind":"質問","question":"その７０６億円からすると、この６８５億円だと低いのですけれども、この７０６億円と６８５億円の算定を伺いたいと思います。","respondent":"小林新庁舎建設担当課長","answer":"その後、引き続き実施設計のほう、あるいは積算のほうを進めていく中で、さらなる削減等ができないかどうかも含めて検討してきたところです。委員ご案内の都市計画関連施設がこの中に入っているかいうご質問につきましては…","id":"exchange-017"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。では、その約６８５億円、これが新庁舎建設総事業費ということで良いのか伺いたいと思います。","respondent":"小林新庁舎建設担当課長","answer":"総事業費という定義をどこにするかということはあるかと思いますが、要は建物を造るにあたっての事業費は確かにこの金額です。例えばこういう机であったりとか椅子であったりとか、これは別途扱いになりますので、建物を造る費用としてその金額とご認識いただければと思います。","id":"exchange-018"},{"speaker":"山本委員","kind":"質問・要望","question":"それから支払いの原資となる支払い調達、今回の分に対してどうされるかというところ、その調達の準備の状況について教えてほしいと求めました。それから、金利負担が発生してくると思うのですけれども、その現状の転嫁などが確認されていれば、詳しく説明を求めました。","respondent":"小林新庁舎建設担当課長、加島財政課長","answer":"私のほうから、前段の部分についてご質問に回答いたします。その資金の原資ですが、合わせて今回そのお金を充てるということになってありますので、その比率に応じて今回お支払いという形になろうかと思います。 令和７年度の調達予定ですけれども、大体全体工事費の１０％をお支払いすることになりますので、国との負担金を除きますと約５３億円となります。そのうち特別区債で４０億円…","id":"exchange-019"},{"speaker":"山本委員","kind":"確認","question":"４０億円今年度起債されるということで理解いたしました。それに変更がないかということの改めての確認と、返済原資を確保するということで、その辺りまた改めて確認させてください。","respondent":"加島財政課長","answer":"令和７年度の調達につきましては、当初予算でお示したとおり、５年満期一括償還を考えております。令和６年度まで庁舎整備基金のほうに３０億円を積み立ててまいりましたが、元金を返済しつつ借換えを行っていくという予定です。","id":"exchange-020"},{"speaker":"山本委員","kind":"質問・要望","question":"５年ごとの償還を考えていると理解しているのですけれども、区としてのご見解はいかがでしょうかというのをお聞きしたいというところになります。それから、ほかの委員の方からも既にご要望ございましたけれども、財源の長期的な展望についてになります。","respondent":"加島財政課長","answer":"それから、ご意見を受けまして、こちらのほうでも比較・検討というのを改めて行ってみました。減債基金から返済を行ってまいりますので、結果的には満期一括償還のほうが利子総額は安いということになっております。","id":"exchange-021"},{"speaker":"須貝委員","kind":"質問","question":"品川区はこれから建てるにあたって、そういう便宜に対して品川区も受けられるのか、その辺はどうなのですか。逆に品川区がやるときには便宜をいただくというのが一般常識だと私は思うのですが、それだけ説明を求めました。","respondent":"泉広町事業調整担当課長","answer":"土地区画整理法上の使用収益が開始されてないところでのお話になってありますので、もう一つ、現在協議を進めているところです。今のところ使わせていただくような方向性を持って、協議をさせていただいているです。","id":"exchange-022"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ゆっくり住民参加と情報公開で進めるべきだと求め続けてきましたけれども、結局この開発優先に庁舎の建て替えも一緒に進められてきたと。そして防災的にも拠点となる庁舎の建設を求め続けてまいりましたけれども、結局超高層、６０ｍを超えるという超高層になりました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"須貝委員","kind":"質問・要望","question":"そしてほかに遠慮しないでやはり正々堂々と主張すべきことは主張して、ＪＲに対しても主張して、立派な建物を建ててほしいと求めました。賛成します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"西本委員","kind":"意見","question":"やはりこの透明性のある内容であってほしいということと、ぜひご検討願いたいというお願いをして、賛成いたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"}]},{"id":"topic-02","title":"第１０２号議案、職員の配偶者同行休業に関する条例の一部を改正する条例","agenda":"第１０２号議案、職員の配偶者同行休業に関する条例の一部を改正する条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"今回の改正としては、配偶者同行休業取得者の代替職員の採用方法に関するということなのですけれども、その配偶者同行休業取得者というのが現在いらっしゃるのか、どれぐらいいるのか、分かれば説明を求めました。","respondent":"宮尾人事課長","answer":"配偶者同行休業ですけれども、実際の取得者ですが若干名、数名おります。過去３年間、令和４年度、５年度、６年度の３か年度合計で５名の取得実績がございました。","id":"exchange-026"},{"speaker":"石田（ち）委員","kind":"質問","question":"３年間で５名ということで若干名ということで、そのように配偶者の同行休業を取得された方の代替職員というのが、この間は採用できなかったものを、できるようにするということなのでしょうか、伺います。","respondent":"宮尾人事課長","answer":"先ほど申し上げました３か年度で５名ですけれども、この５名に対しては、全て職員の配置替えによって代替の職員を手当いたしました。今回はその職員の配置替えによるという選択肢に加えて、臨時的任用や任期付の職員も採用できるようにする、選択肢を増やすという条例改正です。","id":"exchange-027"},{"speaker":"松本委員","kind":"質問","question":"申請期間の間にもう退職してしまわれる方と、申請期間の終わる直前にもう退職してもう戻ってきませんよというパターンが考えられると思うのですけれども、その場合の今回の臨時の方たちの扱いというのはどうなるのか尋ねました。","respondent":"宮尾人事課長","answer":"ですので、今回提案をさせていただいている任期付採用あるいは臨時的任用職員の方も、任期はしっかり全ういただけるのではないかと考えています。ただ、その点は早め早めに情報提供をいただいて…","id":"exchange-028"},{"speaker":"松本委員","kind":"質問","question":"あくまで申請期間の任期を限度とするとなっているので、もともと海外にいる方が辞められてしまったら、そこでもう任用は終わりと考えるべきなのか尋ねました。","respondent":"宮尾人事課長","answer":"職員が欠員であるという状態に変わりはありませんので、そのご本人に不利益が被らないように、どのようなことができるかというのはそのときにしっかり対応したいと考えています。","id":"exchange-029"},{"speaker":"西本委員","kind":"質問","question":"配置替えというのはどういう意味なのでしょうか。そこをちょっと説明を求めました。","respondent":"宮尾人事課長","answer":"その場合は、通常定期の人事異動の中で、そこに新たに１人職員を異動によって配置をするというような形が考えられます。それこそ文字通り配置替えで、どこかからどこかへ職員を年度途中の異動によって補充をするというような対策を取らせていただいております。","id":"exchange-030"},{"speaker":"西本委員","kind":"質問","question":"そうすると、配置替えということになるわけで、そうすると継続したい、その職場に復帰ということが条件だと思うのです。だからこういう同じ仕事の部署に復活したいというのはできないということになるのか尋ねました。","respondent":"宮尾人事課長","answer":"制度上できないというものではございません。逆に、その場合は本人のキャリアをどう考えるかというところで、総合的に考えるようになると思います。","id":"exchange-031"},{"speaker":"西本委員","kind":"質問・要望","question":"そこは丁寧にしていただけるというお話なので、本人のご意向を聞いてという形で、ぜひ丁寧に対応してほしいと求めました。１年を超える任用はできないという、もう既に任期付採用なのか臨時的任用なのかということでの対応が決められるという認識でよろしいか尋ねました。","respondent":"宮尾人事課長","answer":"ただいまの質問、委員のお見込みのとおりです。１年を超えるとなりますと、任期付職員をベースに考えすると、このような考え方です。","id":"exchange-032"},{"speaker":"山本委員","kind":"質問","question":"この条例は、働く職員の方々の選択肢が増えるというところで、良いと考えています。今回その改正によって、そういった応募がなされるような状況なのかどうかというのを、現状とか見通しとかを教えてほしいと求めました。","respondent":"宮尾人事課長","answer":"ただ、速やかに採用募集の活動に入らせていただいて、様々な広報媒体を使って募集活動をしっかりと行ってまいりたいと思います。ですので、早め早めに職員からお申出をいただいて、こちらも早め早めに対策を取るというようなことが肝要になってくるかなと思います。","id":"exchange-033"},{"speaker":"須貝委員","kind":"質問","question":"ただ１点、これは収入がないですけれども、やはり払い続けていくということでしょうか。品川区内にも民間の様々な企業、事業所がありますが、大まかに品川区内で同様の制度を採用しているというところなども何社か把握されているのか尋ねました。","respondent":"宮尾人事課長","answer":"職員の休業期間に関しましては、事業主としての一定の社会保険料負担というのは発生をいたします。それから、民間企業の導入例ですけれども、詳細に調べたわけではありませんが、同様の制度がある企業もあるというふうには認識をしています。","id":"exchange-034"}]},{"id":"topic-03","title":"第１０３号議案、一般職の任期付職員の採用に関する条例の一部を改正する条例","agenda":"第１０３号議案、一般職の任期付職員の採用に関する条例の一部を改正する条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"は優れた識見を有する者という方を、どういう目的で、どういう人をどこに採用しようとしているのか伺いたいと思います。それで、またこの専門的な知識経験があって優れた識見を持つというのは、どういう人たちのことを言うのか、そこも説明を求めました。","respondent":"宮尾人事課長","answer":"今採用予定ですけれども、区はＤＸの分野でさらなる人材を確保していきたいと考えていますので、次年度以降の採用を予定しています。具体的には、技術革新がもう日進月歩の世界ですので、そちらの方面に知識経験が豊かな方を採用したいと思ってあります。","id":"exchange-035"},{"speaker":"石田（ち）委員","kind":"質問","question":"今回品川区の場合はＤＸの関係でということでしたけれども、それ以外にこの専門的な知識経験、優れた知見を有する者というのは、どういう人のことを指すのか説明を求めました。","respondent":"宮尾人事課長","answer":"国などの資料によりますと、例示としては今申し上げたＤＸのほかに、例えば法務部門、あとは医師、こういった方々、専門職の方を採用する例などが掲げられているです。","id":"exchange-036"},{"speaker":"石田（ち）委員","kind":"質問","question":"このＤＸのところにも一般任期付職員という方がいるのか、どこにいるのか伺いたいです。それで、今回この特定任期付職員採用で何人ぐらいを採用しようと思っているのか伺います。","respondent":"宮尾人事課長","answer":"こちらのデジタル、ＤＸの関係ですと、係長級も含めて全部で３名、一般の任期付採用として配置をさせていただいているところです。なお、先ほど申し上げた来年以降の採用ですけれども、人数としては１名を考えているところです。","id":"exchange-037"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。こういった専門の方が集まってこないのか伺いたいと思うのと、今、そこら辺はどのように考えているのかお伺いしたいと思います。","respondent":"宮尾人事課長","answer":"ご提案のこの７段階の給料表を適用しますので、こちらによって待遇面ではかなり良くなっているのではないかと、これはもう特別区で共通の給料表です。ですので、こちらをしっかりと募集の際にはアピールをさせていただいて…","id":"exchange-038"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、やはり普通のというか一般職員の待遇では、こういう専門的な方は集まりづらいということになるということか尋ねました。","respondent":"宮尾人事課長","answer":"やはりしっかりとした待遇面を用意するべきという考え方もあると思います。ですので、今回この制度をしっかり活用して、しかるべき人材を確保したいと考えています。","id":"exchange-039"},{"speaker":"松本委員","kind":"質問","question":"この別表の第１のほうの一番高い方で、今回の改正案の第４条３項を拝見すると、さらに上に行けるというふうな規定になっているかと思うのです。すみません、その後の６号級の給料月額との差額に、これで上限としてはどのぐらいの額になるのかというところを教えていただいていいか尋ねました。","respondent":"宮尾人事課長","answer":"８を設定するとした場合に、その差額というのは１から２の段差の部分を使って計算をするというその計算の仕組み・考え方を示しております。この中のどこかで決めたいと考えています。","id":"exchange-040"},{"speaker":"松本委員","kind":"質問","question":"そうすると、大体これで一番上の方で、年収で言うとどのくらいになると考えればいいでしょうか。お願いいたします。","respondent":"宮尾人事課長","answer":"あくまでも概算というところはちょっとご容赦いただきたいのですが、一番上の７号級で、大体年収として１,６００万円程度の待遇になるかと想定をしております。","id":"exchange-041"},{"speaker":"西本委員","kind":"質問","question":"これ、年齢は決まっていないのですか。下の給与のほかに、具体的にどういう方々がこれに興味を持ってくれるのかと率直に思ったのですけれども、どういう方を想定されていますか。","respondent":"宮尾人事課長","answer":"実際にまず年齢制限ですけれども、委員お見込みのとおり、特に制限というものはございません。一定程度ご自身の中で職としてはもう一旦リタイアされた方で、ぜひ現役時代の知識経験を活かしたいというような方なども当然想定をしています。","id":"exchange-042"},{"speaker":"西本委員","kind":"質問","question":"そういう方に私は来てほしいという立場です。その辺はいかがか尋ねました。","respondent":"宮尾人事課長","answer":"まさに委員おっしゃるとおりで、こういう変化の早いテーマに対してしっかりと仕事をしていただける方、こういった方を採用したいと考えています。今のデジタルを所管している部署とも意見交換などをさせていただきながら…","id":"exchange-043"},{"speaker":"西本委員","kind":"質問","question":"かなり優秀で将来性があるといった場合に、５年という期限ではなく、別の制度を使えないかなと。どういう人かは分からないですけれども、そういうのが出てくるのではないかと思うのですけれども、そういうのは考えておられないのか尋ねました。","respondent":"宮尾人事課長","answer":"まさに任期付きの職員の方を考えているわけですけれども、その５年を終えてもなお品川区で引き続き働いていただきたいと、この辺はしっかりと考えていきたいと考えています。","id":"exchange-044"},{"speaker":"西本委員","kind":"質問・要望","question":"最後に少し確認だけ。任命権者と書いてありますが、この任命というのは誰が任命権者なのか尋ねました。","respondent":"宮尾人事課長","answer":"こちらは、品川区の場合は区長になります。","id":"exchange-045"},{"speaker":"山本委員","kind":"質問・要望","question":"今回の高度な専門的な知識・経験を保有する人材を採用しやすくなるというので、良い条例改正だと考えています。例えば現場のＤＸ推進からの要望だったのか、あと２３区での実施状況、調べられていたらお教えください。","respondent":"宮尾人事課長","answer":"区としても、ツールとしてこういう制度が必要かなというところに、ＤＸが今回必要かなと判断をさせていただいているです。２３区の状況ですが、大体今４分の１程度の区でこの制度を既に導入をしている、あるいは導入を考えているという情報は持ち合わせているところです。","id":"exchange-046"},{"speaker":"山本委員","kind":"質問・要望","question":"４分の１のところに入っていて、トップランナーとしてこうやって積極的に進められているということで、良いなと思いました。ぜひ良い優秀な方を採用して、区政の品質保持を進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"},{"speaker":"須貝委員","kind":"質問","question":"その人を採用するには、より高度な知識を持った人でないと、その人の能力というのは分からないではないですか。その辺についてちょっと説明を求めました。","respondent":"宮尾人事課長","answer":"これはいきなり５年間としてお願いするということではなくて、例えば最初は２年間、プラス後で３年間というふうに任期は分けてやる予定です。加えて、任期の途中でも勤務評価というのは行いますので、しっかりと良い方を採用できるように努めてまいりたいと思います。","id":"exchange-048"},{"speaker":"須貝委員","kind":"質問・要望","question":"全然分野が違いますからね。だから、そういうところを判断して、こういう制度を実施するなら、もう本当により適格な人を選ぶような工夫をしていただきたいと私は思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-049"},{"speaker":"塚本副委員長","kind":"質問","question":"何か部下がいる、一つの組織をまとめて仕事をしていくという、そういうイメージで採用される方なのですか。管理職で最初は課長だったのが部長になったりするということもあり得るのかとか、その辺はどういう扱いになっていますか。","respondent":"宮尾人事課長","answer":"それから、昇給とか昇格に関する考え方ですが、任期の途中で給料が上がるとかという制度ではございません。もうこれでお願いしますというふうにもう固定でお願いするような採用形態になってあります。","id":"exchange-050"},{"speaker":"塚本副委員長","kind":"質問","question":"今みたいな話、いわゆるジョブ型の仕事をお願いするというのですか。特にＤＸとかの分野になってくるとそことの違い、今回のこの特定任期付職員の採用で期待するところの違い、そこのところを教えていただけますか。","respondent":"宮尾人事課長","answer":"例えば考え方を構築していただく、それから情報収集して、それを大事なのは庁舎の中の私どもを含めて他の職員にフィードバックをしていただく。基本的な考え方、ここはやはり委託とは少し趣が異なってくるのかなと考えております。","id":"exchange-051"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"公務員は安定した身分保障の下で働くべきであると考えていますが、今回、国が進めるＤＸに各自治体が一緒に進めているという状況でもあります。今回はＤＸの分野に１人ということですので、これは安易に対象を広げたりしないように求めておきながら、賛成したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-052"},{"speaker":"石田（ち）委員","kind":"意見","question":"申請しているのが約７,０００件なのか、この小規模非住宅用地が約７,０００件なのか、ちょっとそこが分からないのですがとの意見を述べました。","respondent":"宮澤税務課長","answer":"今のご質問の中で、２番の小規模非住宅用地の減免措置を受けているのが品川区で約７,０００件と聞いております。","id":"exchange-053"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。資料記載の３つの軽減措置等を受けているのがこの件数ということで、まだ申請されていない方もいるであろうと考えるのか、伺いたいと思います。","respondent":"宮澤税務課長","answer":"これは固定資産税および都市計画税が都の税目になっておりまして、賦課徴収は東京都が行っておりますので、その申請に関しては東京都のほうの分野となっております。","id":"exchange-054"},{"speaker":"石田（ち）委員","kind":"質問","question":"なので、対象であるならば、ぜひ多くの皆さんが受けられるようにしたほうが良いということで質問をさせていただきました。そこは致し方ないですけれども、私もこれは恒久的な措置にするべきだろうと思っていますので、ぜひほかの委員の皆さんのご意見を伺いたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-055"},{"speaker":"西本委員","kind":"質問・要望","question":"これだけ長い期間同じ要望が出ているということを、東京都に対する意見書ということで毎回議会として意見書を出しているのですよね。どうなのか尋ねました。","respondent":"宮澤税務課長","answer":"東京都の独自減税策として実施しているところで、社会情勢を見極めながら総合的に判断して継続していると伺っているところです。例年、新年度が始まります前に都税全体の情報共有の中で、軽減措置が来年度もありますというのは都税事務所のほうからも伺っているところであります。","id":"exchange-056"},{"speaker":"西本委員","kind":"質問・要望","question":"その思いがあればそれに対して意見書を書くわけですから、出すわけですから、ぜひそういう要望というか。１点だけ、これは先ほども言いましたけれども、東京都の本庁、それからあとほかの自治体からは同じようなものが毎回出ているのか尋ねました。","respondent":"宮澤税務課長","answer":"他の自治体の状況については、把握していないところです。","id":"exchange-057"},{"speaker":"須貝委員","kind":"質問・要望","question":"ぜひ財政課長、今日は副区長もいらっしゃいますけれども、本当に区長ともども私はお願いに上がってほしいと思います。要望だけで終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-058"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"本日結論を出すで、採択で、意見書も提出ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-059"}]},{"id":"topic-04","title":"令和７年請願第１５号、インボイス制度の廃止をめざし、事業者の負担を軽減する経過措置を継続するよう求める意見書を国に送付することを求める請願","agenda":"令和７年請願第１５号、インボイス制度の廃止をめざし、事業者の負担を軽減する経過措置を継続するよう求める意見書を国に送付することを求める請願","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そしてフリーランス、事業者の負担を軽減する経過措置を継続するよう求めるというところに、私は大きな視点があるのではないかと思うのです。ぜひ一致してこの軽減措置を継続するということを求める意見書を上げないといけないのではないかと思うのですが、ほかの委員の方はいかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-060"},{"speaker":"西本委員","kind":"質問・要望","question":"ただ、これはここで言っても、品川区の現状はどうなのですかと言っても、この場所で聞けないのです。ただ、この意見書を求めると言われて意見書として出す以上は、品川区の現状をきっちりと調査というか認識を確認した上で。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-061"},{"speaker":"石田（秀）委員長","kind":"質問","question":"これは請願を総務委員会で上げているので、今みたいに質問をされるのを、私がこの内容のことだから止めるということはするつもりもないです。答える人がいないから。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-062"},{"speaker":"西本委員","kind":"質問","question":"品川区の実態はどこにあるのですかというのを聞いた上で、ではこの意見書でどういう内容のもので出していくか内容に関わってくる話なのです。判断するということはできると思うのですけれども、今は誰もいらっしゃらないので、判断がつかないです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-063"},{"speaker":"西本委員","kind":"質問","question":"どう判断するのですか。いかがですか、皆さん。","respondent":"石田（秀）委員長","answer":"区で支援をしてくれという話なので、その場合は地域産業振興課で答えられるから、それは答えましょうというので区民委員会で審査している。そのとおり、さっき言ったとおりなのです。","id":"exchange-064"},{"speaker":"西本委員","kind":"確認","question":"だから本来はこの趣旨の中身を確認させてもらって、いや、そういう意見書は要らないのではないかという議論になってくると思うのです。本当に申し訳ないです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-065"},{"speaker":"須貝委員","kind":"質問・要望","question":"ただ、もしそういうインボイスに対する制度の改善を国に求めるという意見書なら、この実務が大変だというのは公認会計士からも聞いています。経過措置として実施された２割特例、８割控除の継続を求める」というふうに、あまり適切ではないのかなと私は思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-066"},{"speaker":"山本委員","kind":"質問・要望","question":"で、制度によって実際に負担が増えている方々、その声が制度設計に適切に反映されるように求めていくことは必要であると考えております。支援制度の利用のしやすさも含めて、引き続き要望してまいりたいと考えております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-067"},{"speaker":"塚本副委員長","kind":"質問","question":"請願者が品川区の団体の方ですから、そういう意味から言うと、やはり国の制度としてどうなのですかということを捉えるべきだと思います。益税といったところの考え方をどうするかとか、今の会派としては適さないと考えますので、不採択でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-068"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひしていただきたいと要望はしたいと思うのですけれども、中小業者、意見を上げていくということはすべきだろうなと思います。そして直接声を聞けば、私はすべきだなと、この軽減措置を継続というところで意見書を上げていくべきだと思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-069"},{"speaker":"松本委員","kind":"質問","question":"本日結論を出すで、不採択でお願いします。理由は、政党の方針に反することになりますので願意には沿い難いと考え、不採択でお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-070"},{"speaker":"須貝委員","kind":"質問・要望","question":"各関係団体で相談窓口もありますから、そういうような形を取っていただいて、そういう方々に寄り添う対応をしてほしいと求めました。今回結論を出すということと不採択ということで、。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-071"},{"speaker":"西本委員","kind":"質問・要望","question":"数値化も必要だろうと思うし、今品川区の事業所がどうなっているのかというのは、やはり品川区の責任においてやるべき仕事だと私は思っているのです。こういうふうにしてほしいという要望はあり得る話だと思いますが、それがない以上、今回の請願については不採択とせざるを得ないというのが現状です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-072"}]},{"id":"topic-05","title":"令和７年請願第１６号、「消費税減税を求める意見書」の国への送付を求める請願","agenda":"令和７年請願第１６号、「消費税減税を求める意見書」の国への送付を求める請願","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私たちも減税を求めていますし、本当に多くの国民が求めていることに対して、どうやるかは様々あったと思うのですけれども。品川区内での中小業者の倒産件数というのがもし分かれば、ざっくりでも区のほうに１つだけ聞きたいと思いますが、いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-073"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"本当に暮らしが大変な中でさらにそこにインボイス制度が入ってきたわけですから、低所得者ほど重くのしかかるのはこの消費税になります。区民の暮らしを守る最大の経済対策だと私たちも思っていますので、消費税減税を求める意見書を上げていきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-074"},{"speaker":"須貝委員","kind":"質問・要望","question":"消費税減税を求める意見書を国に送付を求める請願、消費税１０％を減税すると、１００円のものが９０円になります。消費税減税を求める意見書、どうも全世界のドイツやフランスやそれからイギリスの動向を見ると、私は賛成できないという方向になりました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-075"},{"speaker":"山本委員","kind":"質問・要望","question":"消費税は国税の制度であり、国会・国政レベルで議論を深めて決定すべき問題であると認識しております。このような施策をしっかりと進めることを区に要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-076"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"それは違う種類でと思います。なかなかやはり減税だけを求めるというわけにはいかないのかなというのがありますので、請願の願意には沿えないということで、不採択でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-077"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"意見が出て国に求めるということは普通にありますので、国の制度だからできない、やらないというふうにはならなのではないかと思います。ですので、物価が下がらない以上、消費税は下げていくということはできることですですので、そこは国に求めていくべきだと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-078"},{"speaker":"松本委員","kind":"意見","question":"一方で、確かにさきの参院議員選挙では、食料品の消費税ゼロという公約を掲げていたように記憶しております。あまりどうなのかなという思いは自党に対してもあるところでありますが、今回の請願については願意に沿い難いと申し上げますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-079"},{"speaker":"西本委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。まとまるにはまだ議論も深まっていないし、まだ意見を求めるまでの品川区の意識にはなっていないのではないかと考えますので、不採択です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-080"}]},{"id":"topic-06","title":"令和７年陳情第３２号、公共施設内での労組加入、政党機関紙誌の勧誘等に関する調査及び助成を求める陳情","agenda":"令和７年陳情第３２号、公共施設内での労組加入、政党機関紙誌の勧誘等に関する調査及び助成を求める陳情","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"これは禁止されていることなのかちょっと伺いたいのと、この陳情理由の３個目の塊の「自治労、品川の加入率というのが分かれば教えていただきたい。２０２３年で自治労１７８人、全労連自治労連６１４人というふうにあるのですけれども、要はこれがこの数字なのかというのを確認したいと思います。","respondent":"宮尾人事課長","answer":"加入率につきましては、臆測の部分も入ってしまいますけれども、大体最近ですと２割から３割程度ではないかと捉えているところです。ですので、あと次の加入者数についても、私どもとしては把握をしていないというのが実情です。","id":"exchange-081"},{"speaker":"石田（ち）委員","kind":"意見","question":"なので、もし課題があるのであればしっかりと労組内で解決すべきだと思いますし、それがあった場合に対応していだだきたいということです。そこは自由な意思で選択されるべきものだと思っていますので…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-082"},{"speaker":"西本委員","kind":"確認","question":"この陳情項目の２番目にある政党機関紙とかの購読勧誘の有無、それは品川区においてあるのですか。その実態はどうなっているか、分かれば説明を求めました。","respondent":"宮尾人事課長","answer":"特に個々の職員がどういったものを購読しているのか、していないのかというところは、こちらのほうでは把握をしていないのが実際のところです。","id":"exchange-083"},{"speaker":"西本委員","kind":"質問","question":"ということは、庁舎の中でそういうものをやってはいけないとか、購読してはいけないとかいう明確なそういう決まりはあるのですか。ないという、個人の判断に任せられているという認識でよろしいか尋ねました。","respondent":"宮尾人事課長","answer":"そうですね。委員のおっしゃるとおり、特に購読しなければならないとか、逆に購読してはいけないとか、そういうことは一切ございません。","id":"exchange-084"},{"speaker":"西本委員","kind":"質問・要望","question":"それは対応すべきだと思うのですけれども、是正を求めるというのは、ちょっと行き過ぎの感じがいたします。以上、意見です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-085"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"１つだけ確認で、陳情の中で、庁舎管理規則というのに関してとか書いてある。それは一体どういうものなのかということだけ、教えていただきたい。","respondent":"佐藤経理課長","answer":"庁舎管理規則についてのお尋ねですので、経理課のほうでお答えいたします。今回の請願に言う政党機関紙に関して、販売したいので勧誘したいという申請を受けたことはあります。","id":"exchange-086"},{"speaker":"澤田委員","kind":"質問・要望","question":"不採択でお願いします。理由としましては、今後相談がもしあれば対応していただけるということでしたので、現在は陳情で求められていることは必要ないと考えます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-087"},{"speaker":"山本委員","kind":"質問・要望","question":"理事者のご説明から、現時点において品川区では陳情に記載のあるような問題が発生していないと判断いたしまして、本陳情は不採択といたします。しかし、区としてはそれを放置せずに、しっかりと調査対応して是正措置を講ずることを要望したいと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-088"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"先ほども述べたとおりです。ぜひ組合のほうで解決に向けて寄り添ってほしいと求めましたし、庁舎内、そうした場合もしっかりと対応していただけたらと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-089"},{"speaker":"松本委員","kind":"質問・要望","question":"組合に対してこういうことを求めていくというのは、こういうものを一律に求めてくるというのは、この陳情項目を読んでおりました。そういうこともありますので、調査すべきかと言ったら、基本的には調査すべきではありませんので、不採択と申し上げます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-090"},{"speaker":"西本委員","kind":"意見","question":"必要だったら、自分の判断の中で必要なことは入手してお勉強されるとか、把握をするとかいうことは止めてはいけないと思います。不採択でお願いしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-091"}]},{"id":"topic-07","title":"令和７年陳情第３７号、相談カルテ導入を要望する陳情","agenda":"令和７年陳情第３７号、相談カルテ導入を要望する陳情","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"けれども税務課とか、やはり多分税金の滞納等で相談しに行ったときに、その人その人ですごくいろいろな事情があるでしょうから、なので話す。私もこれはどうやったらいいのかちょっとあれですけれども、やられています、そうなっていない部分をどう考えるのかというのをお聞きしたいのです。","respondent":"與那嶺戦略広報課長","answer":"介護に関するところについても高齢者支援総合支援システムという形で、それぞれの相談者によって必要なニーズであるとか、あと。では今度はちょっと生活支援にかけてみたいなところに、税金であるとか、それを改めて所管と共有しながらご回答というところもやっておりますので。","id":"exchange-092"},{"speaker":"石田（ち）委員","kind":"質問","question":"しかも暮らしのこと、自分がどうしてこういう状況になったのかというのを話していくので、端的にはなかなか済まない内容とかもあると思うのです。今のままではちょっと足りないのではないのですかと思うので、さらにもう少し効率的にできるような仕組みをつくるべきではないか、意見です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-093"},{"speaker":"西本委員","kind":"確認","question":"けれども、その回された部署での情報を、やはりしっかりその担当の立場で確認しなければならないと思うのです。そうしないと出てこられないし、「これは誰に聞けばいいですか」みたいな、そういうような状況のものも多々あるのです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-094"},{"speaker":"須貝委員","kind":"質問・要望","question":"相談に来られた方に対しては、やはり相談者はいろいろ話を聞いてほしいということが第一だと思います。まして個人情報ということがありますので、今の状態でじっくりその相談者の話を寄り添って聞いてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-095"},{"speaker":"山本委員","kind":"質問・要望","question":"それぞれの情報に対して都度確認していくというプロセスも必要になるので、運用上非常に煩雑になる可能性があるかなというところです。以上、会派としてはその個人情報の観点から、全庁的な一元管理を求める本陳情には不採択といたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-096"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"必要なところ、求められるところではもう既に品川区でも所管の部署の中での情報共有ができているというところとが確認できましたし、課題があるのか。そういったことに照らすと、必ずしもその必要性というのは今見えてこないと思いますので、不採択でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-097"},{"speaker":"石田（ち）委員","kind":"提案","question":"どうできるかというのは様々あると思うし、私たちとしても提案的なものは今ないのですけれども、ぜひ検討していただきたいと思うのです。なので、それを一元化と言うのでしょうか、そうやってつなげていくというのは検討していただきたいというのが私たちの思いですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-098"},{"speaker":"松本委員","kind":"質問・要望","question":"利便性を求めていくというのは、同時にリスクも内在しているということかと思います。行政がどこまで一元管理するのかというところは極めて難しい問題があるという状況の中で、この要望に対して採択という意見は述べることができません。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-099"},{"speaker":"西本委員","kind":"意見","question":"担当部署によっても知らなければいけないことというのは多々違いますので、だからそこは人間のマニュアル的なところでの対応ができていたら。そういうのを徹底して改善をしていただければ、大分この問題というのは少なくなるのではないかと考えていますので…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-100"},{"speaker":"石田（ち）委員","kind":"意見","question":"マイナンバー云々のところは、デジタル化イコールマイナンバーだと思っていない私たちは、福祉の増進、そして区民の利便性向上というところでのデジタル化は進めていくべきという立場ですので、１人でも多く趣旨でも採択があればいいなと思いますので、趣旨採択でとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-101"}]},{"id":"topic-08","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"石田（ち）委員","kind":"確認","question":"なので、早く完成するといいなというところですけれども、令和１０年３月ということですね。やはり今回のこういう災害を受けて、これ、工期はこのまま今のところ変更はないということで確認させていただいて大丈夫か尋ねました。","respondent":"佐藤経理課長","answer":"今回変更にあたりましては契約金額のみでして、完成の時期について特段変更はございません。","id":"exchange-102"}]},{"id":"topic-09","title":"審査請求の却下の報告について（報告第３３号）","agenda":"審査請求の却下の報告について（報告第３３号）","exchanges":[{"speaker":"西本委員","kind":"質問","question":"その理由になるその資料といいますか内容のものが提示されなかったので、審理できずということでよろしいですか。それが受け入れられることは別問題なのですけれども、審理がちゃんとされていたという認識でよろしいか尋ねました。","respondent":"藤村総務課長","answer":"今回この督促処分に係る審査請求という形が整いましたので、資料の補正がされたという形になれば、こちらの要件が整ったということで、審査の遡上には上がったという形になります。","id":"exchange-103"}]},{"id":"topic-10","title":"本定例会の一般質問に係る所管質問ですが、本定例会の一般質問中、総務委員会に関わる項目","agenda":"本定例会の一般質問に係る所管質問ですが、本定例会の一般質問中、総務委員会に関わる項目","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"そこの確認と、それは同じ議員であるのになぜかというようなところを疑問に思いましたので、関連という形で質問したいと思います。ここでもハラスメントについての議論がなされましたので、その中で、今区側としてはどういう対応をされているのかということを確認したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-104"},{"speaker":"西本委員","kind":"確認","question":"しっかり議会に対して、ということは議員に対して説明責任はあるのではないかという観点で、確認したかった。確かにこの項目については、田中たけし議員の中には入っていなかったというのはあります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-105"},{"speaker":"西本委員","kind":"確認","question":"やはり会派に対して、個人・無所属の議員に対してということの説明を、どういう考え方で仕切っているのか。議会に対して、議員に対してどういう思い、どういう仕切りの中で説明をしているのかというのを確認したい。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-106"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/787454?Template=document&Id=7185#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":71768,"voices":338}}]);
